INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fdfef2c-bb0e-49eb-9d3e-a06bfd49b8d0', '臥病家園', '臥病家园', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["世上無名子，人間歲月賒。","縱橫策已棄，寂寞道爲家。","臥病誰能問，閒居空物華。","猶憶靈臺友，棲真隱太霞。","還丹奔日御，却老餌雲芽。","寧知白社客，不厭青門瓜。"]', '["世上無名子，人间歲月賒。","縱橫策已棄，寂寞道爲家。","臥病誰能问，閒居空物华。","猶憶靈台友，棲真隐太霞。","還丹奔日御，却老餌云芽。","寧知白社客，不厭青门瓜。"]', '诗', 'shi', '', NULL, '臥病家園 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6537bdd-3490-4a1c-a5f2-bf6be6c2c55b', '于長史山池三日曲水宴', '于长史山池三日曲水宴', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["摘蘭藉芳月，祓宴坐廻汀。","泛灩清流滿，葳蕤白芷生。","金弦揮趙瑟，玉指弄秦箏。","巖榭風光媚，郊園春樹平。","煙花飛御道，羅綺照昆明。","日落紅塵合，車馬亂縱橫。"]', '["摘蘭藉芳月，祓宴坐廻汀。","泛灩清流满，葳蕤白芷生。","金弦揮趙瑟，玉指弄秦箏。","巖榭风光媚，郊园春樹平。","煙花飞御道，羅綺照昆明。","日落紅塵合，车马亂縱橫。"]', '诗', 'shi', '', NULL, '于長史山池三日曲水宴 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e9f33f-c0dd-4c3e-a5af-e71c9e56cb07', '合州津口別舍弟至東陽峽步趂不及眷然有憶作以示之', '合州津口別舍弟至东陽峽步趂不及眷然有憶作以示之', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["江潭共爲客，洲浦獨迷津。","思積芳庭樹，心斷白眉人。","同衾成楚越，別島類胡秦。","林岸隨天轉，雲峰逐望新。","遙遙終不見，默默坐含嚬。","念別疑三月，經遊未一旬。","孤舟多逸興，誰共爾爲鄰。"]', '["江潭共爲客，洲浦独迷津。","思積芳庭樹，心斷白眉人。","同衾成楚越，別島類胡秦。","林岸隨天轉，云峰逐望新。","遙遙終不见，默默坐含嚬。","念別疑三月，經游未一旬。","孤舟多逸兴，誰共爾爲鄰。"]', '诗', 'shi', '', NULL, '合州津口別舍弟至東陽峽步趂不及眷然有憶作以示之 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33887bff-a836-4320-8f96-f9f4d34e34c2', '萬州曉發放舟乘漲還寄蜀中親朋', '万州晓發放舟乘漲還寄蜀中親朋', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["空濛巖雨霽，爛熳曉雲歸。","嘯旅乘明發，奔橈騖斷磯。","蒼茫林岫轉，絡繹漲濤飛。","遠岸孤煙出，遙峰曙日微。","前瞻未能眴，坐望已相依。","曲直多今古，經過失是非。","還期方浩浩，征思日騑騑。","寄謝千金子，江海事多違。"]', '["空濛巖雨霽，爛熳晓云归。","嘯旅乘明發，奔橈騖斷磯。","蒼茫林岫轉，絡繹漲濤飞。","远岸孤煙出，遙峰曙日微。","前瞻未能眴，坐望已相依。","曲直多今古，經過失是非。","還期方浩浩，征思日騑騑。","寄謝千金子，江海事多違。"]', '诗', 'shi', '', NULL, '萬州曉發放舟乘漲還寄蜀中親朋 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33678a13-152a-423c-ac13-c1f3b2164c88', '入峭峽安居谿伐木谿源幽邃林嶺相映有奇致焉', '入峭峽安居谿伐木谿源幽邃林嶺相映有奇致焉', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["肅徒歌伐木，騖檝漾輕舟。","靡迤隨廻水，潺湲泝淺流。","煙沙分兩岸，露島夾雙洲。","古樹連雲密，交峰入浪浮。","巖潭相映媚，谿谷屢環周。","路迥光逾逼，山深興轉幽。","麕鼯寒思晚，猿鳥暮聲秋。","誓息蘭臺策，將從桂樹遊。","因書謝親愛，千歲覓蓬丘。"]', '["肅徒歌伐木，騖檝漾轻舟。","靡迤隨廻水，潺湲泝淺流。","煙沙分兩岸，露島夾雙洲。","古樹連云密，交峰入浪浮。","巖潭相映媚，谿谷屢环周。","路迥光逾逼，山深兴轉幽。","麕鼯寒思晚，猿鸟暮声秋。","誓息蘭台策，將從桂樹游。","因书謝親愛，千歲覓蓬丘。"]', '诗', 'shi', '', NULL, '入峭峽安居谿伐木谿源幽邃林嶺相映有奇致焉 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f73293-7bd0-420d-bbc8-d66b53abddef', '入東陽峽與李明府舟前後不相及', '入东陽峽與李明府舟前後不相及', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["東巖初解纜，南浦遂離羣。","出沒同洲島，沿洄異渚濆。","風煙猶可望，歌笑浩難聞。","路轉青山合，峰廻白日曛。","奔濤上漫漫，積水下沄沄。","倏忽猶疑及，差池復兩分。","離離間遠樹，藹藹沒遙氛。","地上巴陵道，星連牛斗文。","孤狖啼寒月，哀鴻呌斷雲。","仙舟不可見，搖思坐氛氳。"]', '["东巖初解纜，南浦遂離羣。","出沒同洲島，沿洄異渚濆。","风煙猶可望，歌笑浩难闻。","路轉青山合，峰廻白日曛。","奔濤上漫漫，積水下沄沄。","倏忽猶疑及，差池复兩分。","離離间远樹，藹藹沒遙氛。","地上巴陵道，星連牛斗文。","孤狖啼寒月，哀鴻呌斷云。","仙舟不可见，搖思坐氛氳。"]', '诗', 'shi', '', NULL, '入東陽峽與李明府舟前後不相及 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5ef458-310a-449a-9d31-6175f68beafb', '同旻上人傷壽安傅少府', '同旻上人傷壽安傅少府', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["生涯良浩浩，天命固諄諄。","聞道神仙尉，懷德遂爲鄰。","疇昔逢堯日，衣冠仕漢辰。","交遊紛若鳳，詞翰宛如麟。","太息勞黃綬，長思謁紫宸。","金蘭徒有契，玉樹已埋塵。","把臂雖無託，平生固亦親。","援琴一流涕，舊館幾霑巾。","杳杳泉中夜，悠悠世上春。","幽明長隔此，歌哭爲何人。"]', '["生涯良浩浩，天命固諄諄。","闻道神仙尉，懷德遂爲鄰。","疇昔逢堯日，衣冠仕漢辰。","交游紛若鳳，词翰宛如麟。","太息勞黄綬，长思謁紫宸。","金蘭徒有契，玉樹已埋塵。","把臂雖無託，平生固亦親。","援琴一流涕，旧館幾霑巾。","杳杳泉中夜，悠悠世上春。","幽明长隔此，歌哭爲何人。"]', '诗', 'shi', '', NULL, '同旻上人傷壽安傅少府 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1388d7d7-5fd7-4b17-8adb-ea66d045dea9', '南山家園林木交映盛夏五月幽然清涼獨坐思遠率成十韻', '南山家园林木交映盛夏五月幽然清涼独坐思远率成十韻', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["寂寥守寒巷，幽獨臥空林。","松竹生虛白，階庭橫古今。","鬱蒸炎夏晚，棟宇閟清陰。","軒窗交紫靄，簷戶對蒼岑。","鳳蘊仙人籙，鸞歌素女琴。","忘機委人代，閉牖察天心。","蛺蝶憐紅藥，蜻蜓愛碧潯。","坐觀萬象化，方見百年侵。","擾擾將何息，青青長苦吟。","願隨白雲駕，龍鶴相招尋。"]', '["寂寥守寒巷，幽独臥空林。","松竹生虛白，階庭橫古今。","鬱蒸炎夏晚，棟宇閟清陰。","軒窗交紫靄，簷戶对蒼岑。","鳳蘊仙人籙，鸾歌素女琴。","忘機委人代，閉牖察天心。","蛺蝶怜紅藥，蜻蜓愛碧潯。","坐观万象化，方见百年侵。","擾擾將何息，青青长苦吟。","願隨白云駕，龙鹤相招尋。"]', '诗', 'shi', '', NULL, '南山家園林木交映盛夏五月幽然清涼獨坐思遠率成十韻 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c8b680e-ed52-4e35-ab8a-cf675c2e6c4e', '還至張掖古城聞東軍告捷贈韋五虛己', '還至張掖古城闻东軍告捷贈韋五虛己', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["孟秋首歸路，仲月旅邊亭。","聞道蘭山戰，相邀在井陘。","屢鬬關月滿，三捷虜雲平。","漢軍追北地，胡騎走南庭。","君爲幕中士，疇昔好言兵。","白虎鋒應出，青龍陣幾成。","披圖見丞相，按節入咸京。","寧知玉門道，翻作隴西行。","北海朱旄落，東歸白露生。","縱橫未得意，寂寞寡相迎。","負劒空歎息，蒼茫登古城。"]', '["孟秋首归路，仲月旅邊亭。","闻道蘭山戰，相邀在井陘。","屢鬬关月满，三捷虜云平。","漢軍追北地，胡騎走南庭。","君爲幕中士，疇昔好言兵。","白虎鋒應出，青龙陣幾成。","披圖见丞相，按節入咸京。","寧知玉门道，翻作隴西行。","北海朱旄落，东归白露生。","縱橫未得意，寂寞寡相迎。","負劒空歎息，蒼茫登古城。"]', '诗', 'shi', '', NULL, '還至張掖古城聞東軍告捷贈韋五虛己 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae094f36-9ed9-4687-b926-72e3053f2484', '題祀山烽樹贈喬十二侍御', '題祀山烽樹贈喬十二侍御', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["漢庭榮巧宦，雲閣薄邊功。","可憐驄馬使，白首爲誰雄。"]', '["漢庭榮巧宦，云閣薄邊功。","可怜驄马使，白首爲誰雄。"]', '诗', 'shi', '', NULL, '題祀山烽樹贈喬十二侍御 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c361c97a-f3e4-40f7-8b50-0bc236efcf10', '初入峽苦風寄故鄉親友', '初入峽苦风寄故乡親友', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["故鄉今日友，歡會坐應同。","寧知巴峽路，辛苦石尤風。"]', '["故乡今日友，歡會坐應同。","寧知巴峽路，辛苦石尤风。"]', '诗', 'shi', '', NULL, '初入峽苦風寄故鄉親友 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5a9ae0-5a39-478a-9a85-98edaafd321f', '題田洗馬遊巖桔槔', '題田洗马游巖桔槔', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["望苑長爲客，商山遂不歸。","誰憐北陵井，未息漢陰機。"]', '["望苑长爲客，商山遂不归。","誰怜北陵井，未息漢陰機。"]', '诗', 'shi', '', NULL, '題田洗馬遊巖桔槔 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae67aa0c-09f7-479a-839c-7bd635d6ff48', '古意題徐令壁', '古意題徐令壁', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["白雲蒼梧來，氛氳萬里色。","聞君太平世，棲泊靈臺側。"]', '["白云蒼梧来，氛氳万里色。","闻君太平世，棲泊靈台側。"]', '诗', 'shi', '', NULL, '古意題徐令壁 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aacccb99-3312-4253-a2a4-3099992eaa2c', '贈別冀侍御崔司議', '贈別冀侍御崔司議', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["有道君匡國，無悶余在林。","白雲峨眉上，歲晚來相尋。"]', '["有道君匡国，無悶余在林。","白云峨眉上，歲晚来相尋。"]', '诗', 'shi', '', NULL, '贈別冀侍御崔司議 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b5ba9aa-1472-44a9-bbb2-6ef28427df63', '三月三日宴王明府山亭', '三月三日宴王明府山亭', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["暮春嘉月，上巳芳辰。","羣公禊飲，于洛之濱。","奕奕車騎，粲粲都人。","連帷競野，袨服縟津。","青郊樹密，翠渚萍新。","今我不樂，含意□申。"]', '["暮春嘉月，上巳芳辰。","羣公禊饮，于洛之濱。","奕奕车騎，粲粲都人。","連帷競野，袨服縟津。","青郊樹密，翠渚萍新。","今我不乐，含意□申。"]', '诗', 'shi', '', NULL, '三月三日宴王明府山亭 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8e3003-0741-4a1d-94ee-761086827b5d', '唐封泰山樂章 豫和六首 一', '唐封泰山乐章 豫和六首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["挹泰壇，紫泰清。","受天命，報天成。","竦皇心，薦樂聲。","志上達，歌下迎。"]', '["挹泰壇，紫泰清。","受天命，報天成。","竦皇心，薦乐声。","志上達，歌下迎。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和六首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091e047c-9f70-40c9-a30c-b578c8416fa3', '唐封泰山樂章 豫和六首 二', '唐封泰山乐章 豫和六首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["億上帝，臨下庭。","騎日月，陪列星。","嘉視信，大糦聲。","澹神心，醉皇靈。"]', '["億上帝，臨下庭。","騎日月，陪列星。","嘉視信，大糦声。","澹神心，醉皇靈。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和六首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7e9ebf-3577-41dd-af76-0b172828bc4b', '唐封泰山樂章 豫和六首 三', '唐封泰山乐章 豫和六首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["相百辟，貢八荒。","九歌敘，萬舞翔。","肅振振，鏗皇皇。","帝欣欣，福穰穰。"]', '["相百辟，貢八荒。","九歌敘，万舞翔。","肅振振，鏗皇皇。","帝欣欣，福穰穰。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和六首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd168ba5-e055-4c6d-aadb-42870f80391c', '唐封泰山樂章 豫和六首 四', '唐封泰山乐章 豫和六首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["高在上，道光明。","物資始，德難名。","承眷命，牧蒼生。","寰宇謐，泰階平。"]', '["高在上，道光明。","物資始，德难名。","承眷命，牧蒼生。","寰宇謐，泰階平。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和六首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0525e3ad-b2cd-448a-8432-a3d9cff1639b', '唐封泰山樂章 豫和六首 五', '唐封泰山乐章 豫和六首 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天道無親，至誠與鄰。","山川遍禮，宮徵惟新。","玉帛非盛，聰明會真。","正斯一德，通乎百神。"]', '["天道無親，至誠與鄰。","山川遍禮，宮徵惟新。","玉帛非盛，聰明會真。","正斯一德，通乎百神。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和六首 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa4faf5-71fb-4721-a191-4bb415b7ee8a', '唐封泰山樂章 豫和六首 六', '唐封泰山乐章 豫和六首 六', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["享帝享親，維孝維聖。","緝熙懿德，敷揚成命。","華夷志同，笙鏞禮盛。","明靈降止，感此誠敬。"]', '["享帝享親，維孝維聖。","緝熙懿德，敷揚成命。","华夷志同，笙鏞禮盛。","明靈降止，感此誠敬。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和六首 六 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('440b840d-d9d0-419b-8e03-aca8a10fbcb9', '唐封泰山樂章 太和', '唐封泰山乐章 太和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["孝敬中發，和容外彰。","騰華照宇，如昇太陽。","貞璧就奠，玄靈垂光。","禮樂具舉，濟濟洋洋。"]', '["孝敬中發，和容外彰。","腾华照宇，如昇太陽。","貞璧就奠，玄靈垂光。","禮乐具舉，濟濟洋洋。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 太和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f4029f-9090-4253-9544-2e90df171abd', '唐封泰山樂章 肅和', '唐封泰山乐章 肅和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["奠祖配天，承天享帝。","百靈咸秩，四海來祭。","植我蒼璧，布我玄製。","華日裴回，神煙容裔。"]', '["奠祖配天，承天享帝。","百靈咸秩，四海来祭。","植我蒼璧，布我玄製。","华日裴回，神煙容裔。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 肅和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3846ed3-9fe0-4c1c-b225-3ff1917b059c', '唐封泰山樂章 雍和', '唐封泰山乐章 雍和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["俎豆有馥，粢盛絜豐。","亦有和羹，既戒既平。","鼓鐘管磬，肅唱和鳴。","皇皇我祖，來我思成。"]', '["俎豆有馥，粢盛絜豐。","亦有和羹，既戒既平。","鼓鐘管磬，肅唱和鳴。","皇皇我祖，来我思成。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 雍和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b773a93-eddb-44b8-a00e-82cd2dfe4af5', '唐封泰山樂章 壽和', '唐封泰山乐章 壽和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["烝烝我后，享獻惟寅。","躬酌鬱鬯，跪奠明神。","孝莫孝乎，配上帝親。","敬莫敬乎，教天下臣。"]', '["烝烝我后，享獻惟寅。","躬酌鬱鬯，跪奠明神。","孝莫孝乎，配上帝親。","敬莫敬乎，教天下臣。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 壽和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f55cac7-8e74-4692-97de-a67d0c443c66', '唐封泰山樂章 壽和', '唐封泰山乐章 壽和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["皇祖嚴配，配享皇天。","皇皇降嘏，天子萬年。"]', '["皇祖嚴配，配享皇天。","皇皇降嘏，天子万年。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 壽和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a18743-c88d-4cd3-b654-b82b0cada99e', '唐封泰山樂章 舒和', '唐封泰山乐章 舒和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["六鐘翕協六變成，八佾徜徉八風生。","樂九[韶]兮[人神]感，美七德兮天地清。"]', '["六鐘翕協六变成，八佾徜徉八风生。","乐九[韶]兮[人神]感，美七德兮天地清。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 舒和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b53b6fe-49aa-4ca3-a09a-f5c053543b79', '唐封泰山樂章 凱和', '唐封泰山乐章 凱和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["烈祖順三靈，文宗威四海。","黃鉞誅羣盜，朱旗掃多罪。","戢兵天下安，約法人心改。","大哉干羽意，常見風雲在。"]', '["烈祖順三靈，文宗威四海。","黄鉞誅羣盜，朱旗掃多罪。","戢兵天下安，約法人心改。","大哉干羽意，常见风云在。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 凱和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4bc9ca4-dab8-40de-b76c-29ab3e6640e7', '唐封泰山樂章 豫和', '唐封泰山乐章 豫和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["禮樂終，[煙]燎上。","懷靈惠，結皇想。","歸風疾，回風爽。","百[福]來，衆神往。"]', '["禮乐終，[煙]燎上。","懷靈惠，結皇想。","归风疾，回风爽。","百[福]来，衆神往。"]', '诗', 'shi', '', NULL, '唐封泰山樂章 豫和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78df6ed3-3b15-4e1a-b8e9-8da3e0ac95bc', '唐享太廟樂章 永和三首 一', '唐享太廟乐章 永和三首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["肅九室，諧八音。","歌皇慕，動神心。","禮宿設，樂妙尋。","聲明備，祼奠臨。"]', '["肅九室，諧八音。","歌皇慕，动神心。","禮宿設，乐妙尋。","声明備，祼奠臨。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 永和三首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a50afa2-92f0-4ff8-8da7-0bed702c39fc', '唐享太廟樂章 永和三首 二', '唐享太廟乐章 永和三首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["律迓氣，音入玄。","依玉几，御黼筵。","聆愾息，僾周旋。","九韶徧，百福傳。"]', '["律迓氣，音入玄。","依玉几，御黼筵。","聆愾息，僾周旋。","九韶徧，百福傳。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 永和三首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1497c90-e83d-4b81-a5c7-d38c361e08b7', '唐享太廟樂章 永和三首 三', '唐享太廟乐章 永和三首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["信工祝，永頌聲。","來祖考，聽和平。","相百辟，貢九瀛。","神休委，帝孝成。"]', '["信工祝，永頌声。","来祖考，听和平。","相百辟，貢九瀛。","神休委，帝孝成。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 永和三首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8203ddb-a0d5-49ef-9fea-721a17b09491', '唐享太廟樂章 太和', '唐享太廟乐章 太和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["時文聖后，清廟肅邕。","致誠勤薦，在貌思恭。","玉節肆夏，金鏘五鐘。","繩繩雲步，穆穆天容。"]', '["时文聖后，清廟肅邕。","致誠勤薦，在貌思恭。","玉節肆夏，金鏘五鐘。","繩繩云步，穆穆天容。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 太和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c5f01f-b1a6-457e-b288-1ba08ccb2c13', '唐享太廟樂章 肅和', '唐享太廟乐章 肅和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天子享孝，工歌溥將。","射祼鬱鬯，乃焚膋薌。","臭以達旨，聲以求陽。","奉時烝嘗，永代不忘。"]', '["天子享孝，工歌溥將。","射祼鬱鬯，乃焚膋薌。","臭以達旨，声以求陽。","奉时烝嘗，永代不忘。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 肅和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5106cdbd-2fb3-42d0-ac9f-bb393416b4c4', '唐享太廟樂章 雍和二首 一', '唐享太廟乐章 雍和二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["在滌嘉豢，麗碑敬牲。","角握之牝，色純之騂。","火傳陽燧，水溉陰精。","太公胖俎，傅說和羹。"]', '["在滌嘉豢，丽碑敬牲。","角握之牝，色純之騂。","火傳陽燧，水溉陰精。","太公胖俎，傅说和羹。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 雍和二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2396a68-1853-4969-a3c9-42666a157f39', '唐享太廟樂章 雍和二首 二', '唐享太廟乐章 雍和二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["俎豆有馥，齊盛絜豐。","亦有和羹，既戒既平。","鼓鐘管磬，肅唱和鳴。","皇皇后祖，來我思成。"]', '["俎豆有馥，齊盛絜豐。","亦有和羹，既戒既平。","鼓鐘管磬，肅唱和鳴。","皇皇后祖，来我思成。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 雍和二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb0ce32f-de5e-450c-a271-242f7c87f48d', '唐享太廟樂章 文舞', '唐享太廟乐章 文舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖謨九德，真言五千。","慶集昌胄，符開帝先。","高文杖鉞，克配彼天。","三宗握鏡，六合渙燃。","帝其承祀，率禮罔愆。","圖書霧出，日月清懸。","舞形德類，詠諗功傳。","黃龍蜿蟺，彩雲蹁躚。","五行氣順，八佾風宣。","介此百祿，於皇萬年。"]', '["聖謨九德，真言五千。","慶集昌胄，符开帝先。","高文杖鉞，克配彼天。","三宗握镜，六合渙燃。","帝其承祀，率禮罔愆。","圖书霧出，日月清懸。","舞形德類，詠諗功傳。","黄龙蜿蟺，彩云蹁躚。","五行氣順，八佾风宣。","介此百祿，於皇万年。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 文舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a2700d9-5ff7-4535-b1fc-2154886f28a2', '唐享太廟樂章 光大舞', '唐享太廟乐章 光大舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["肅肅藝祖，滔滔濬源。","有雄玉劒，作鎮金門。","玄王貽緒，后稷謀孫。","肇禋九廟，四海來尊。"]', '["肅肅藝祖，滔滔濬源。","有雄玉劒，作鎮金门。","玄王貽緒，后稷謀孫。","肇禋九廟，四海来尊。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 光大舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7322d88-e16c-4607-8649-e22e65d52f4a', '唐享太廟樂章 長發舞', '唐享太廟乐章 长發舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["具禮崇德，備樂承風。","魏推幢主，周贈司空。","不行而至，無成有終。","神興王業，天歸帝功。"]', '["具禮崇德，備乐承风。","魏推幢主，周贈司空。","不行而至，無成有終。","神兴王業，天归帝功。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 長發舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9e6eea-ced2-4495-b994-358bc3de1956', '唐享太廟樂章 大政舞', '唐享太廟乐章 大政舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["於赫元命，權輿帝文。","天齊八柱，地半三分。","宗廟觀德，笙鏞樂勳。","封唐之兆，成天下君。"]', '["於赫元命，權輿帝文。","天齊八柱，地半三分。","宗廟观德，笙鏞乐勳。","封唐之兆，成天下君。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 大政舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85404b91-989a-4bb9-967a-4903d7a8fa97', '唐享太廟樂章 大成舞', '唐享太廟乐章 大成舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝舞季歷，龍聖生昌。","后歌有蟜，胎炎孕黃。","天地合德，日月齊光。","肅雍孝享，祚我萬方。"]', '["帝舞季歷，龙聖生昌。","后歌有蟜，胎炎孕黄。","天地合德，日月齊光。","肅雍孝享，祚我万方。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 大成舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b032d71-6e53-4f6a-ad71-786202a0b486', '唐享太廟樂章 大明舞', '唐享太廟乐章 大明舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["赤精亂德，四海困窮。","黃旗舉義，三靈會同。","早望春雨，雲披大風。","溥天來祭，高祖之功。"]', '["赤精亂德，四海困窮。","黄旗舉義，三靈會同。","早望春雨，云披大风。","溥天来祭，高祖之功。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 大明舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('221980c0-157e-4ab7-9286-c5c09463a723', '唐享太廟樂章 崇德舞', '唐享太廟乐章 崇德舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["皇合一德，朝宗百神。","削平天地，大拯生人。","上帝配食，單于入臣。","戎歌陳武，曄曄震震。"]', '["皇合一德，朝宗百神。","削平天地，大拯生人。","上帝配食，單于入臣。","戎歌陳武，曄曄震震。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 崇德舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b5df22-c75a-4f22-a228-fba21d052255', '唐享太廟樂章 鈞天舞', '唐享太廟乐章 鈞天舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["高皇邁道，端拱無爲。","化懷獯鬻，兵[戢]句驪。","禮尊封禪，樂盤來儀。","合位媧后，同稱伏羲。"]', '["高皇邁道，端拱無爲。","化懷獯鬻，兵[戢]句驪。","禮尊封禪，乐盤来儀。","合位媧后，同稱伏羲。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 鈞天舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8b24bd-ff95-4886-bde5-c1e36b266441', '唐享太廟樂章 大和舞', '唐享太廟乐章 大和舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["退居江水，鬱起丹陵。","禮物還舊，朝章中興。","龍圖友及，駿命恭膺。","鳴球香瓚，大糦是承。"]', '["退居江水，鬱起丹陵。","禮物還旧，朝章中兴。","龙圖友及，駿命恭膺。","鳴球香瓚，大糦是承。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 大和舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9ea81a-58f9-4e82-b85f-b44498660479', '唐享太廟樂章 景雲舞', '唐享太廟乐章 景云舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["景雲霏爛，告我帝符。","噫帝沖德，與天爲徒。","笙鏞遙遠，俎豆虛無。","春秋孝獻，回復此都。"]', '["景云霏爛，告我帝符。","噫帝沖德，與天爲徒。","笙鏞遙远，俎豆虛無。","春秋孝獻，回复此都。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 景雲舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a55fbd-d955-430f-9bd8-bef7a99193c0', '唐享太廟樂章 福和', '唐享太廟乐章 福和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["備禮用樂，崇親致尊。","誠通慈降，敬徹愛存。","獻懷稱壽，啐感承恩。","皇帝孝德，子孫千億。","大包天域，長亙不極。"]', '["備禮用乐，崇親致尊。","誠通慈降，敬徹愛存。","獻懷稱壽，啐感承恩。","皇帝孝德，子孫千億。","大包天域，长亙不極。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 福和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa136c9-c472-4095-a172-fd4b9a02dbd4', '唐享太廟樂章 舒和', '唐享太廟乐章 舒和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["六鐘翕協六變成，八佾徜徉八風生。","樂九韶兮人神感，美七德兮天地清。"]', '["六鐘翕協六变成，八佾徜徉八风生。","乐九韶兮人神感，美七德兮天地清。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 舒和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeefef60-1b6d-4747-9fbb-8b77371a13b2', '唐享太廟樂章 凱安三首 一', '唐享太廟乐章 凱安三首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["瑟彼瑤爵，亞維上公。","室如屏氣，門不容躬。","禮殷其本，樂執其中。","聖皇永慕，天地幽通。"]', '["瑟彼瑤爵，亞維上公。","室如屏氣，门不容躬。","禮殷其本，乐執其中。","聖皇永慕，天地幽通。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 凱安三首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a034e87-1c87-46fb-9c17-a06294a4dce3', '唐享太廟樂章 凱安三首 二', '唐享太廟乐章 凱安三首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["禮匝三獻，樂徧九成。","降循軒陛，仰欷皇情。","福與仁合，德因孝明。","百年神畏，四海風行。"]', '["禮匝三獻，乐徧九成。","降循軒陛，仰欷皇情。","福與仁合，德因孝明。","百年神畏，四海风行。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 凱安三首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7421548-22b1-454e-a9e5-5da5fd63969b', '唐享太廟樂章 凱安三首 三', '唐享太廟乐章 凱安三首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["總總干戚，填填鼓鐘。","奮揚增氣，坐作爲容。","離若鷙鳥，合如戰龍。","萬方觀德，肅肅邕邕。"]', '["總總干戚，填填鼓鐘。","奮揚增氣，坐作爲容。","離若鷙鸟，合如戰龙。","万方观德，肅肅邕邕。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 凱安三首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13720122-7d30-4270-9f0f-39d418fe79d9', '唐享太廟樂章 登歌', '唐享太廟乐章 登歌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["止笙磬，撤豆籩。","廓無響，窅入玄。","主在室，神在天。","情餘慕，禮罔愆。","喜黍稷，屢豐年。"]', '["止笙磬，撤豆籩。","廓無响，窅入玄。","主在室，神在天。","情餘慕，禮罔愆。","喜黍稷，屢豐年。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 登歌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c59869-f23c-418f-a160-6d639f355efe', '唐享太廟樂章 永和', '唐享太廟乐章 永和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["眇嘉樂，授靈爽。","感若來，思如往。","休氣散，回風上。","返寂寞，還惚恍。","懷靈駕，結空想。"]', '["眇嘉乐，授靈爽。","感若来，思如往。","休氣散，回风上。","返寂寞，還惚恍。","懷靈駕，結空想。"]', '诗', 'shi', '', NULL, '唐享太廟樂章 永和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6eb43b4-b342-47c0-bd80-2df868433752', '奉和聖製賜諸州刺史應制以題坐右', '奉和聖製賜諸州刺史應制以題坐右', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["文明遍禹跡，鰥寡達堯心。","正在親人守，能令王澤深。","朝廷多秀士，鎔鍊比精金。","犀節同分命，熊軒各外臨。","聖主賦新詩，穆若聽薰琴。","先言教爲本，次言則是欽。","三時農不奪，午夜犬無侵。","願使天宇內，品物遂浮沈。","寄情羣飛鶴，千里一揚音。","共躡華胥夢，龔黃安足尋。"]', '["文明遍禹跡，鰥寡達堯心。","正在親人守，能令王澤深。","朝廷多秀士，鎔鍊比精金。","犀節同分命，熊軒各外臨。","聖主賦新诗，穆若听薰琴。","先言教爲本，次言則是欽。","三时農不奪，午夜犬無侵。","願使天宇內，品物遂浮沈。","寄情羣飞鹤，千里一揚音。","共躡华胥梦，龔黄安足尋。"]', '诗', 'shi', '', NULL, '奉和聖製賜諸州刺史應制以題坐右 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21219b7-bbc9-426d-910f-85568464d646', '奉和聖製送宇文融安輯戶口應制', '奉和聖製送宇文融安輯戶口應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["至德臨天下，勞情遍九圍。","念茲人去本，蓬轉將何依。","外避征戍數，內傷親黨稀。","嗟不逢明盛，胡能照隱微。","柏臺簡行李，蘭殿錫朝衣。","別曲動秋風，恩令生春輝。","使出四海安，詔下萬心歸。","怍非夔龍佐，徒歌鴻雁飛。"]', '["至德臨天下，勞情遍九圍。","念茲人去本，蓬轉將何依。","外避征戍數，內傷親黨稀。","嗟不逢明盛，胡能照隐微。","柏台簡行李，蘭殿錫朝衣。","別曲动秋风，恩令生春輝。","使出四海安，詔下万心归。","怍非夔龙佐，徒歌鴻雁飞。"]', '诗', 'shi', '', NULL, '奉和聖製送宇文融安輯戶口應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ca1da0-47bf-446b-b974-00e47f499580', '奉和聖製過晉陽宮應制', '奉和聖製過晉陽宮應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["太原俗尚武，高皇初奮庸。","星軒三晉躔，土樂二堯封。","北風遂舉鵬，西河亦上龍。","至德起王業，繼明賴人雍。","六合啓昌期，再興廣聖蹤。","傳呼大駕來，文物如雲從。","連營火百里，縱觀人千重。","翠華渡汾水，白日臨崒峰。","枌榆恩賞洽，桑梓舊情恭。","往運感不追，清時惜難逢。","詩發尊祖心，頌刊盛德容。","願君及春事，廻輿綏萬邦。"]', '["太原俗尚武，高皇初奮庸。","星軒三晉躔，土乐二堯封。","北风遂舉鵬，西河亦上龙。","至德起王業，繼明賴人雍。","六合啓昌期，再兴廣聖蹤。","傳呼大駕来，文物如云從。","連營火百里，縱观人千重。","翠华渡汾水，白日臨崒峰。","枌榆恩賞洽，桑梓旧情恭。","往運感不追，清时惜难逢。","诗發尊祖心，頌刊盛德容。","願君及春事，廻輿綏万邦。"]', '诗', 'shi', '', NULL, '奉和聖製過晉陽宮應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ee99f4-7a07-44e7-aaa1-7c038667e972', '奉和聖製行次成臯應制', '奉和聖製行次成臯應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["夏氏階隋亂，自言河朔雄。","王師進穀水，兵氣臨山東。","前掃成臯陣，却下洛陽宮。","義合帝圖起，威加天宇同。","軒臺百年外，虞典一巡中。","戰龍思王業，倚馬賦神功。"]', '["夏氏階隋亂，自言河朔雄。","王師進穀水，兵氣臨山东。","前掃成臯陣，却下洛陽宮。","義合帝圖起，威加天宇同。","軒台百年外，虞典一巡中。","戰龙思王業，倚马賦神功。"]', '诗', 'shi', '', NULL, '奉和聖製行次成臯應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2ee9bd-bf98-4c40-9ac0-e63b5c683089', '奉和聖製溫湯對雪應制', '奉和聖製溫湯对雪應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["瑞雪帶寒風，寒風入陰琯。","陰琯方凝閉，寒風復淒斷。","宮似瑤林匝，庭如月華滿。","正賡挾纊詞，非近溫湯暖。"]', '["瑞雪带寒风，寒风入陰琯。","陰琯方凝閉，寒风复淒斷。","宮似瑤林匝，庭如月华满。","正賡挾纊词，非近溫湯暖。"]', '诗', 'shi', '', NULL, '奉和聖製溫湯對雪應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340fd0e0-4205-45e9-99aa-b32a3dc7c003', '奉和聖製義成校獵喜雪應制', '奉和聖製義成校獵喜雪應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["文教資武功，郊畋閱邦政。","不知仁育久，徒看禽獸盛。","夜霰氛埃滅，朝日山川淨。","綽仗飛走繁，抨絃筋角勁。","帝射參神道，龍馳合人性。","五豝連一發，百中皆先命。","勇爵均萬夫，雄圖羅七聖。","星爲吉符老，雪作豐年慶。","喜聽行獵詩，威神入軍令。"]', '["文教資武功，郊畋閱邦政。","不知仁育久，徒看禽獸盛。","夜霰氛埃滅，朝日山川淨。","綽仗飞走繁，抨絃筋角勁。","帝射參神道，龙驰合人性。","五豝連一發，百中皆先命。","勇爵均万夫，雄圖羅七聖。","星爲吉符老，雪作豐年慶。","喜听行獵诗，威神入軍令。"]', '诗', 'shi', '', NULL, '奉和聖製義成校獵喜雪應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('877edc30-59cc-4593-acc8-94b2080ef52d', '清明日詔宴寧王山池賦得飛字', '清明日詔宴寧王山池賦得飞字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["今日清明宴，佳境惜芳菲。","搖揚花雜下，嬌囀鸎亂飛。","綠渚傳歌榜，紅橋度舞旂。","和風偏應律，細雨不霑衣。","承恩如改火，春去春來歸。"]', '["今日清明宴，佳境惜芳菲。","搖揚花杂下，嬌囀鸎亂飞。","綠渚傳歌榜，紅橋度舞旂。","和风偏應律，細雨不霑衣。","承恩如改火，春去春来归。"]', '诗', 'shi', '', NULL, '清明日詔宴寧王山池賦得飛字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9170257-f685-45b7-b69e-7b39d3d6f1a7', '四月十三日詔宴寧王亭子賦得好字', '四月十三日詔宴寧王亭子賦得好字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["何許承恩宴，山亭風日好。","綠嫩鳴鶴洲，陰穠鬬雞道。","果思夏來茂，花嫌春去早。","行樂無限時，皇情及芳草。"]', '["何許承恩宴，山亭风日好。","綠嫩鳴鹤洲，陰穠鬬雞道。","果思夏来茂，花嫌春去早。","行乐無限时，皇情及芳草。"]', '诗', 'shi', '', NULL, '四月十三日詔宴寧王亭子賦得好字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d34dd2e-ac91-419f-985b-74bdb893bcad', '藥園宴武輅沙將軍賦得洛字', '藥园宴武輅沙將軍賦得洛字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["東第乘餘興，南園宴清洛。","文學引鄒枚，歌鐘陳衞霍。","風高大夫樹，露下將軍藥。","待聞出塞還，丹青上麟閣。"]', '["东第乘餘兴，南园宴清洛。","文学引鄒枚，歌鐘陳衞霍。","风高大夫樹，露下將軍藥。","待闻出塞還，丹青上麟閣。"]', '诗', 'shi', '', NULL, '藥園宴武輅沙將軍賦得洛字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a77e00fb-854a-4ec7-86ab-3d53653b1073', '修書院學士奉敕宴梁王宅賦得樹字', '修书院学士奉敕宴梁王宅賦得樹字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["虎殿成鴻業，猿巖題鳳賦。","既荷大君恩，還蒙小山遇。","秋吹迎絃管，涼雲生竹樹。","共惜朱邸歡，無辭洛城暮。"]', '["虎殿成鴻業，猿巖題鳳賦。","既荷大君恩，還蒙小山遇。","秋吹迎絃管，涼云生竹樹。","共惜朱邸歡，無辞洛城暮。"]', '诗', 'shi', '', NULL, '修書院學士奉敕宴梁王宅賦得樹字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30700331-9b75-4911-8ea3-556546092bf9', '夕宴房主簿舍', '夕宴房主簿舍', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["歲晏關雍空，風急河謂冰。","薄遊羈物役，微尚愜遠憑。","旅館月宿永，閉扃雲思興。","伊人美修夜，朋酒惠來稱。","交談既清雅，琴吹亦淒凝。","不逢君蹇涸，幽意長鬱蒸。"]', '["歲晏关雍空，风急河謂冰。","薄游羈物役，微尚愜远憑。","旅館月宿永，閉扃云思兴。","伊人美修夜，朋酒惠来稱。","交談既清雅，琴吹亦淒凝。","不逢君蹇涸，幽意长鬱蒸。"]', '诗', 'shi', '', NULL, '夕宴房主簿舍 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c9e5b55-7849-42cc-bd06-bab68a6a02e2', '行從方秀川與劉評事文同宿', '行從方秀川與劉評事文同宿', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["方秀美盤遊，頻年降天罕。","水共伊川接，山將闕門斷。","捧日照恩華，攀雲引疲散。","野宿霜入帳，孤衾寒不暖。","靜聞宮漏疎，臥視庭月滿。","開爐命溫酎，中夜發清管。","風送關山長，氣遒星歲短。","寓言情思愜，適興真意坦。","寰中病羈掛，方外嫌縱誕。","願君樂盛時，無嗟帶纕緩。"]', '["方秀美盤游，頻年降天罕。","水共伊川接，山將闕门斷。","捧日照恩华，攀云引疲散。","野宿霜入帳，孤衾寒不暖。","静闻宮漏疎，臥視庭月满。","开爐命溫酎，中夜發清管。","风送关山长，氣遒星歲短。","寓言情思愜，適兴真意坦。","寰中病羈掛，方外嫌縱誕。","願君乐盛时，無嗟带纕緩。"]', '诗', 'shi', '', NULL, '行從方秀川與劉評事文同宿 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ec6ab6-a121-437c-a042-ef5622aa23fe', '送郭大夫元振再使吐蕃', '送郭大夫元振再使吐蕃', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["犬戎廢東獻，漢使馳西極。","長策問酋渠，猜阻自夷殛。","容髪徂邊歲，旌裘敝海色。","五年一見家，妻子不相識。","武庫兵猶動，金方事未息。","遠圖待才智，苦節輸筋力。","脫刀贈分手，書帶加餐食。","知君萬里侯，立功在異域。"]', '["犬戎廢东獻，漢使驰西極。","长策问酋渠，猜阻自夷殛。","容髪徂邊歲，旌裘敝海色。","五年一见家，妻子不相識。","武庫兵猶动，金方事未息。","远圖待才智，苦節輸筋力。","脫刀贈分手，书带加餐食。","知君万里侯，立功在異域。"]', '诗', 'shi', '', NULL, '送郭大夫元振再使吐蕃 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15009be4-4070-4c22-ad6a-d9d5c21c26bc', '送李侍郎逈秀薛長史季昶同賦得水字', '送李侍郎逈秀薛长史季昶同賦得水字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["漢郡接胡庭，幽幷對烽壘。","旌旗按部曲，文武惟卿士。","薛公善籌畫，李相威邊鄙。","中冀分兩河，長城各萬里。","藉馬黃花塞，蒐兵白狼水。","勝敵在安人，爲君汗青史。"]', '["漢郡接胡庭，幽幷对烽壘。","旌旗按部曲，文武惟卿士。","薛公善籌畫，李相威邊鄙。","中冀分兩河，长城各万里。","藉马黄花塞，蒐兵白狼水。","勝敵在安人，爲君汗青史。"]', '诗', 'shi', '', NULL, '送李侍郎逈秀薛長史季昶同賦得水字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5deb0bb-355f-40dc-bf23-a876b34ba77a', '別平一師', '別平一師', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["王子不事俗，高駕眇難追。","茅土非屑盼，傾城無樂資。","宴坐深林中，三世同一時。","皎皎獨往心，不爲塵網欺。","朅來已復去，今去何來思。","廻首謝同行，勤會安請期。"]', '["王子不事俗，高駕眇难追。","茅土非屑盼，傾城無乐資。","宴坐深林中，三世同一时。","皎皎独往心，不爲塵網欺。","朅来已复去，今去何来思。","廻首謝同行，勤會安請期。"]', '诗', 'shi', '', NULL, '別平一師 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7ec325-7949-47d7-8b60-c927f68e3fdb', '送王光庭', '送王光庭', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["同居洛陽陌，經日懶相求。","及爾江湖去，言別悵悠悠。","楚雲眇羈翼，海月倦行舟。","愛而不可見，徒嗟芳歲流。"]', '["同居洛陽陌，經日懶相求。","及爾江湖去，言別悵悠悠。","楚云眇羈翼，海月倦行舟。","愛而不可见，徒嗟芳歲流。"]', '诗', 'shi', '', NULL, '送王光庭 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba1de99-5c14-49e8-bd7e-5ca50fd96480', '新都南亭送郭元振盧崇道', '新都南亭送郭元振盧崇道', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["竹徑女蘿蹊，蓮洲文石隄。","靜深人俗斷，尋玩往還迷。","碧潭秀初月，素林驚夕棲。","褰幌納蟾影，理琴聽猿啼。","佳辰改宿昔，勝寄坐暌攜。","長懷賞心愛，如玉復如珪。"]', '["竹徑女蘿蹊，蓮洲文石隄。","静深人俗斷，尋玩往還迷。","碧潭秀初月，素林驚夕棲。","褰幌納蟾影，理琴听猿啼。","佳辰改宿昔，勝寄坐暌携。","长懷賞心愛，如玉复如珪。"]', '诗', 'shi', '', NULL, '新都南亭送郭元振盧崇道 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055b7091-3c96-42e7-8131-72193bbd970f', '贈崔公', '贈崔公', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["我聞西漢日，四老南山幽。","長歌紫芝秀，高臥白雲浮。","朝野光塵絕，榛蕪年貌秋。","一朝驅駟馬，連轡入龍樓。","昔遯高皇去，今從太子遊。","行藏惟聖節，福禍在人謀。","卒能匡惠帝，豈不賴留侯。","事隨年代遠，名與圖籍留。","平生欽淳德，慷慨景前修。","蜯蛤伺陰兔，蛟龍望斗牛。","無嗟異飛伏，同氣幸相求。"]', '["我闻西漢日，四老南山幽。","长歌紫芝秀，高臥白云浮。","朝野光塵絕，榛蕪年貌秋。","一朝驱駟马，連轡入龙楼。","昔遯高皇去，今從太子游。","行藏惟聖節，福禍在人謀。","卒能匡惠帝，豈不賴留侯。","事隨年代远，名與圖籍留。","平生欽淳德，慷慨景前修。","蜯蛤伺陰兔，蛟龙望斗牛。","無嗟異飞伏，同氣幸相求。"]', '诗', 'shi', '', NULL, '贈崔公 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90849769-bd57-4dcd-aac8-14d3efdb4a31', '贈趙公', '贈趙公', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["湘東股肱守，心與帝鄉期。","舟楫中途蹇，風波復來思。","嘉我常聯翼，金貂侍玉墀。","迹參前馬聖，名綴鬻熊師。","寒暑一何速，山川遠間之。","寧知洞庭上，獨得平生時。","精意微絕簡，從權討妙棋。","林壑爲予請，紛靄發華滋。","流賞忽已散，驚帆杳難追。","送君在南浦，侘傺投此詞。"]', '["湘东股肱守，心與帝乡期。","舟楫中途蹇，风波复来思。","嘉我常聯翼，金貂侍玉墀。","迹參前马聖，名綴鬻熊師。","寒暑一何速，山川远间之。","寧知洞庭上，独得平生时。","精意微絕簡，從權討妙棋。","林壑爲予請，紛靄發华滋。","流賞忽已散，驚帆杳难追。","送君在南浦，侘傺投此词。"]', '诗', 'shi', '', NULL, '贈趙公 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58dcb426-0643-4090-adff-bc33c1476d72', '贈趙侍御', '贈趙侍御', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["祿放跡異端，偏荒事同蹇。","苟忘風波累，俱會雲壑踐。","險式壓西湖，僑廬對南峴。","夜樓江月入，朝幌山雲捲。","山勢遠濤連，江途斜漢轉。","坐嘯予多暇，行吟子獨善。","並轡躧郊郭，方舟玩遊演。","虛聲萬籟分，水色千里辨。","不知岸陰謝，再見春露泫。","綠壤發欣顏，華年助蟲篆。","上世時難接，古人情可選。","泊渚煩爲媒，多才怨成褊。","長沙鵩作賦，任道可知淺。","請從三已心，榮辱兩都遣。"]', '["祿放跡異端，偏荒事同蹇。","苟忘风波累，俱會云壑踐。","險式壓西湖，僑廬对南峴。","夜楼江月入，朝幌山云捲。","山勢远濤連，江途斜漢轉。","坐嘯予多暇，行吟子独善。","並轡躧郊郭，方舟玩游演。","虛声万籟分，水色千里辨。","不知岸陰謝，再见春露泫。","綠壤發欣顏，华年助蟲篆。","上世时难接，古人情可選。","泊渚煩爲媒，多才怨成褊。","长沙鵩作賦，任道可知淺。","請從三已心，榮辱兩都遣。"]', '诗', 'shi', '', NULL, '贈趙侍御 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c29980e0-a410-4a84-bf9e-476be5c29468', '答李伯魚桐竹', '答李伯鱼桐竹', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["結廬桐竹下，室邇人相深。","接垣分竹徑，隔戶共桐陰。","落花朝滿岸，明月夜披林。","竹有龍鳴管，桐留鳳舞琴。","奇聲與高節，非吾誰賞心。"]', '["結廬桐竹下，室邇人相深。","接垣分竹徑，隔戶共桐陰。","落花朝满岸，明月夜披林。","竹有龙鳴管，桐留鳳舞琴。","奇声與高節，非吾誰賞心。"]', '诗', 'shi', '', NULL, '答李伯魚桐竹 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6081c046-007a-4535-bb3f-fb9ff6e4e1de', '寄姚司馬', '寄姚司马', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["共君春種瓜，本期清夏暑。","瓜成人已去，失望將誰語。","裛露摘香園，感味懷心許。","偶逢西風便，因之寄鄂渚。"]', '["共君春種瓜，本期清夏暑。","瓜成人已去，失望將誰語。","裛露摘香园，感味懷心許。","偶逢西风便，因之寄鄂渚。"]', '诗', 'shi', '', NULL, '寄姚司馬 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79bd177a-d96f-49f6-8156-50e27e57a656', '代書答姜七崔九', '代书答姜七崔九', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["婀娜金閨樹，離披野田草。","雖殊兩地榮，幸共三春好。","花殊鳥飛處，葉鏤蟲行道。","真心獨感人，惆悵令人老。"]', '["婀娜金閨樹，離披野田草。","雖殊兩地榮，幸共三春好。","花殊鸟飞处，葉鏤蟲行道。","真心独感人，惆悵令人老。"]', '诗', 'shi', '', NULL, '代書答姜七崔九 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c44f4181-060a-4ff0-ada9-2f31ee0b13ac', '代書寄吉十一', '代书寄吉十一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["一雁雪上飛，值我衡陽道。","口銜離別字，遠寄當歸草。","目想春來遲，心驚寒去早。","憶鄉乘羽翮，慕侶盈懷抱。","零落答故人，將隨江樹老。"]', '["一雁雪上飞，值我衡陽道。","口銜離別字，远寄當归草。","目想春来遲，心驚寒去早。","憶乡乘羽翮，慕侶盈懷抱。","零落答故人，將隨江樹老。"]', '诗', 'shi', '', NULL, '代書寄吉十一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f3b22d-2d02-449e-9d27-e56931c39796', '代書寄薛四', '代书寄薛四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["孤雁東飛來，寄我紋與素。","紋足經三象，素當綜羣務。","遠見故人心，一言重千金。","答之綵毛翰，繼以瑤華音。","歲寒衆木改，松柏心常在。"]', '["孤雁东飞来，寄我紋與素。","紋足經三象，素當綜羣務。","远见故人心，一言重千金。","答之綵毛翰，繼以瑤华音。","歲寒衆木改，松柏心常在。"]', '诗', 'shi', '', NULL, '代書寄薛四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('312f898d-94e3-4ce0-983f-fca1ef82a5fe', '過蜀道山', '過蜀道山', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["我行春三月，山中百花開。","披林入峭蒨，攀磴陟崔嵬。","白雲半峰起，清江出峽來。","誰知高深意，緬邈心幽哉。"]', '["我行春三月，山中百花开。","披林入峭蒨，攀磴陟崔嵬。","白云半峰起，清江出峽来。","誰知高深意，緬邈心幽哉。"]', '诗', 'shi', '', NULL, '過蜀道山 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17294113-e63d-4282-9cd3-6a5732aa9cb0', '蜀路二首 一', '蜀路二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["雲埃夜澄廓，山日曉晴鮮。","葉落蒼江岸，鴻飛白露天。","磷磷含水石，冪冪覆林煙。","客心久無緒，秋風殊未然。"]', '["云埃夜澄廓，山日晓晴鲜。","葉落蒼江岸，鴻飞白露天。","磷磷含水石，冪冪覆林煙。","客心久無緒，秋风殊未然。"]', '诗', 'shi', '', NULL, '蜀路二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017ca3d7-c762-4c97-90bd-8327c8ef5b7a', '蜀路二首 二', '蜀路二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["徭蜀時未改，別家鄉念盈。","憶昨出門日，春風發鮮榮。","及茲旋轅地，秋風滿路生。","昏曉思魏闕，夢寐還秦京。","秦京開朱第，魏闕垂紫纓。","幽獨玄虛閣，不聞人馬聲。","藝業爲君重，名位爲君輕。","玉琴知調苦，寶鏡對膽清。","鷹飢常啄腥，鳳飢亦待瓊。","於君自有屬，物外豈能輕。"]', '["徭蜀时未改，別家乡念盈。","憶昨出门日，春风發鲜榮。","及茲旋轅地，秋风满路生。","昏晓思魏闕，梦寐還秦京。","秦京开朱第，魏闕垂紫纓。","幽独玄虛閣，不闻人马声。","藝業爲君重，名位爲君轻。","玉琴知調苦，寶镜对膽清。","鷹飢常啄腥，鳳飢亦待瓊。","於君自有屬，物外豈能轻。"]', '诗', 'shi', '', NULL, '蜀路二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63559e35-7d6f-4430-9752-ac1faef055b4', '再使蜀道', '再使蜀道', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["眇眇葭萌道，蒼蒼褒斜谷。","煙壑爭晦深，雲山共重複。","古來風塵子，同眩望鄉目。","芸閣有儒生，軺車倦馳逐。","青春客岷嶺，白露搖江服。","歲月鎮羈孤，山川俄反覆。","魚遊戀深水，鳥遷戀喬木。","如何別親愛，坐去文章國。","蟋蟀鳴戶庭，蟏蛸網琴筑。"]', '["眇眇葭萌道，蒼蒼褒斜谷。","煙壑爭晦深，云山共重複。","古来风塵子，同眩望乡目。","芸閣有儒生，軺车倦驰逐。","青春客岷嶺，白露搖江服。","歲月鎮羈孤，山川俄反覆。","鱼游戀深水，鸟遷戀喬木。","如何別親愛，坐去文章国。","蟋蟀鳴戶庭，蟏蛸網琴筑。"]', '诗', 'shi', '', NULL, '再使蜀道 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c02a617-dfae-4fed-85d4-cf38043b7000', '江路憶郡', '江路憶郡', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["霧斂江早明，星翻漢將沒。","臥聞峽猿響，起視榜人發。","倚棹攀岸篠，憑船弄波月。","水宿厭洲渚，晨光屢揮忽。","林澤來不窮，煙波去無歇。","結思笙竽里，搖情遊俠窟。","年貌不暫留，歡愉及玄髪。","雲涓戀山海，禽馬懷燕越。","自非行役人，安知慕城闕。"]', '["霧斂江早明，星翻漢將沒。","臥闻峽猿响，起視榜人發。","倚棹攀岸篠，憑船弄波月。","水宿厭洲渚，晨光屢揮忽。","林澤来不窮，煙波去無歇。","結思笙竽里，搖情游俠窟。","年貌不暫留，歡愉及玄髪。","云涓戀山海，禽马懷燕越。","自非行役人，安知慕城闕。"]', '诗', 'shi', '', NULL, '江路憶郡 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1e6d6cf-5bbc-4ecd-ba74-01f2bdeb7248', '過漢南城歎古墳', '過漢南城歎古墳', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["舊國多陵墓，荒涼無歲年。","洶湧蔽平岡，汩若波濤連。","上世千金子，潛臥九重泉。","松柏剪無餘，碑記滅罔傳。","葬於不毛地，咸謂楚先賢。","事盡情可識，使人心悵然。"]', '["旧国多陵墓，荒涼無歲年。","洶湧蔽平岡，汩若波濤連。","上世千金子，潛臥九重泉。","松柏剪無餘，碑記滅罔傳。","葬於不毛地，咸謂楚先賢。","事尽情可識，使人心悵然。"]', '诗', 'shi', '', NULL, '過漢南城歎古墳 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8292b6f2-089b-43e5-af27-784fdd4c099b', '至尉氏', '至尉氏', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["夕次阮公臺，嘯歌臨爽塏。","高名安足賴，故物今皆改。","吾兄昔茲邑，遺愛稱賢宰。","桑中雉未飛，屋上烏猶在。","途逢舊甿吏，城有同僚寀。","望塵遠見迎，拂館來欣待。","慈惠留千室，友于存四海。","始知魯衞間，優劣相懸倍。"]', '["夕次阮公台，嘯歌臨爽塏。","高名安足賴，故物今皆改。","吾兄昔茲邑，遺愛稱賢宰。","桑中雉未飞，屋上烏猶在。","途逢旧甿吏，城有同僚寀。","望塵远见迎，拂館来欣待。","慈惠留千室，友于存四海。","始知魯衞间，優劣相懸倍。"]', '诗', 'shi', '', NULL, '至尉氏 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b2da4c-4588-4df1-a9ce-b222824566fc', '襄州景空寺題融上人蘭若', '襄州景空寺題融上人蘭若', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["高名出漢陰，禪閣跨香岑。","衆山既圍繞，長川復迴臨。","雲峰曉靈變，風木夜虛吟。","碧湫龍池滿，蒼松虎徑深。","舊知青巖意，偏入杳冥心。","何由侶飛錫，從此脫朝簪。"]', '["高名出漢陰，禪閣跨香岑。","衆山既圍繞，长川复迴臨。","云峰晓靈变，风木夜虛吟。","碧湫龙池满，蒼松虎徑深。","旧知青巖意，偏入杳冥心。","何由侶飞錫，從此脫朝簪。"]', '诗', 'shi', '', NULL, '襄州景空寺題融上人蘭若 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ca9f2e-682c-42c4-8b77-7c508b08923c', '巡邊在河北作', '巡邊在河北作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["撫劒空餘勇，彎弧遂無力。","老去事如何，據鞍長歎息。","故交索將盡，後進稀相識。","獨憐半死心，尚有寒松直。"]', '["撫劒空餘勇，彎弧遂無力。","老去事如何，據鞍长歎息。","故交索將尽，後進稀相識。","独怜半死心，尚有寒松直。"]', '诗', 'shi', '', NULL, '巡邊在河北作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1439acb0-0c50-4fe6-84da-b89457995c2d', '入海二首 一', '入海二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["乘桴入南海，海曠不可臨。","茫茫失方面，混混如凝陰。","雲山相出沒，天地互浮沈。","萬里無涯際，云何測廣深。","潮波自盈縮，安得會虛心。"]', '["乘桴入南海，海曠不可臨。","茫茫失方面，混混如凝陰。","云山相出沒，天地互浮沈。","万里無涯際，云何測廣深。","潮波自盈縮，安得會虛心。"]', '诗', 'shi', '', NULL, '入海二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f5cc4b-4a84-45c9-84f7-f9bb03313bed', '入海二首 二', '入海二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["海上三神山，逍遙集衆仙。","靈心豈不同，變化無常全。","龍伯如人類，一釣兩鰲連。","金臺此淪沒，玉真時播遷。","問子勞何事，江上泣經年。","隰中生紅草，所美非美然。"]', '["海上三神山，逍遙集衆仙。","靈心豈不同，变化無常全。","龙伯如人類，一釣兩鰲連。","金台此淪沒，玉真时播遷。","问子勞何事，江上泣經年。","隰中生紅草，所美非美然。"]', '诗', 'shi', '', NULL, '入海二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc556445-c706-48b8-9962-8e235a8952d4', '相州山池作', '相州山池作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["嘗懷謝公詠，山水陶嘉月。","及此年事衰，徒看衆花發。","觀魚樂何在，聽鳥情都歇。","星漢流不停，蓬萊去難越。","鄴中秋麥秀，淇上春雲沒。","日見塵物空，如何靜心闕。"]', '["嘗懷謝公詠，山水陶嘉月。","及此年事衰，徒看衆花發。","观鱼乐何在，听鸟情都歇。","星漢流不停，蓬萊去难越。","鄴中秋麦秀，淇上春云沒。","日见塵物空，如何静心闕。"]', '诗', 'shi', '', NULL, '相州山池作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7898a7c7-680e-4346-ab88-e49773b1bb31', '岳州作', '岳州作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["夜夢雲闕間，從容簪履列。","朝遊洞庭上，緬望京華絕。","潦收江未清，火退山更熱。","重欷視欲醉，懵滿氣如噎。","器留魚鼈腥，衣點蚊虻血。","髪白思益壯，心玄用彌拙。","冠劒日苔蘚，琴書坐廢撤。","唯有報恩字，刻意長不滅。"]', '["夜梦云闕间，從容簪履列。","朝游洞庭上，緬望京华絕。","潦收江未清，火退山更熱。","重欷視欲醉，懵满氣如噎。","器留鱼鼈腥，衣点蚊虻血。","髪白思益壯，心玄用彌拙。","冠劒日苔蘚，琴书坐廢撤。","唯有報恩字，刻意长不滅。"]', '诗', 'shi', '', NULL, '岳州作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59f3db1-a16f-4f8b-bbd4-2efd8381f6ee', '岳州行郡竹籬', '岳州行郡竹籬', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["山郡不溝郭，荒居無翳壅。","愛人忠主利，善守閉爲勇。","苟非小勤瘁，安得期逸寵。","版築恐土疎，襄城嫌役重。","藩柵聊可固，筠篁近易奉。","差池截浦沙，繚繞緣隈壠。","矗似長雲亙，森如高戟聳。","預絕豺狼憂，知免牛羊恐。","閭里寬矯步，榛叢恣踏踵。","始果遊處心，終日成閑拱。"]', '["山郡不溝郭，荒居無翳壅。","愛人忠主利，善守閉爲勇。","苟非小勤瘁，安得期逸寵。","版築恐土疎，襄城嫌役重。","藩柵聊可固，筠篁近易奉。","差池截浦沙，繚繞緣隈壠。","矗似长云亙，森如高戟聳。","預絕豺狼憂，知免牛羊恐。","閭里寬矯步，榛叢恣踏踵。","始果游处心，終日成闲拱。"]', '诗', 'shi', '', NULL, '岳州行郡竹籬 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c80d0a74-4216-4d8d-bd22-5ea0c0f80da6', '遊洞庭湖湘', '游洞庭湖湘', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["緬邈洞庭岫，葱蒙水霧色。","宛在太湖中，可望不可即。","剖竹守窮渚，開門對奇域。","城池自縶籠，纓綬爲徽纆。","靡日不思往，經時始願克。","飛棹越溟波，維舟恣攀陟。","䆗窱入雲步，崎嶇倚松息。","巖壇有鶴過，壁字無人識。","滴石香乳溜，垂崖靈草植。","玩幽輕霧阻，討異忘曛逼。","寒沙際水平，霜樹籠煙直。","空宮聞莫覩，地道窺難測。","此處學金丹，何人生羽翼。","誰傳九光要，幾拜三仙職。","紫氣徒想像，清潭長眇默。","霓裳若有來，覯我雲峰側。"]', '["緬邈洞庭岫，葱蒙水霧色。","宛在太湖中，可望不可即。","剖竹守窮渚，开门对奇域。","城池自縶籠，纓綬爲徽纆。","靡日不思往，經时始願克。","飞棹越溟波，維舟恣攀陟。","䆗窱入云步，崎嶇倚松息。","巖壇有鹤過，壁字無人識。","滴石香乳溜，垂崖靈草植。","玩幽轻霧阻，討異忘曛逼。","寒沙際水平，霜樹籠煙直。","空宮闻莫覩，地道窺难測。","此处学金丹，何人生羽翼。","誰傳九光要，幾拜三仙職。","紫氣徒想像，清潭长眇默。","霓裳若有来，覯我云峰側。"]', '诗', 'shi', '', NULL, '遊洞庭湖湘 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2593aea-05b8-4084-8c9a-2ee94666b503', '㴩湖山寺', '㴩湖山寺', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["楚老遊山寺，提攜觀畫壁。","揚袂指辟支，睩眄相鬬鬩。","險哉透撞兒，千金賭一擲。","成敗身自受，傍人那歎息。"]', '["楚老游山寺，提携观畫壁。","揚袂指辟支，睩眄相鬬鬩。","險哉透撞兒，千金賭一擲。","成敗身自受，傍人那歎息。"]', '诗', 'shi', '', NULL, '㴩湖山寺 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a122ff7-9cd2-4a88-a56e-903bcb04d374', '出湖寄趙冬曦', '出湖寄趙冬曦', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西泛平湖盡，參差入亂山。","東瞻岳陽郡，汗漫太虛間。","窘步同行樂，遒文互屢看。","山戍上雲桂，江亭臨水關。","川途倏忽間，風景依如昨。","湘浦未賜環，荆門猶主諾。"]', '["西泛平湖尽，參差入亂山。","东瞻岳陽郡，汗漫太虛间。","窘步同行乐，遒文互屢看。","山戍上云桂，江亭臨水关。","川途倏忽间，风景依如昨。","湘浦未賜环，荆门猶主諾。"]', '诗', 'shi', '', NULL, '出湖寄趙冬曦 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a33e04-a84e-4026-ba8f-a90d76a57370', '岳陽早霽南樓', '岳陽早霽南楼', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["山水佳新霽，南樓玩初旭。","夜來枝半紅，雨後洲全綠。","四運相終始，萬形紛代續。","適臨青草湖，再變黃鸎曲。","地穴穿東武，江流下西蜀。","歌聞枉渚邅，舞見長沙促。","心阻意徒馳，神和生自足。","白髪悲上春，知常謝先欲。"]', '["山水佳新霽，南楼玩初旭。","夜来枝半紅，雨後洲全綠。","四運相終始，万形紛代續。","適臨青草湖，再变黄鸎曲。","地穴穿东武，江流下西蜀。","歌闻枉渚邅，舞见长沙促。","心阻意徒驰，神和生自足。","白髪悲上春，知常謝先欲。"]', '诗', 'shi', '', NULL, '岳陽早霽南樓 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e1f77b-4c7a-48a7-a9e6-3dcfa180614f', '岳陽石門墨山二山相連有禪堂觀天下絕境', '岳陽石门墨山二山相連有禪堂观天下絕境', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["囷輪江上山，近在華容縣。","常涉巴丘首，天晴遙可見。","佳遊屢前諾，芳月愆幽眷。","及此符守移，歡言臨道便。","既攜賞心客，復有送行掾。","竹徑入陰窅，松蘿上空蒨。","草共林一色，雲與峰萬變。","探窺石門斷，緣越沙澗轉。","兩山勢爭雄，峰巘相顧眄。","藥妙靈仙寶，境華巖壑選。","清都西淵絕，金地東敞宴。","池果接園畦，風煙邇臺殿。","高尋去石頂，曠覽天宇遍。","千山紛滿目，百川豁對面。","騎來雲氣迎，人去鳥聲戀。","長揖桃源士，舉世同企羨。"]', '["囷輪江上山，近在华容縣。","常涉巴丘首，天晴遙可见。","佳游屢前諾，芳月愆幽眷。","及此符守移，歡言臨道便。","既携賞心客，复有送行掾。","竹徑入陰窅，松蘿上空蒨。","草共林一色，云與峰万变。","探窺石门斷，緣越沙澗轉。","兩山勢爭雄，峰巘相顧眄。","藥妙靈仙寶，境华巖壑選。","清都西淵絕，金地东敞宴。","池果接园畦，风煙邇台殿。","高尋去石頂，曠覽天宇遍。","千山紛满目，百川豁对面。","騎来云氣迎，人去鸟声戀。","长揖桃源士，舉世同企羨。"]', '诗', 'shi', '', NULL, '岳陽石門墨山二山相連有禪堂觀天下絕境 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361a5653-9ee7-4b32-a978-c8e6db62ada6', '和尹懋秋夜遊㴩湖', '和尹懋秋夜游㴩湖', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["坐嘯人事閑，佳遊野情發。","山門送落照，湖口昇微月。","林尋猿狖居，水戲黿鼉穴。","朔風吹飛雁，芳草亦云歇。"]', '["坐嘯人事闲，佳游野情發。","山门送落照，湖口昇微月。","林尋猿狖居，水戲黿鼉穴。","朔风吹飞雁，芳草亦云歇。"]', '诗', 'shi', '', NULL, '和尹懋秋夜遊㴩湖 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8357820-f27b-43b5-afa8-49b4cedc8fcd', '五君詠五首 魏齊公元忠', '五君詠五首 魏齊公元忠', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["齊公生人表，逈天聞鶴唳。","清論早揣摩，玄心晚超詣。","入相廊廟靜，出軍沙漠霽。","見深呂祿憂，舉後陳平計。","甘心除君惡，足以報先帝。"]', '["齊公生人表，逈天闻鹤唳。","清論早揣摩，玄心晚超詣。","入相廊廟静，出軍沙漠霽。","见深呂祿憂，舉後陳平計。","甘心除君惡，足以報先帝。"]', '诗', 'shi', '', NULL, '五君詠五首 魏齊公元忠 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a40eebd-96b4-4237-b027-4cae2004a6b3', '五君詠五首 蘇許公瓌', '五君詠五首 蘇許公瓌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["許公信國楨，克美具瞻情。","百事資朝問，三章廣世程。","處高心不有，臨節自爲名。","朱戶傳新戟，青松拱舊塋。","淒涼丞相府，餘慶在玄成。"]', '["許公信国楨，克美具瞻情。","百事資朝问，三章廣世程。","处高心不有，臨節自爲名。","朱戶傳新戟，青松拱旧塋。","淒涼丞相府，餘慶在玄成。"]', '诗', 'shi', '', NULL, '五君詠五首 蘇許公瓌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33908b4-132e-4ba6-ba47-47e8f1eff7a6', '五君詠五首 李趙公嶠', '五君詠五首 李趙公嶠', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["李公實神敏，才華乃天授。","睦親何用心，處貴不忘舊。","故事遵臺閣，新詩冠宇宙。","在人忠所奉，惡我誠將宥。","南浦去莫歸，嗟嗟蔑孫秀。"]', '["李公實神敏，才华乃天授。","睦親何用心，处貴不忘旧。","故事遵台閣，新诗冠宇宙。","在人忠所奉，惡我誠將宥。","南浦去莫归，嗟嗟蔑孫秀。"]', '诗', 'shi', '', NULL, '五君詠五首 李趙公嶠 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae92855-1fd2-456c-8629-8196e08c3bb2', '五君詠五首 郭代公元振', '五君詠五首 郭代公元振', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["代公舉鵬翼，懸飛摩海霧。","志康天地屯，適與雲雷遇。","興喪一言決，安危萬心注。","大勳書王府，舛命淪江路。","勢傾北夏門，哀靡東平樹。"]', '["代公舉鵬翼，懸飞摩海霧。","志康天地屯，適與云雷遇。","兴喪一言決，安危万心注。","大勳书王府，舛命淪江路。","勢傾北夏门，哀靡东平樹。"]', '诗', 'shi', '', NULL, '五君詠五首 郭代公元振 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a386a8b-1b68-4f67-b803-3ef00e53e0e1', '五君詠五首 趙耿公彥昭', '五君詠五首 趙耿公彥昭', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["耿公山嶽秀，才傑心亦妙。","鷙鳥峻標立，哀玉扣清調。","協贊休明啓，恩華日月照。","何意瑤臺雲，風吹落江徼。","湘流下潯陽，灑淚一投弔。"]', '["耿公山嶽秀，才傑心亦妙。","鷙鸟峻標立，哀玉扣清調。","協贊休明啓，恩华日月照。","何意瑤台云，风吹落江徼。","湘流下潯陽，灑泪一投弔。"]', '诗', 'shi', '', NULL, '五君詠五首 趙耿公彥昭 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddbe3a60-c682-4fb0-b8ce-0fdfec2771de', '遊龍山靜勝寺', '游龙山静勝寺', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["每上襄陽樓，遙望龍山樹。","鬱茀吐岡嶺，微蒙在煙霧。","下車歲已成，飾馬閑餘步。","苦霜裛野草，愛日揚江煦。","雲對石上塔，風吹松下路。","禪室宴三空，神祠同六趣。","兒童共戲謔，猿鳥相驚顧。","南識桓公臺，北望先賢墓。","世上人何在，時聞心不住。","但傳無盡燈，可使有情悟。"]', '["每上襄陽楼，遙望龙山樹。","鬱茀吐岡嶺，微蒙在煙霧。","下车歲已成，飾马闲餘步。","苦霜裛野草，愛日揚江煦。","云对石上塔，风吹松下路。","禪室宴三空，神祠同六趣。","兒童共戲謔，猿鸟相驚顧。","南識桓公台，北望先賢墓。","世上人何在，时闻心不住。","但傳無尽灯，可使有情悟。"]', '诗', 'shi', '', NULL, '遊龍山靜勝寺 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657d18af-6eb4-4ba2-80ce-7cdc1799c2fd', '一柱觀', '一柱观', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["舊說江陵觀，初疑神化來。","空山結雲閣，綺靡隨風回。","奈何任一柱，斯焉容衆材。","奇功非長世，今餘草露臺。"]', '["旧说江陵观，初疑神化来。","空山結云閣，綺靡隨风回。","奈何任一柱，斯焉容衆材。","奇功非长世，今餘草露台。"]', '诗', 'shi', '', NULL, '一柱觀 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbffd2b-2798-4ee4-a6e8-cdc7c4a397eb', '登九里臺是樊姬墓', '登九里台是樊姬墓', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["楚國所以霸，樊姬有力焉。","不懷沈尹祿，誰諳叔敖賢。","萬化茫無在，孤墳獨巋然。","北分陽臺陌，南識郢城阡。","漠漠渚宮樹，蒼蒼雲夢田。","登高形勝出，訪古令名傳。","自我來符守，因君樹蕙荃。","詩書將變俗，絺纊忽彌年。","志闡三折後，愁值二毛前。","佇立帝京路，遙心寄此篇。"]', '["楚国所以霸，樊姬有力焉。","不懷沈尹祿，誰諳叔敖賢。","万化茫無在，孤墳独巋然。","北分陽台陌，南識郢城阡。","漠漠渚宮樹，蒼蒼云梦田。","登高形勝出，訪古令名傳。","自我来符守，因君樹蕙荃。","诗书將变俗，絺纊忽彌年。","志闡三折後，愁值二毛前。","佇立帝京路，遙心寄此篇。"]', '诗', 'shi', '', NULL, '登九里臺是樊姬墓 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3082e5bf-5125-4d43-915c-1d7d2bf68124', '過懷王墓', '過懷王墓', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["咿嚘不可信，以此敗懷王。","客死嶢關路，返葬岐江陽。","啼狖抱山月，飢狐獵野霜。","一聞懷沙事，千載盡悲涼。"]', '["咿嚘不可信，以此敗懷王。","客死嶢关路，返葬岐江陽。","啼狖抱山月，飢狐獵野霜。","一闻懷沙事，千載尽悲涼。"]', '诗', 'shi', '', NULL, '過懷王墓 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dcf5826-9304-4226-b3ed-dc7b8441915d', '聞雨', '闻雨', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["多雨絕塵事，寥寥入太玄。","城陰疎復合，簷滴斷還連。","念我勞造化，從來五十年。","誤將心徇物，近得還自然。","閑居草木侍，虛室鬼神憐。","有時進美酒，有時泛清絃。","聲真不世識，心醉豈言詮。"]', '["多雨絕塵事，寥寥入太玄。","城陰疎复合，簷滴斷還連。","念我勞造化，從来五十年。","誤將心徇物，近得還自然。","闲居草木侍，虛室鬼神怜。","有时進美酒，有时泛清絃。","声真不世識，心醉豈言詮。"]', '诗', 'shi', '', NULL, '聞雨 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e191ee2-2b77-42ef-b87f-c3bb7b5fce7c', '夜坐', '夜坐', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["懷哉四壁時，未有五都價。","百金誰見許，斗酒難爲貰。","落花生芳春，孤月皎清夜。","復逢利交客，題戶遙相謝。"]', '["懷哉四壁时，未有五都價。","百金誰见許，斗酒难爲貰。","落花生芳春，孤月皎清夜。","复逢利交客，題戶遙相謝。"]', '诗', 'shi', '', NULL, '夜坐 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d3a2e5-947b-4eba-85c9-5e49f43d3555', '山夜聞鐘', '山夜闻鐘', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["夜臥聞夜鐘，夜靜山更響。","霜風吹寒月，䆗窱虛中上。","前聲既舂容，後聲復晃盪。","聽之如可見，尋之定無像。","信知本際空，徒掛生滅想。"]', '["夜臥闻夜鐘，夜静山更响。","霜风吹寒月，䆗窱虛中上。","前声既舂容，後声复晃盪。","听之如可见，尋之定無像。","信知本際空，徒掛生滅想。"]', '诗', 'shi', '', NULL, '山夜聞鐘 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb7d9eb-2369-4396-b3c3-3c548d8794c0', '冬日見牧牛人擔青草歸', '冬日见牧牛人擔青草归', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["塞上綿應折，江南草可結。","欲持梅嶺花，遠競榆關雪。","日月無他照，山川何頓別。","苟齊兩地心，天問將安說。"]', '["塞上綿應折，江南草可結。","欲持梅嶺花，远競榆关雪。","日月無他照，山川何頓別。","苟齊兩地心，天问將安说。"]', '诗', 'shi', '', NULL, '冬日見牧牛人擔青草歸 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2a3e30-d72c-4a8c-a301-96569da934fb', '詠鏡', '詠镜', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寶鏡如明月，出自秦宮樣。","隱起雙蟠龍，銜珠儼相向。","常恐君不察，匣中委清量。","積翳掩菱花，虛心蔽塵狀。","倘蒙羅袖拂，光生玉臺上。"]', '["寶镜如明月，出自秦宮樣。","隐起雙蟠龙，銜珠儼相向。","常恐君不察，匣中委清量。","積翳掩菱花，虛心蔽塵狀。","倘蒙羅袖拂，光生玉台上。"]', '诗', 'shi', '', NULL, '詠鏡 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a30e12-c8ac-4c7c-b944-ce1dfc63bee4', '詠瓢', '詠瓢', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["美酒酌懸瓢，真淳好相映。","蝸房卷墮首，鶴頸抽長柄。","雅色素而黃，虛心輕且勁。","豈無雕刻者，貴此成天性。"]', '["美酒酌懸瓢，真淳好相映。","蝸房卷墮首，鹤頸抽长柄。","雅色素而黄，虛心轻且勁。","豈無雕刻者，貴此成天性。"]', '诗', 'shi', '', NULL, '詠瓢 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8282e05-ec11-4727-8d44-a4672dbdfcc3', '雜詩四首 一', '杂诗四首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["抱薰心常焦，舉斾心常搖。","天長地自久，歡樂能幾朝。","君看西陵樹，歌舞爲誰嬌。"]', '["抱薰心常焦，舉斾心常搖。","天长地自久，歡乐能幾朝。","君看西陵樹，歌舞爲誰嬌。"]', '诗', 'shi', '', NULL, '雜詩四首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6676180c-9b9d-445d-9d5d-8f2ff0c33e64', '雜詩四首 二', '杂诗四首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["山閑苦積雨，木落悲時遽。","賞心凡幾人，良辰在何處？","觸石滿堂侈，灑我終夕慮。","客鳥懷主人，銜花未能去。","剖珠貴分明，琢玉思堅貞。","要君意如此，終始莫相輕。"]', '["山闲苦積雨，木落悲时遽。","賞心凡幾人，良辰在何处？","觸石满堂侈，灑我終夕慮。","客鸟懷主人，銜花未能去。","剖珠貴分明，琢玉思堅貞。","要君意如此，終始莫相轻。"]', '诗', 'shi', '', NULL, '雜詩四首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916ae490-eeab-4edd-b5a0-d536cdc7ad23', '雜詩四首 三', '杂诗四首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["問子青霞意，何事留朱軒。","自言心遠俗，未始迹辭喧。","過蒙良時幸，側息吏途煩。","簪纓非宿好，文史棄前言。","夕臥北窗下，夢歸南山園。","白雲慙幽谷，清風愧泉源。","十年茲賞廢，佳期今復存。","掛冠謝朝侶，星駕別君門。"]', '["问子青霞意，何事留朱軒。","自言心远俗，未始迹辞喧。","過蒙良时幸，側息吏途煩。","簪纓非宿好，文史棄前言。","夕臥北窗下，梦归南山园。","白云慙幽谷，清风愧泉源。","十年茲賞廢，佳期今复存。","掛冠謝朝侶，星駕別君门。"]', '诗', 'shi', '', NULL, '雜詩四首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a46aec5-3803-4201-8a36-846c9ebe322b', '雜詩四首 四', '杂诗四首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["默念羣疑起，玄通百慮清。","初心滅陽豔，復見湛虛明。","悟滅心非盡，求虛見後生。","應將無住法，修到不成名。"]', '["默念羣疑起，玄通百慮清。","初心滅陽豔，复见湛虛明。","悟滅心非尽，求虛见後生。","應將無住法，修到不成名。"]', '诗', 'shi', '', NULL, '雜詩四首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1242e5b-90ef-4695-9465-4cc397a9da17', '和張監遊終南', '和張監游終南', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["宿懷終南意，及此語雲峰。","夜聞竹澗靜，曉望林嶺重。","春煙生古石，時鳥戲幽松。","豈無山中賞，但畏心莫從。"]', '["宿懷終南意，及此語云峰。","夜闻竹澗静，晓望林嶺重。","春煙生古石，时鸟戲幽松。","豈無山中賞，但畏心莫從。"]', '诗', 'shi', '', NULL, '和張監遊終南 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652a7480-573a-4c70-8677-0f61c119258c', '古泉驛', '古泉驛', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["昔聞陳仲子，守義辭三公。","身賃妻織屨，樂亦在其中。","豈無窮賤苦，羞與傾巧同。","長白臨河上，於陵入濟東。","我行弔遺跡，感歎古泉空。"]', '["昔闻陳仲子，守義辞三公。","身賃妻织屨，乐亦在其中。","豈無窮賤苦，羞與傾巧同。","长白臨河上，於陵入濟东。","我行弔遺跡，感歎古泉空。"]', '诗', 'shi', '', NULL, '古泉驛 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3727470f-9fc9-4e4d-a691-d085e8409404', '河上公', '河上公', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["尊師厭塵去，精魄知何明。","形氣不復生，弟子空傷情。","濟北神如在，淮南藥未成。","共期終莫遂，寥落兩無成。"]', '["尊師厭塵去，精魄知何明。","形氣不复生，弟子空傷情。","濟北神如在，淮南藥未成。","共期終莫遂，寥落兩無成。"]', '诗', 'shi', '', NULL, '河上公 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490ecb5d-a36a-4da8-a551-995f68a8f781', '奉和聖製初入秦川路寒食應制', '奉和聖製初入秦川路寒食應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["上陽柳色喚春歸，臨渭桃花拂水飛。","總爲朝廷巡幸去，頓教京洛少光輝。","昨從分陝山南口，馳道依依漸花柳。","入關正投寒食前，還京遂落清明後。","路上天心重豫遊，御前恩賜特風流。","便幕那能鏤雞子，行宮善巧帖毛毬。","渭橋南渡花如撲，麥隴青青斷人目。","漢家行樹直新豐，秦地驪山抱溫谷。","香池春溜水初平，預歡浴日照京城。","今歲隨宜過寒食，明年陪宴作清明。"]', '["上陽柳色喚春归，臨渭桃花拂水飞。","總爲朝廷巡幸去，頓教京洛少光輝。","昨從分陝山南口，驰道依依漸花柳。","入关正投寒食前，還京遂落清明後。","路上天心重豫游，御前恩賜特风流。","便幕那能鏤雞子，行宮善巧帖毛毬。","渭橋南渡花如撲，麦隴青青斷人目。","漢家行樹直新豐，秦地驪山抱溫谷。","香池春溜水初平，預歡浴日照京城。","今歲隨宜過寒食，明年陪宴作清明。"]', '诗', 'shi', '', NULL, '奉和聖製初入秦川路寒食應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d32edeb8-6be5-4eb3-8be8-caa63f7eb089', '時樂鳥篇', '时乐鸟篇', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["舊傳南海出靈禽，時樂名聞不可尋。","形貌乍同鸚鵡類，精神別稟鳳皇心。","千年待聖方輕舉，萬里呈才無伴侶。","紅茸糅繡好毛衣，清泠謳鵶好言語。","內人試取御衣牽，啄手暝聲不許前。","心願陽烏恆保日，志嫌陰鶴欲凌天。","天情玩訝良無已，察圖果見祥經裏。","本持符瑞驗明王，還用文章比君子。","自憐弱羽詎堪珍，喜共華篇來示人。","人見嚶嚶報恩鳥，多慙碌碌具官臣。"]', '["旧傳南海出靈禽，时乐名闻不可尋。","形貌乍同鸚鵡類，精神別稟鳳皇心。","千年待聖方轻舉，万里呈才無伴侶。","紅茸糅繡好毛衣，清泠謳鵶好言語。","內人試取御衣牽，啄手暝声不許前。","心願陽烏恆保日，志嫌陰鹤欲凌天。","天情玩訝良無已，察圖果见祥經裏。","本持符瑞驗明王，還用文章比君子。","自怜弱羽詎堪珍，喜共华篇来示人。","人见嚶嚶報恩鸟，多慙碌碌具官臣。"]', '诗', 'shi', '', NULL, '時樂鳥篇 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020271e2-92e8-4e27-a788-9a32dbef1fd6', '安樂郡主花燭行', '安乐郡主花燭行', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["青宮朱邸翊皇闈，玉葉瓊蕤發紫微。","姬姜本來舅甥國，卜筮俱道鳳皇飛。","星昴殷冬獻吉日，夭桃穠李遙相匹。","鸞車鳳傳王子來，龍樓月殿天孫出。","平臺火樹連上陽，紫炬紅輪十二行。","丹爐飛鐵馳炎焰，炎霞爍電吐明光。","綠軿紺幰紛如霧，節鼓清笳前啓路。","城隅靡靡稍東還，橋上鱗鱗轉南渡。","五方觀者聚中京，四合塵煙漲洛城。","商女香車珠結網，天人寶馬玉繁纓。","百壺淥酒千斤肉，大道連延障錦軸。","先祝聖人壽萬年，復禱宜家承百祿。","珊瑚刻盤青玉尊，因之假道入梁園。","梁園山竹凝雲漢，仰望高樓在天半。","翠幕蘭堂蘇合薰，珠簾掛戶水波紋。","別起芙蓉織成帳，金鏤鴛鴦兩相向。","罽茵飾地承琱履，花燭分階移錦帳。","織女西垂隱燭臺，雙童連縷合歡杯。","藹藹綺庭嬪從列，娥娥紅粉扇中開。","黃金兩印雙花綬，富貴婚姻古無有。","清歌棠棣美王姬，流化邦人正夫婦。"]', '["青宮朱邸翊皇闈，玉葉瓊蕤發紫微。","姬姜本来舅甥国，卜筮俱道鳳皇飞。","星昴殷冬獻吉日，夭桃穠李遙相匹。","鸾车鳳傳王子来，龙楼月殿天孫出。","平台火樹連上陽，紫炬紅輪十二行。","丹爐飞鐵驰炎焰，炎霞爍電吐明光。","綠軿紺幰紛如霧，節鼓清笳前啓路。","城隅靡靡稍东還，橋上鱗鱗轉南渡。","五方观者聚中京，四合塵煙漲洛城。","商女香车珠結網，天人寶马玉繁纓。","百壺淥酒千斤肉，大道連延障錦軸。","先祝聖人壽万年，复禱宜家承百祿。","珊瑚刻盤青玉尊，因之假道入梁园。","梁园山竹凝云漢，仰望高楼在天半。","翠幕蘭堂蘇合薰，珠簾掛戶水波紋。","別起芙蓉织成帳，金鏤鴛鴦兩相向。","罽茵飾地承琱履，花燭分階移錦帳。","织女西垂隐燭台，雙童連縷合歡杯。","藹藹綺庭嬪從列，娥娥紅粉扇中开。","黄金兩印雙花綬，富貴婚姻古無有。","清歌棠棣美王姬，流化邦人正夫婦。"]', '诗', 'shi', '', NULL, '安樂郡主花燭行 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4298afa3-c537-4947-9430-68f5a2348abb', '離會曲', '離會曲', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["何處送客洛橋頭，洛水泛泛中行舟。","可憐河樹葉萎蕤，關關河鳥聲相思。","街鼓喧喧日將夕，去棹歸軒兩相迫。"]', '["何处送客洛橋头，洛水泛泛中行舟。","可怜河樹葉萎蕤，关关河鸟声相思。","街鼓喧喧日將夕，去棹归軒兩相迫。"]', '诗', 'shi', '', NULL, '離會曲 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af126201-9a4d-428b-bd37-7e951d5eae31', '鄴都引', '鄴都引', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["君不見魏武草創爭天祿，羣雄睚眦相馳逐。","晝攜壯士破堅陣，夜接詞人賦華屋。","都邑繚繞西山陽，桑榆汗漫漳河曲。","城郭爲虛人代改，但有西園明月在。","鄴傍高冢多貴臣，娥眉𥊑睩共灰塵。","試上銅臺歌舞處，唯有秋風愁殺人。"]', '["君不见魏武草創爭天祿，羣雄睚眦相驰逐。","晝携壯士破堅陣，夜接词人賦华屋。","都邑繚繞西山陽，桑榆汗漫漳河曲。","城郭爲虛人代改，但有西园明月在。","鄴傍高冢多貴臣，娥眉𥊑睩共灰塵。","試上銅台歌舞处，唯有秋风愁殺人。"]', '诗', 'shi', '', NULL, '鄴都引 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc42d018-5e64-4501-be9b-0fa22cd98573', '城南亭作', '城南亭作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["珂馬朝歸連萬石，矟門洞啓親迎客。","北堂珍重琥珀酒，庭前列肆茱萸席。","長袖遲回意緒多，清商緩轉[目]騰波。","舊傳比翼侯家舞，新出將雛主第歌。","漢家絳灌餘兵氣，晉代浮虛安足貴。","正逢天下金鏡清，偏加日飲醇醪意。","誰復遨遊不復歸，閑庭莫畏不芳菲。","會待城南春色至，竟將花柳拂羅衣。"]', '["珂马朝归連万石，矟门洞啓親迎客。","北堂珍重琥珀酒，庭前列肆茱萸席。","长袖遲回意緒多，清商緩轉[目]腾波。","旧傳比翼侯家舞，新出將雛主第歌。","漢家絳灌餘兵氣，晉代浮虛安足貴。","正逢天下金镜清，偏加日饮醇醪意。","誰复遨游不复归，闲庭莫畏不芳菲。","會待城南春色至，竟將花柳拂羅衣。"]', '诗', 'shi', '', NULL, '城南亭作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1616dac6-2614-4e48-a757-43d7ff1ad31b', '同趙侍御乾湖作', '同趙侍御乾湖作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["江南湖水咽山川，春江溢入共湖連。","氣色紛淪橫罩海，波濤鼓怒上漫天。","鱗宗殼族嬉爲府，弋叟罛師利焉聚。","欹帆側柁弄風口，赴險臨深繞灣浦。","一灣一浦悵邅迴，千曲千溠怳迷哉。","乍見靈妃含笑往，復聞遊女怨歌來。","暑來寒往運洄洑，潭生水落移陵谷。","雲間墜翮散泥沙，波上浮查棲樹木。","昨暮飛霜下北津，今朝行雁度南濱。","處處溝洚清源竭，年年舊葦白頭新。","天地盈虛尚難保，人間倚伏何須道。","秋月皛皛泛澄瀾，冬景青青步纖草。","念君宿昔觀物變，安得躊躕不衰老。"]', '["江南湖水咽山川，春江溢入共湖連。","氣色紛淪橫罩海，波濤鼓怒上漫天。","鱗宗殼族嬉爲府，弋叟罛師利焉聚。","欹帆側柁弄风口，赴險臨深繞灣浦。","一灣一浦悵邅迴，千曲千溠怳迷哉。","乍见靈妃含笑往，复闻游女怨歌来。","暑来寒往運洄洑，潭生水落移陵谷。","云间墜翮散泥沙，波上浮查棲樹木。","昨暮飞霜下北津，今朝行雁度南濱。","处处溝洚清源竭，年年旧葦白头新。","天地盈虛尚难保，人间倚伏何須道。","秋月皛皛泛澄瀾，冬景青青步纖草。","念君宿昔观物变，安得躊躕不衰老。"]', '诗', 'shi', '', NULL, '同趙侍御乾湖作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47d109f-2493-47bf-8dbe-442c5edb625f', '巡邊在河北作', '巡邊在河北作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["去年六月西河西，今年六月北河北。","沙場磧路何爲爾，重氣輕生知許國。","人生在世能幾時，壯年征戰髪如絲。","會待安邊報明主，作頌封山也未遲。"]', '["去年六月西河西，今年六月北河北。","沙場磧路何爲爾，重氣轻生知許国。","人生在世能幾时，壯年征戰髪如絲。","會待安邊報明主，作頌封山也未遲。"]', '诗', 'shi', '', NULL, '巡邊在河北作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1519da86-7f1b-4f2b-8f2d-43b1def6ebe6', '贈崔二安平公樂世詞', '贈崔二安平公乐世词', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["十五紅粧侍綺樓，朝承握槊夜藏鉤。","君臣一意金門寵，兄弟雙飛玉殿遊。","寧知宿昔恩華樂，變作瀟湘離別愁。","地濕莓苔生舞袖，江聲怨歎入箜篌。","自憐京兆雙眉嫵，會待南來五馬留。"]', '["十五紅粧侍綺楼，朝承握槊夜藏鉤。","君臣一意金门寵，兄弟雙飞玉殿游。","寧知宿昔恩华乐，变作瀟湘離別愁。","地濕莓苔生舞袖，江声怨歎入箜篌。","自怜京兆雙眉嫵，會待南来五马留。"]', '诗', 'shi', '', NULL, '贈崔二安平公樂世詞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bd00a3-d714-42b6-900b-6927d205d0e5', '送尹補闕元凱琴歌', '送尹補闕元凱琴歌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["鳳哉鳳哉！啄琅玕。","飲瑤池，棲崑崙之山哉。","中國有聖人，感和氣。","飛來飛來，自歌自舞。","先王冊府，麒鱗之臺。","羇雌衆雛故山曲，其鳴喈喈。","其鳴喈喈，欲往銜之歘去來。","去別鸞鳳心徘徊，明年阿閣梧桐花葉開。","羣飛鳳歸來，羣飛鳳歸來。"]', '["鳳哉鳳哉！啄琅玕。","饮瑤池，棲崑崙之山哉。","中国有聖人，感和氣。","飞来飞来，自歌自舞。","先王冊府，麒鱗之台。","羇雌衆雛故山曲，其鳴喈喈。","其鳴喈喈，欲往銜之歘去来。","去別鸾鳳心徘徊，明年阿閣梧桐花葉开。","羣飞鳳归来，羣飞鳳归来。"]', '诗', 'shi', '', NULL, '送尹補闕元凱琴歌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db523ba-e9d5-4ff6-be82-eb84617d064a', '送考功武員外學士使嵩山署舍利塔', '送考功武員外学士使嵩山署舍利塔', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["懷玉泉，戀仁者，寂滅真心不可見。","空留影塔嵩巖下，寶王四海轉千輪。","金曇百粒送分身，山中二月娑羅會。","虛唄遙遙愁思人，我念過去微塵劫。","與子禪門同正法，雖在神仙蘭省間。","常持清淨蓮花葉，來亦好，去亦好。","了觀車行馬不移，當見菩提離煩惱。"]', '["懷玉泉，戀仁者，寂滅真心不可见。","空留影塔嵩巖下，寶王四海轉千輪。","金曇百粒送分身，山中二月娑羅會。","虛唄遙遙愁思人，我念過去微塵劫。","與子禪门同正法，雖在神仙蘭省间。","常持清淨蓮花葉，来亦好，去亦好。","了观车行马不移，當见菩提離煩惱。"]', '诗', 'shi', '', NULL, '送考功武員外學士使嵩山署舍利塔 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4460d2c-7917-4469-8b05-9c74d892acc2', '遙同蔡起居偃松篇', '遙同蔡起居偃松篇', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["清都衆木總榮芬，傳道孤松最出羣。","名接天庭長景色，氣連宮闕借氛氳。","懸池的的停華露，偃蓋重重拂瑞雲。","不借流膏助仙鼎，願將楨幹捧明君。","莫比冥靈楚南樹，朽老江邊代不聞。"]', '["清都衆木總榮芬，傳道孤松最出羣。","名接天庭长景色，氣連宮闕借氛氳。","懸池的的停华露，偃蓋重重拂瑞云。","不借流膏助仙鼎，願將楨幹捧明君。","莫比冥靈楚南樹，朽老江邊代不闻。"]', '诗', 'shi', '', NULL, '遙同蔡起居偃松篇 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c849dec-be6c-4ac3-a4e0-f1630382f983', '奉和聖製登驪山矚眺應制', '奉和聖製登驪山矚眺應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寒山上半空，臨眺盡寰中。","是日巡遊處，晴光遠近同。","川明分渭水，樹暗辨新豐。","巖壑清音暮，天歌起大風。"]', '["寒山上半空，臨眺尽寰中。","是日巡游处，晴光远近同。","川明分渭水，樹暗辨新豐。","巖壑清音暮，天歌起大风。"]', '诗', 'shi', '', NULL, '奉和聖製登驪山矚眺應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d34e11c4-2cd3-4bba-aa49-a7c7cbd2b263', '奉和聖製幸白鹿觀應制', '奉和聖製幸白鹿观應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["洞府寒山曲，天遊日旰迴。","披雲看石鏡，拂雪上金臺。","竹徑龍驂下，松庭鶴轡來。","雙童還獻藥，五色耀仙材。"]', '["洞府寒山曲，天游日旰迴。","披云看石镜，拂雪上金台。","竹徑龙驂下，松庭鹤轡来。","雙童還獻藥，五色耀仙材。"]', '诗', 'shi', '', NULL, '奉和聖製幸白鹿觀應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e768ab09-3e55-4536-bbbf-7056e742df09', '奉和聖製送金城公主適西蕃應制', '奉和聖製送金城公主適西蕃應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["青海和親日，潢星出降時。","戎王子壻寵，漢國舅家慈。","春野開離讌，雲天起別詞。","空彈馬上曲，詎減鳳樓思。"]', '["青海和親日，潢星出降时。","戎王子壻寵，漢国舅家慈。","春野开離讌，云天起別词。","空彈马上曲，詎減鳳楼思。"]', '诗', 'shi', '', NULL, '奉和聖製送金城公主適西蕃應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af6e859-f802-42c8-bbe6-3b4a7c29c6ed', '奉和同皇太子過慈恩寺應制二首 一', '奉和同皇太子過慈恩寺應制二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["翼翼宸恩永，煌煌福地開。","離光升寶殿，震氣繞香臺。","上界幡花合，中天伎樂來。","願君無量壽，仙樂屢徘徊。"]', '["翼翼宸恩永，煌煌福地开。","離光升寶殿，震氣繞香台。","上界幡花合，中天伎乐来。","願君無量壽，仙乐屢徘徊。"]', '诗', 'shi', '', NULL, '奉和同皇太子過慈恩寺應制二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d4c272-ef65-45c4-828a-cd6d774c044e', '奉和同皇太子過慈恩寺應制二首 二', '奉和同皇太子過慈恩寺應制二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["朗朗神居峻，軒軒瑞象威。","聖君成願果，太子拂天衣。","至樂三靈會，深仁四皓歸。","還聞渦水曲，更繞白雲飛。"]', '["朗朗神居峻，軒軒瑞象威。","聖君成願果，太子拂天衣。","至乐三靈會，深仁四皓归。","還闻渦水曲，更繞白云飞。"]', '诗', 'shi', '', NULL, '奉和同皇太子過慈恩寺應制二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f44d4ff-b703-48b0-b9c1-33cb0ee89291', '侍宴武三思山第應制賦得風字', '侍宴武三思山第應制賦得风字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["梁王池館好，曉日鳳樓通。","竹町羅千衞，蘭筵降兩宮。","清歌芳樹下，妙舞落花中。","臣覺筵中聽，還如大國風。"]', '["梁王池館好，晓日鳳楼通。","竹町羅千衞，蘭筵降兩宮。","清歌芳樹下，妙舞落花中。","臣覺筵中听，還如大国风。"]', '诗', 'shi', '', NULL, '侍宴武三思山第應制賦得風字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de32b002-29b2-40b4-a0bc-d5f8c6bed778', '奉和聖製過寧王宅應制', '奉和聖製過寧王宅應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["進酒忘憂觀，簫韶喜降臨。","帝堯敦族禮，王季友兄心。","竹院龍鳴笛，梧宮鳳遶林。","大風將小雅，一字盡千金。"]', '["進酒忘憂观，簫韶喜降臨。","帝堯敦族禮，王季友兄心。","竹院龙鳴笛，梧宮鳳遶林。","大风將小雅，一字尽千金。"]', '诗', 'shi', '', NULL, '奉和聖製過寧王宅應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33036605-ce3a-4a5c-b40d-b46716dbbad4', '奉和聖製同玉真公主過大哥山池題石壁應制', '奉和聖製同玉真公主過大哥山池題石壁應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["綠竹初成苑，丹砂欲化金。","乘龍與驂鳳，歌吹滿山林。","爽氣凝情逈，寒光映浦深。","忘憂題此觀，爲樂賞同心。"]', '["綠竹初成苑，丹砂欲化金。","乘龙與驂鳳，歌吹满山林。","爽氣凝情逈，寒光映浦深。","忘憂題此观，爲乐賞同心。"]', '诗', 'shi', '', NULL, '奉和聖製同玉真公主過大哥山池題石壁應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6407377d-1574-4304-99f6-789b048ae451', '奉和聖製賜王公千秋鏡應制', '奉和聖製賜王公千秋镜應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寶鏡頒神節，凝規寫聖情。","千秋題作字，長壽帶爲名。","月向天邊下，花從日裏生。","不承懸象意，誰辨照心明。"]', '["寶镜頒神節，凝規寫聖情。","千秋題作字，长壽带爲名。","月向天邊下，花從日裏生。","不承懸象意，誰辨照心明。"]', '诗', 'shi', '', NULL, '奉和聖製賜王公千秋鏡應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f47ce43e-7f0e-48fa-b586-da5ba8b68fc8', '奉和聖製經鄒魯祭孔子應制', '奉和聖製經鄒魯祭孔子應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["孔聖家鄒魯，儒風藹典墳。","龍驂廻舊宅，鳳德詠餘芬。","入室神如在，升堂樂似聞。","懸知一王法，今日待明君。"]', '["孔聖家鄒魯，儒风藹典墳。","龙驂廻旧宅，鳳德詠餘芬。","入室神如在，升堂乐似闻。","懸知一王法，今日待明君。"]', '诗', 'shi', '', NULL, '奉和聖製經鄒魯祭孔子應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75055ddf-124c-4628-9ee3-75914bc7dea1', '侍宴蘘荷亭應制', '侍宴蘘荷亭應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["回鑾青嶽觀，帳殿紫煙峰。","仙路迎三鳥，雲衢駐兩龍。","園林看化塔，壇墠識餘封。","山外聞簫管，還如天上逢。"]', '["回鑾青嶽观，帳殿紫煙峰。","仙路迎三鸟，云衢駐兩龙。","园林看化塔，壇墠識餘封。","山外闻簫管，還如天上逢。"]', '诗', 'shi', '', NULL, '侍宴蘘荷亭應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b90d94-8519-4966-9993-2808a4dc2f24', '侍宴滻水賦得濃字', '侍宴滻水賦得濃字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["千行發御柳，一葉下仙筇。","青浦宸遊至，朱城佳氣濃。","雲霞交暮色，草樹喜春容。","藹藹天旗轉，清笳入九重。"]', '["千行發御柳，一葉下仙筇。","青浦宸游至，朱城佳氣濃。","云霞交暮色，草樹喜春容。","藹藹天旗轉，清笳入九重。"]', '诗', 'shi', '', NULL, '侍宴滻水賦得濃字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98b9c819-c287-4a62-b844-f08172081922', '奉和聖製同劉晃喜雨應制', '奉和聖製同劉晃喜雨應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["青氣含春雨，知從岱嶽來。","行雲避師出，灑雨待車廻。","厭浥塵清道，空濛柳映臺。","最宜三五夜，晴月九重開。"]', '["青氣含春雨，知從岱嶽来。","行云避師出，灑雨待车廻。","厭浥塵清道，空濛柳映台。","最宜三五夜，晴月九重开。"]', '诗', 'shi', '', NULL, '奉和聖製同劉晃喜雨應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('747c9605-90bf-4d94-ad6c-ad75a674f482', '奉和聖製觀拔河俗戲應制', '奉和聖製观拔河俗戲應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["今歲好拖鉤，橫銜敞御樓。","長繩繫日住，貫索挽河流。","鬬力頻催鼓，爭都更上籌。","春來百種戲，天意在宜秋。"]', '["今歲好拖鉤，橫銜敞御楼。","长繩繫日住，貫索挽河流。","鬬力頻催鼓，爭都更上籌。","春来百種戲，天意在宜秋。"]', '诗', 'shi', '', NULL, '奉和聖製觀拔河俗戲應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c35fe3-c3aa-41d9-ab4f-b2dcc6b588cf', '奉和聖製途次陝州應制', '奉和聖製途次陝州應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["周召嘗分陝，詩書空復傳。","何如萬乘睠，追賞二南篇。","郡帶洪河側，宮臨大道邊。","洛城將日近，佳氣滿山川。"]', '["周召嘗分陝，诗书空复傳。","何如万乘睠，追賞二南篇。","郡带洪河側，宮臨大道邊。","洛城將日近，佳氣满山川。"]', '诗', 'shi', '', NULL, '奉和聖製途次陝州應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09003398-8839-4c09-a6ce-a5730b4e1838', '奉和聖製野次喜雪應制', '奉和聖製野次喜雪應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寒更玉漏催，曉色御前開。","泱漭雲陰積，氤氳風雪廻。","山知銀作甕，宮見璧成臺。","欲驗豐年象，飄搖仙藻來。"]', '["寒更玉漏催，晓色御前开。","泱漭云陰積，氤氳风雪廻。","山知銀作甕，宮见璧成台。","欲驗豐年象，飄搖仙藻来。"]', '诗', 'shi', '', NULL, '奉和聖製野次喜雪應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3a45f6-f45a-4e0a-a8a4-aabfba6ac1de', '奉和聖製溫泉言志應制', '奉和聖製溫泉言志應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["溫谷媚新豐，驪山橫半空。","湯池薰水殿，翠木暖煙宮。","起疾逾仙藥，無私合聖功。","始知堯舜德，心與萬人同。"]', '["溫谷媚新豐，驪山橫半空。","湯池薰水殿，翠木暖煙宮。","起疾逾仙藥，無私合聖功。","始知堯舜德，心與万人同。"]', '诗', 'shi', '', NULL, '奉和聖製溫泉言志應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731f0cd1-37cc-40e9-bd76-b2c75ff08f00', '皇帝降誕日集賢殿賜宴', '皇帝降誕日集賢殿賜宴', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["仲秋金帝起，五日土行昭。","瑞表壬寅露，光傳甲子宵。","陰風吹大澤，夢日照昌朝。","不獨華封老，千年喜祝堯。"]', '["仲秋金帝起，五日土行昭。","瑞表壬寅露，光傳甲子宵。","陰风吹大澤，梦日照昌朝。","不独华封老，千年喜祝堯。"]', '诗', 'shi', '', NULL, '皇帝降誕日集賢殿賜宴 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632a1b6e-2fbe-487e-9648-e79134ff15f4', '晦日詔宴永穆公主亭子賦得流字', '晦日詔宴永穆公主亭子賦得流字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["堂邑山林美，朝恩晦日遊。","園亭含淑氣，竹樹遶春流。","舞席千花妓，歌船五彩樓。","羣歡與王澤，歲歲滿皇州。"]', '["堂邑山林美，朝恩晦日游。","园亭含淑氣，竹樹遶春流。","舞席千花妓，歌船五彩楼。","羣歡與王澤，歲歲满皇州。"]', '诗', 'shi', '', NULL, '晦日詔宴永穆公主亭子賦得流字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408d5a1a-2138-4212-9d31-8f86d17d38b1', '恩制賜食於麗正殿書院宴賦得林字', '恩制賜食於丽正殿书院宴賦得林字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["東壁圖書府，西園翰墨林。","誦詩聞國政，講易見天心。","位竊和羹重，恩叨醉酒深。","緩歌春興曲，情竭爲知音。"]', '["东壁圖书府，西园翰墨林。","誦诗闻国政，講易见天心。","位竊和羹重，恩叨醉酒深。","緩歌春兴曲，情竭爲知音。"]', '诗', 'shi', '', NULL, '恩制賜食於麗正殿書院宴賦得林字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f2a004-7042-4a89-9cda-c9e238b1cc5b', '羽林恩召觀御書王太尉碑', '羽林恩召观御书王太尉碑', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["隴首名公石，來承聖札歸。","魚龍生意態，鉤劒動鋩輝。","字得神明保，詞慙少女徽。","誰家羽林將，又逐鳳書飛。"]', '["隴首名公石，来承聖札归。","鱼龙生意態，鉤劒动鋩輝。","字得神明保，词慙少女徽。","誰家羽林將，又逐鳳书飞。"]', '诗', 'shi', '', NULL, '羽林恩召觀御書王太尉碑 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b9bb50-2d2a-46be-bff0-31d7061c0399', '東都酺宴四首 一', '东都酺宴四首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["重華昇寶曆，軒帝眇閑居。","政成天子孝，俗返上皇初。","忘味因觀樂，歡心寄合酺。","自憐疲馬意，戀戀主恩餘。"]', '["重华昇寶曆，軒帝眇闲居。","政成天子孝，俗返上皇初。","忘味因观乐，歡心寄合酺。","自怜疲马意，戀戀主恩餘。"]', '诗', 'shi', '', NULL, '東都酺宴四首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73298021-0132-4783-806e-fe1e8eb036fc', '東都酺宴四首 二', '东都酺宴四首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["朱城塵曀滅，翠幕景情開。","震震靈鼉起，翔翔舞鳳來。","雕盤裝草樹，綺乘結樓臺。","共喜光華日，酣歌捧玉杯。"]', '["朱城塵曀滅，翠幕景情开。","震震靈鼉起，翔翔舞鳳来。","雕盤裝草樹，綺乘結楼台。","共喜光华日，酣歌捧玉杯。"]', '诗', 'shi', '', NULL, '東都酺宴四首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db1ed665-4598-4165-a6ed-c2c027ef6fe8', '東都酺宴四首 三', '东都酺宴四首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["曉月調金闕，朝暾對玉盤。","爭馳羣鳥散，鬬伎百花團。","遇聖人知幸，承恩物自歡。","洛橋將舉燭，醉舞拂歸鞍。"]', '["晓月調金闕，朝暾对玉盤。","爭驰羣鸟散，鬬伎百花團。","遇聖人知幸，承恩物自歡。","洛橋將舉燭，醉舞拂归鞍。"]', '诗', 'shi', '', NULL, '東都酺宴四首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e88877-e4fb-4912-a6d4-c3c9ca45e84d', '東都酺宴四首 四', '东都酺宴四首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["愷宴惟今席，餘歡殊未窮。","入雲歌嫋嫋，向日伎叢叢。","駛管催酣興，留關待曲終。","長安若爲樂，應與萬方同。"]', '["愷宴惟今席，餘歡殊未窮。","入云歌嫋嫋，向日伎叢叢。","駛管催酣兴，留关待曲終。","长安若爲乐，應與万方同。"]', '诗', 'shi', '', NULL, '東都酺宴四首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d8ec10-5701-49f4-911d-e0bf0ff0b179', '道家四首奉敕撰 一', '道家四首奉敕撰 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["金壇啓曙闈，真氣肅微微。","落月銜仙竇，初霞拂羽衣。","香隨龍節下，雲逐鳳簫飛。","暫住蓬萊戲，千年始一歸。"]', '["金壇啓曙闈，真氣肅微微。","落月銜仙竇，初霞拂羽衣。","香隨龙節下，云逐鳳簫飞。","暫住蓬萊戲，千年始一归。"]', '诗', 'shi', '', NULL, '道家四首奉敕撰 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b52608e-68e4-4ff7-aca2-f385ac7eb4cc', '道家四首奉敕撰 二', '道家四首奉敕撰 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["窈窕流精觀，深沈紫翠庭。","金匳調上藥，寶案讀仙經。","作賦看神雨，乘槎辨客星。","秪應謝人俗，輕舉托雲軿。"]', '["窈窕流精观，深沈紫翠庭。","金匳調上藥，寶案读仙經。","作賦看神雨，乘槎辨客星。","秪應謝人俗，轻舉托云軿。"]', '诗', 'shi', '', NULL, '道家四首奉敕撰 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b1933b1-1971-4c5a-b8c7-c9fcd9531464', '道家四首奉敕撰 三', '道家四首奉敕撰 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["金爐承道訣，玉牒啓玄機。","雲逐笙歌度，星流宮殿飛。","乘風嬉浩蕩，窺月弄光輝。","唯有三山鶴，應同千載歸。"]', '["金爐承道訣，玉牒啓玄機。","云逐笙歌度，星流宮殿飞。","乘风嬉浩蕩，窺月弄光輝。","唯有三山鹤，應同千載归。"]', '诗', 'shi', '', NULL, '道家四首奉敕撰 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe376a0-6337-4ef8-b2ba-7f8d80ecc10b', '道家四首奉敕撰 四', '道家四首奉敕撰 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["道記開中籙，真官表上清。","焚香三鳥至，煉藥九仙成。","天上靈書下，空中妙伎迎。","迎來出煙霧，渺渺戲蓬瀛。"]', '["道記开中籙，真官表上清。","焚香三鸟至，煉藥九仙成。","天上靈书下，空中妙伎迎。","迎来出煙霧，渺渺戲蓬瀛。"]', '诗', 'shi', '', NULL, '道家四首奉敕撰 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a9b373c-d05e-40bb-9723-4e79166c8557', '鳳樓尋勝地', '鳳楼尋勝地', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西掖持醇酒，東山就白雲。","開軒綠池映，命席紫蘭芬。","舞度花爲伴，鶯來管作羣。","太平多樂事，春物共氛氳。"]', '["西掖持醇酒，东山就白云。","开軒綠池映，命席紫蘭芬。","舞度花爲伴，鶯来管作羣。","太平多乐事，春物共氛氳。"]', '诗', 'shi', '', NULL, '鳳樓尋勝地 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57cb7c60-6ef4-4ba3-be91-13b1a5a9c3d5', '幽州夜飲', '幽州夜饮', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["涼風吹夜雨，蕭瑟動寒林。","正有高堂宴，能忘遲暮心。","軍中宜劒舞，塞上重笳音。","不作邊城將，誰知恩遇深。"]', '["涼风吹夜雨，蕭瑟动寒林。","正有高堂宴，能忘遲暮心。","軍中宜劒舞，塞上重笳音。","不作邊城將，誰知恩遇深。"]', '诗', 'shi', '', NULL, '幽州夜飲 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26d418d-e816-4ef1-bfeb-5266aa57eb74', '崔禮部園亭得深字', '崔禮部园亭得深字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["窈窕留清館，虛徐步晚陰。","水連伊闕近，樹接夏陽深。","柳蔓憐垂拂，藤梢愛上尋。","訝君軒蓋侶，非復俗人心。"]', '["窈窕留清館，虛徐步晚陰。","水連伊闕近，樹接夏陽深。","柳蔓怜垂拂，藤梢愛上尋。","訝君軒蓋侶，非复俗人心。"]', '诗', 'shi', '', NULL, '崔禮部園亭得深字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2274cb47-305e-49bb-90c3-2f7d45153bdd', '送鄭大夫惟忠從公主入蕃', '送鄭大夫惟忠從公主入蕃', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["鳳吹遙將斷，龍旗送欲還。","傾都邀節使，傳酌緩離顏。","春磧沙連海，秋城月對關。","和戎因賞魏，定遠莫辭班。"]', '["鳳吹遙將斷，龙旗送欲還。","傾都邀節使，傳酌緩離顏。","春磧沙連海，秋城月对关。","和戎因賞魏，定远莫辞班。"]', '诗', 'shi', '', NULL, '送鄭大夫惟忠從公主入蕃 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42417af2-2744-4dc2-9f2b-f1f2579009d3', '送崔二長史日知赴潞州', '送崔二长史日知赴潞州', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["東山懷臥理，南省悵悲翁。","共見前途促，何知後會同。","莫輕一筵宴，明日半成空。","況爾新離闕，思歸迷夢中。"]', '["东山懷臥理，南省悵悲翁。","共见前途促，何知後會同。","莫轻一筵宴，明日半成空。","況爾新離闕，思归迷梦中。"]', '诗', 'shi', '', NULL, '送崔二長史日知赴潞州 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6eaa0da-11c3-44cf-9234-36e91ea5d8a8', '同賀八送兗公赴荆州', '同賀八送兗公赴荆州', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["疇昔同聲友，騫飛出鳳池。","風雲一蕩薄，日月屢參差。","此別黃葉下，前期安可知。","誰憐楚南樹，不爲歲寒移。"]', '["疇昔同声友，騫飞出鳳池。","风云一蕩薄，日月屢參差。","此別黄葉下，前期安可知。","誰怜楚南樹，不爲歲寒移。"]', '诗', 'shi', '', NULL, '同賀八送兗公赴荆州 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43da0758-7295-4538-aa20-35af9e371ee3', '餞唐州高使君', '餞唐州高使君', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["常時好閑獨，朋舊少相過。","及爾宣風去，方嗟別日多。","淮流春晼晚，江海路蹉跎。","百歲屢分散，歡言復幾何。"]', '["常时好闲独，朋旧少相過。","及爾宣风去，方嗟別日多。","淮流春晼晚，江海路蹉跎。","百歲屢分散，歡言复幾何。"]', '诗', 'shi', '', NULL, '餞唐州高使君 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4caa7c43-48aa-47ab-8d24-941e2db79553', '送王晙自羽林赴永昌令', '送王晙自羽林赴永昌令', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["將星移北洛，神雨避東京。","爲負剛腸譽，還追強項名。","白雲向伊闕，黃葉散昆明。","多謝弦歌宰，稀聞桴鼓聲。"]', '["將星移北洛，神雨避东京。","爲負剛腸譽，還追強項名。","白云向伊闕，黄葉散昆明。","多謝弦歌宰，稀闻桴鼓声。"]', '诗', 'shi', '', NULL, '送王晙自羽林赴永昌令 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46adbad6-193a-4a69-bd5e-f0252646b181', '同王僕射山亭餞岑廣武羲得言字', '同王僕射山亭餞岑廣武羲得言字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聞道長岑令，奮翼宰旅門。","長安東陌上，送客滿朱軒。","琴爵留佳境，山池借好園。","茲遊恨不見，別後綴離言。"]', '["闻道长岑令，奮翼宰旅门。","长安东陌上，送客满朱軒。","琴爵留佳境，山池借好园。","茲游恨不见，別後綴離言。"]', '诗', 'shi', '', NULL, '同王僕射山亭餞岑廣武羲得言字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9322de4f-e476-4bc0-909a-a2b8736211c3', '送任御史江南發糧以賑河北百姓', '送任御史江南發糧以賑河北百姓', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["河朔人無歲，荆南義廩開。","將興汎舟役，必仗濟川才。","夜月臨江浦，春雲歷楚臺。","調飢坐相望，繡服幾時回。"]', '["河朔人無歲，荆南義廩开。","將兴汎舟役，必仗濟川才。","夜月臨江浦，春云歷楚台。","調飢坐相望，繡服幾时回。"]', '诗', 'shi', '', NULL, '送任御史江南發糧以賑河北百姓 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ea4a2f-60f9-445b-ad9e-c54c15b11ca9', '送王尚一嚴嶷二侍御赴司馬都督軍', '送王尚一嚴嶷二侍御赴司马都督軍', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["漢掖通沙塞，邊兵護草腓。","將行司馬令，助以鐵冠威。","白露鷹初下，黃塵騎欲飛。","明年春酒熟，留酌二星歸。"]', '["漢掖通沙塞，邊兵護草腓。","將行司马令，助以鐵冠威。","白露鷹初下，黄塵騎欲飞。","明年春酒熟，留酌二星归。"]', '诗', 'shi', '', NULL, '送王尚一嚴嶷二侍御赴司馬都督軍 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847ecb84-d347-4e13-a810-528db3163dfd', '送李問政河北簡兵', '送李问政河北簡兵', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["斗酒貽朋愛，躊躕出御溝。","依然四牡別，更想八龍遊。","密親仕燕冀，連年邇寇讐。","因君閱河朔，垂淚語幽州。"]', '["斗酒貽朋愛，躊躕出御溝。","依然四牡別，更想八龙游。","密親仕燕冀，連年邇寇讐。","因君閱河朔，垂泪語幽州。"]', '诗', 'shi', '', NULL, '送李問政河北簡兵 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d80cf61-ce91-4f3c-9c49-01ef44427e14', '送薛植入京', '送薛植入京', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["青組言從史，鴻都忽見求。","款言人向老，飲別歲方秋。","髣髴長安陌，平生是舊遊。","何時復相遇，宛在水中流。"]', '["青組言從史，鴻都忽见求。","款言人向老，饮別歲方秋。","髣髴长安陌，平生是旧游。","何时复相遇，宛在水中流。"]', '诗', 'shi', '', NULL, '送薛植入京 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b351f8-4e44-4109-9e3f-47464b6c740f', '相州前池別許鄭二判官景先神力', '相州前池別許鄭二判官景先神力', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["數步圓塘水，雙鴻戢羽儀。","一飛喬木上，一返故林垂。","澹泊含秋景，虛明抱夜規。","無因留絕翰，雲海意差池。"]', '["數步圓塘水，雙鴻戢羽儀。","一飞喬木上，一返故林垂。","澹泊含秋景，虛明抱夜規。","無因留絕翰，云海意差池。"]', '诗', 'shi', '', NULL, '相州前池別許鄭二判官景先神力 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b169d271-062d-4ba5-b8e4-e8a620a6f804', '岳州宴別潭州王熊二首 一', '岳州宴別潭州王熊二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["絲管清且哀，一曲傾一杯。","氣將然諾重，心向友朋開。","古木無生意，寒雲若死灰。","贈君芳杜草，爲植建章臺。"]', '["絲管清且哀，一曲傾一杯。","氣將然諾重，心向友朋开。","古木無生意，寒云若死灰。","贈君芳杜草，爲植建章台。"]', '诗', 'shi', '', NULL, '岳州宴別潭州王熊二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b51df46-0dc4-4f8a-b960-cf66c4a3adec', '岳州宴別潭州王熊二首 二', '岳州宴別潭州王熊二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["縉雲連省閣，溝水遽西東。","然諾心猶在，榮華歲不同。","孤城臨楚塞，遠樹入秦宮。","誰念三千里，江潭一老翁。"]', '["縉云連省閣，溝水遽西东。","然諾心猶在，榮华歲不同。","孤城臨楚塞，远樹入秦宮。","誰念三千里，江潭一老翁。"]', '诗', 'shi', '', NULL, '岳州宴別潭州王熊二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f848ccb-ab8f-4b0d-8492-9241874c340f', '廣州蕭都督入朝過岳州宴餞得冬字', '廣州蕭都督入朝過岳州宴餞得冬字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["孤城抱大江，節使往朝宗。","果是臺中舊，依然水上逢。","京華遙比日，疲老颯如冬。","竊羨能言鳥，銜恩向九重。"]', '["孤城抱大江，節使往朝宗。","果是台中旧，依然水上逢。","京华遙比日，疲老颯如冬。","竊羨能言鸟，銜恩向九重。"]', '诗', 'shi', '', NULL, '廣州蕭都督入朝過岳州宴餞得冬字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35484a7d-55ec-479c-a90e-31084ead58a2', '岳州別姚司馬紹之制許歸侍', '岳州別姚司马紹之制許归侍', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["和玉悲無已，長沙宦不成。","天從扇枕願，人遂倚門情。","方外懷司馬，江東憶步兵。","問君棲泊處，空嶺夜猿驚。"]', '["和玉悲無已，长沙宦不成。","天從扇枕願，人遂倚门情。","方外懷司马，江东憶步兵。","问君棲泊处，空嶺夜猿驚。"]', '诗', 'shi', '', NULL, '岳州別姚司馬紹之制許歸侍 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7d6df5-d65e-4a4b-ba4c-f86f19e929a6', '送岳州李十從軍桂州', '送岳州李十從軍桂州', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["送客之江上，其人美且才。","風波萬里闊，故舊十年來。","劒拔蛟隨斷，弓張鳥自摧。","陽橋書落落，驛馬定先回。"]', '["送客之江上，其人美且才。","风波万里闊，故旧十年来。","劒拔蛟隨斷，弓張鸟自摧。","陽橋书落落，驛马定先回。"]', '诗', 'shi', '', NULL, '送岳州李十從軍桂州 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9ccaa26-8551-45a7-a699-c78736e20720', '岳州別趙國公王十一琚入朝', '岳州別趙国公王十一琚入朝', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["昔濫貂蟬長，同承雨露霏。","今參魚鱉守，望美洞庭歸。","浦樹懸秋影，江雲燒落輝。","離魂似征帆，恆往帝鄉飛。"]', '["昔濫貂蟬长，同承雨露霏。","今參鱼鱉守，望美洞庭归。","浦樹懸秋影，江云燒落輝。","離魂似征帆，恆往帝乡飞。"]', '诗', 'shi', '', NULL, '岳州別趙國公王十一琚入朝 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f5195f-65b7-410f-973a-6cdb95070def', '岳州別子均', '岳州別子均', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["離筵非燕喜，別酒正銷魂。","念汝猶童孺，嗟予隔遠藩。","津亭拔心草，江路斷腸猿。","他日將何見，愁來獨倚門。"]', '["離筵非燕喜，別酒正銷魂。","念汝猶童孺，嗟予隔远藩。","津亭拔心草，江路斷腸猿。","他日將何见，愁来独倚门。"]', '诗', 'shi', '', NULL, '岳州別子均 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e755ba23-405e-42fa-afbe-a514a2b9b807', '端州別高六戩', '端州別高六戩', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["異壤同羈竄，途中喜共過。","愁多時舉酒，勞罷或長歌。","南海風潮壯，西江瘴癘多。","於焉復分手，此別傷如何。"]', '["異壤同羈竄，途中喜共過。","愁多时舉酒，勞罷或长歌。","南海风潮壯，西江瘴癘多。","於焉复分手，此別傷如何。"]', '诗', 'shi', '', NULL, '端州別高六戩 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ab2824-2a44-4aaf-9ae2-5df8dbc96753', '南中別蔣五岑向青州', '南中別蔣五岑向青州', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["老親依北海，賤子棄南荒。","有淚皆成血，無聲不斷腸。","此中逢故友，彼地送還鄉。","願作楓林葉，隨君度洛陽。"]', '["老親依北海，賤子棄南荒。","有泪皆成血，無声不斷腸。","此中逢故友，彼地送還乡。","願作楓林葉，隨君度洛陽。"]', '诗', 'shi', '', NULL, '南中別蔣五岑向青州 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9732735-65bf-471f-bdb0-2fd5a4a765b7', '南中別陳七李十', '南中別陳七李十', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["二年共遊處，一旦各西東。","請君聊駐馬，看我轉征蓬。","畫鷁愁南海，離駒思北風。","何時似春雁，雙入上林中。"]', '["二年共游处，一旦各西东。","請君聊駐马，看我轉征蓬。","畫鷁愁南海，離駒思北风。","何时似春雁，雙入上林中。"]', '诗', 'shi', '', NULL, '南中別陳七李十 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9134a60e-1366-424b-baa3-634f3ddbbd52', '南中別王陵成崇', '南中別王陵成崇', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["握手與君別，歧路贈一言。","曹卿禮公子，楚媼饋王孫。","倏爾生六翮，翻飛戾九門。","常懷客鳥意，會答主人恩。"]', '["握手與君別，歧路贈一言。","曹卿禮公子，楚媼饋王孫。","倏爾生六翮，翻飞戾九门。","常懷客鸟意，會答主人恩。"]', '诗', 'shi', '', NULL, '南中別王陵成崇 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a3e739-43a9-4425-b2d1-0d8350ba852b', '嶺南送使', '嶺南送使', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["秋雁逢春返，流人何日歸？","將余去國淚，灑子入鄉衣。","飢狖啼相聚，愁猿喘更飛。","南中不可問，書此示京畿。"]', '["秋雁逢春返，流人何日归？","將余去国泪，灑子入乡衣。","飢狖啼相聚，愁猿喘更飞。","南中不可问，书此示京畿。"]', '诗', 'shi', '', NULL, '嶺南送使 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b15384f-f05f-4b0e-a131-af5e4162d3a4', '幽州別陰長河行先', '幽州別陰长河行先', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["惠好交情重，辛勤世事多。","荆南久爲別，薊北遠來過。","寄目雲中鳥，留歡酒上歌。","影移春復間，遲暮兩如何。"]', '["惠好交情重，辛勤世事多。","荆南久爲別，薊北远来過。","寄目云中鸟，留歡酒上歌。","影移春复间，遲暮兩如何。"]', '诗', 'shi', '', NULL, '幽州別陰長河行先 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8665b35-36e5-4230-9d54-234c61e341a0', '和朱使欣道峽似巫山之作', '和朱使欣道峽似巫山之作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["江如曉天淨，石似暮霞張。","征帆一流覽，宛若巫山陽。","楚客思歸路，秦人謫異鄉。","猿鳴孤月夜，再使淚沾裳。"]', '["江如晓天淨，石似暮霞張。","征帆一流覽，宛若巫山陽。","楚客思归路，秦人謫異乡。","猿鳴孤月夜，再使泪沾裳。"]', '诗', 'shi', '', NULL, '和朱使欣道峽似巫山之作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83214349-d778-44de-9f0f-5b3d627ebad3', '和朱使欣二首 一', '和朱使欣二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["南土多爲寇，西江盡畏途。","山行阻篁竹，水宿礙萑蒲。","使越才應有，征蠻力豈無。","空傳人贈劒，不見虎銜珠。"]', '["南土多爲寇，西江尽畏途。","山行阻篁竹，水宿礙萑蒲。","使越才應有，征蠻力豈無。","空傳人贈劒，不见虎銜珠。"]', '诗', 'shi', '', NULL, '和朱使欣二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0362b9af-d549-4eaf-8361-0f2f531ee392', '和朱使欣二首 二', '和朱使欣二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["江勢連山遠，天涯此夜愁。","霜空極天靜，寒月帶江流。","思起南征棹，文高北望樓。","自憐如墜葉，泛泛侶仙舟。"]', '["江勢連山远，天涯此夜愁。","霜空極天静，寒月带江流。","思起南征棹，文高北望楼。","自怜如墜葉，泛泛侶仙舟。"]', '诗', 'shi', '', NULL, '和朱使欣二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fae120f-15c9-4eef-82a9-f7ca563e06a1', '過庾信宅', '過庾信宅', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["蘭成追宋玉，舊宅偶詞人。","筆湧江山氣，文驕雲雨神。","包胥非救楚，隨會反留秦。","獨有東陽守，來嗟古樹春。"]', '["蘭成追宋玉，旧宅偶词人。","笔湧江山氣，文驕云雨神。","包胥非救楚，隨會反留秦。","独有东陽守，来嗟古樹春。"]', '诗', 'shi', '', NULL, '過庾信宅 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05133f97-474d-4030-91f6-fdc78b04afcc', '盧巴驛聞張御史張判官欲到不得待留贈之', '盧巴驛闻張御史張判官欲到不得待留贈之', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["旅竄南方遠，傳聞北使來。","舊庭知玉樹，合浦識珠胎。","白髮因愁改，丹心托夢廻。","皇恩若再造，爲憶不然灰。"]', '["旅竄南方远，傳闻北使来。","旧庭知玉樹，合浦識珠胎。","白髮因愁改，丹心托梦廻。","皇恩若再造，爲憶不然灰。"]', '诗', 'shi', '', NULL, '盧巴驛聞張御史張判官欲到不得待留贈之 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c5487f-370a-4f0b-8395-ce185814ac2a', '南中贈高六戩', '南中贈高六戩', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["北極辭明代，南溟宅放臣。","丹誠由義盡，白髮帶愁新。","鳥墜炎洲氣，花飛洛水春。","平生歌舞席，誰憶不歸人。"]', '["北極辞明代，南溟宅放臣。","丹誠由義尽，白髮带愁新。","鸟墜炎洲氣，花飞洛水春。","平生歌舞席，誰憶不归人。"]', '诗', 'shi', '', NULL, '南中贈高六戩 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5033e04-6379-4c84-a7ad-6a387748cee9', '岳州山城', '岳州山城', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["山城豐日暇，閉戶見天心。","東曠迎朝色，西樓引夕陰。","書觀千載近，學靜二毛深。","忽有南風至，吹君堂上琴。"]', '["山城豐日暇，閉戶见天心。","东曠迎朝色，西楼引夕陰。","书观千載近，学静二毛深。","忽有南风至，吹君堂上琴。"]', '诗', 'shi', '', NULL, '岳州山城 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc309e8-0d5f-462b-ae8a-30f4d2801bbc', '和尹懋秋夜遊㴩湖', '和尹懋秋夜游㴩湖', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["㴩湖佳可遊，既近復能幽。","林裏棲精舍，山間轉去舟。","雁飛江月冷，猿嘯野風秋。","不是迷鄉客，尋奇處處留。"]', '["㴩湖佳可游，既近复能幽。","林裏棲精舍，山间轉去舟。","雁飞江月冷，猿嘯野风秋。","不是迷乡客，尋奇处处留。"]', '诗', 'shi', '', NULL, '和尹懋秋夜遊㴩湖 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5181d49-2b38-40ca-8f28-2a1b3c02810d', '與趙冬曦尹懋子均登南樓', '與趙冬曦尹懋子均登南楼', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["危樓瀉洞湖，積水照城隅。","命駕邀漁火，通家引鳳雛。","山晴紅蘂匝，洲曉綠苗鋪。","舉目思鄉縣，春光定不殊。"]', '["危楼瀉洞湖，積水照城隅。","命駕邀漁火，通家引鳳雛。","山晴紅蘂匝，洲晓綠苗鋪。","舉目思乡縣，春光定不殊。"]', '诗', 'shi', '', NULL, '與趙冬曦尹懋子均登南樓 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('367e8d94-9363-42df-8d87-3d4f2a20898b', '遊㴩湖上寺', '游㴩湖上寺', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["湖上奇峰積，山中芳樹春。","何知絕世境，來遇賞心人。","清舊巖前樂，呦嚶鳥獸馴。","靜言觀聽裏，萬法自成輪。"]', '["湖上奇峰積，山中芳樹春。","何知絕世境，来遇賞心人。","清旧巖前乐，呦嚶鸟獸馴。","静言观听裏，万法自成輪。"]', '诗', 'shi', '', NULL, '遊㴩湖上寺 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d490872-2d79-4a7e-98c2-c444c94cb7cf', '晦日', '晦日', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["晦日嫌春淺，江浦看湔衣。","道傍花欲合，枝上鳥猶稀。","共憶浮橋晚，無人不醉歸。","寄書題此日，雁過洛陽飛。"]', '["晦日嫌春淺，江浦看湔衣。","道傍花欲合，枝上鸟猶稀。","共憶浮橋晚，無人不醉归。","寄书題此日，雁過洛陽飞。"]', '诗', 'shi', '', NULL, '晦日 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae708f30-8b96-4973-9d9c-f674eb603572', '湘州九日城北亭子', '湘州九日城北亭子', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西楚茱萸節，南淮戲馬臺。","寧知沅水上，復有菊花杯。","亭帳憑高出，親朋自遠來。","短歌將急景，同使興情催。"]', '["西楚茱萸節，南淮戲马台。","寧知沅水上，复有菊花杯。","亭帳憑高出，親朋自远来。","短歌將急景，同使兴情催。"]', '诗', 'shi', '', NULL, '湘州九日城北亭子 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44d2e0d8-114b-4364-9c08-6372c05deb75', '翻著葛巾呈趙尹', '翻著葛巾呈趙尹', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["昔日接㒿倒，今我葛巾翻。","宿酒何時醒，形骸不復存。","忽聞有嘉客，躧步出閑門。","桃花春徑滿，誤識武陵源。"]', '["昔日接㒿倒，今我葛巾翻。","宿酒何时醒，形骸不复存。","忽闻有嘉客，躧步出闲门。","桃花春徑满，誤識武陵源。"]', '诗', 'shi', '', NULL, '翻著葛巾呈趙尹 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6aed324-262c-4917-a86c-d9defc45ad3e', '戲題草樹', '戲題草樹', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["忽驚石榴樹，遠出渡江來。","戲問芭蕉葉，何愁心不開。","微霜拂宮桂，淒吹掃庭槐。","榮盛更如此，慙君獨見哀。"]', '["忽驚石榴樹，远出渡江来。","戲问芭蕉葉，何愁心不开。","微霜拂宮桂，淒吹掃庭槐。","榮盛更如此，慙君独见哀。"]', '诗', 'shi', '', NULL, '戲題草樹 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56354da7-a86d-4fff-b5e6-68ee489e3ae6', '岳州贈廣平公宋大夫', '岳州贈廣平公宋大夫', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["亞相本時英，歸來復國楨。","朝推長孺直，野慕隱之清。","傳節還閩嶂，皇華入漢京。","寧思江上老，歲[晏]獨無成。"]', '["亞相本时英，归来复国楨。","朝推长孺直，野慕隐之清。","傳節還閩嶂，皇华入漢京。","寧思江上老，歲[晏]独無成。"]', '诗', 'shi', '', NULL, '岳州贈廣平公宋大夫 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('380f90d8-c49d-4796-b4eb-9325ec1ae51a', '和魏僕射還鄉', '和魏僕射還乡', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["富貴還鄉國，光華滿舊林。","秋風樹不靜，君子歎何深。","故老空懸劒，鄰交日散金。","衆芳搖落盡，獨有歲寒心。"]', '["富貴還乡国，光华满旧林。","秋风樹不静，君子歎何深。","故老空懸劒，鄰交日散金。","衆芳搖落尽，独有歲寒心。"]', '诗', 'shi', '', NULL, '和魏僕射還鄉 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02fc6b63-398c-4824-b91d-88e95d3900cb', '和張監觀赦', '和張監观赦', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["日御臨雙闕，天街儼百神。","雷茲作解氣，歲復建寅春。","喜候開星驛，歡聲發市人。","金環能作賦，來入管弦聲。"]', '["日御臨雙闕，天街儼百神。","雷茲作解氣，歲复建寅春。","喜候开星驛，歡声發市人。","金环能作賦，来入管弦声。"]', '诗', 'shi', '', NULL, '和張監觀赦 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9a37b3-d2f3-4cab-82ec-42cbdf9009d2', '寄天台司馬道士', '寄天台司马道士', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["世上求真客，天台去不還。","傳聞有仙要，夢寐在茲山。","朱闕青霞斷，瑤堂紫月閑。","何時枉飛鶴，笙吹接人間。"]', '["世上求真客，天台去不還。","傳闻有仙要，梦寐在茲山。","朱闕青霞斷，瑤堂紫月闲。","何时枉飞鹤，笙吹接人间。"]', '诗', 'shi', '', NULL, '寄天台司馬道士 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9887e7-a451-4c8a-958f-e6fb492b059d', '下江南向夔州', '下江南向夔州', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天明江霧歇，洲浦棹歌來。","綠水逶迤去，青山相向開。","城臨蜀帝祀，雲接楚王臺。","舊知巫山上，遊子共徘徊。"]', '["天明江霧歇，洲浦棹歌来。","綠水逶迤去，青山相向开。","城臨蜀帝祀，云接楚王台。","旧知巫山上，游子共徘徊。"]', '诗', 'shi', '', NULL, '下江南向夔州 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2ee474-431f-4932-b0a0-8d2eca3e3c5b', '還至端州驛前與高六別處', '還至端州驛前與高六別处', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["舊館分江日，悽然望落暉。","相逢傳旅食，臨別換征衣。","昔記山川是，今傷人代非。","往來皆此路，生死不同歸。"]', '["旧館分江日，悽然望落暉。","相逢傳旅食，臨別換征衣。","昔記山川是，今傷人代非。","往来皆此路，生死不同归。"]', '诗', 'shi', '', NULL, '還至端州驛前與高六別處 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633b6184-f88c-45d4-9d7a-0a73a584c4f2', '四月一日過江赴荆州', '四月一日過江赴荆州', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["春色沅湘盡，三年客始回。","夏雲隨北帆，同日過江來。","水漫荆門出，山平郢路開。","比肩羊叔子，千載豈無才。"]', '["春色沅湘尽，三年客始回。","夏云隨北帆，同日過江来。","水漫荆门出，山平郢路开。","比肩羊叔子，千載豈無才。"]', '诗', 'shi', '', NULL, '四月一日過江赴荆州 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1758b317-c423-47ff-9925-1aca2c0018a9', '湘州北亭', '湘州北亭', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["人務南亭少，風煙北院多。","山花迷徑路，池水拂藤蘿。","萍散魚時躍，林幽鳥任歌。","悠然白雲意，乘興抱琴過。"]', '["人務南亭少，风煙北院多。","山花迷徑路，池水拂藤蘿。","萍散鱼时躍，林幽鸟任歌。","悠然白云意，乘兴抱琴過。"]', '诗', 'shi', '', NULL, '湘州北亭 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('831d51fb-3169-467e-b8f8-5010bf9d0aa6', '荆州亭入朝', '荆州亭入朝', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["巫山雲雨峽，湘水洞庭波。","九辨人猶擯，三秋鴈始過。","旃裘吳地盡，髫薦楚言多。","不果朝宗願，其如江漢何。"]', '["巫山云雨峽，湘水洞庭波。","九辨人猶擯，三秋鴈始過。","旃裘吳地尽，髫薦楚言多。","不果朝宗願，其如江漢何。"]', '诗', 'shi', '', NULL, '荆州亭入朝 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d7b7e6-9fc1-489b-9c46-a72cb9868fdb', '岳州守歲', '岳州守歲', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["除夜清樽滿，寒庭燎火多。","舞衣連臂拂，醉坐合聲歌。","至樂都忘我，冥心自委和。","今年只如此，來歲知如何。"]', '["除夜清樽满，寒庭燎火多。","舞衣連臂拂，醉坐合声歌。","至乐都忘我，冥心自委和。","今年只如此，来歲知如何。"]', '诗', 'shi', '', NULL, '岳州守歲 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a46b89-ddd7-4e66-8ad4-acf1e2bca7d4', '詠塵', '詠塵', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["仙浦生羅襪，神京染素衣。","裨山期益峻，照日幸增輝。","夕伴龍媒合，朝遊鳳輦歸。","獨憐范甑下，思繞畫梁飛。"]', '["仙浦生羅襪，神京染素衣。","裨山期益峻，照日幸增輝。","夕伴龙媒合，朝游鳳輦归。","独怜范甑下，思繞畫梁飞。"]', '诗', 'shi', '', NULL, '詠塵 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716debdd-daf8-4993-9547-7b88ff246619', '闕題', '闕題', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["婚禮知無賀，承家歎有輝。","親迎驥子躍，吉兆鳳雛飛。","溫席開華扇，梁門換褧衣。","遙思桃李日，應賦採蘋歸。"]', '["婚禮知無賀，承家歎有輝。","親迎驥子躍，吉兆鳳雛飞。","溫席开华扇，梁门換褧衣。","遙思桃李日，應賦採蘋归。"]', '诗', 'shi', '', NULL, '闕題 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd610ff-0140-4d56-978f-2b14de7f1ce6', '深渡驛', '深渡驛', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["旅泊青山夜，荒庭白露秋。","洞房懸月影，高枕聽江流。","猿響寒巖樹，螢飛古驛樓。","他鄉對搖落，倂覺起離憂。"]', '["旅泊青山夜，荒庭白露秋。","洞房懸月影，高枕听江流。","猿响寒巖樹，螢飞古驛楼。","他乡对搖落，倂覺起離憂。"]', '诗', 'shi', '', NULL, '深渡驛 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f30037f0-0219-46eb-a376-2143c22cf226', '惠文太子挽歌二首 一', '惠文太子挽歌二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["碣館英靈在，瑤山美諡尊。","剪桐悲曩戲，攻玉愴新恩。","宮仗傳馳道，朝衣送國門。","千秋穀門外，明月照西園。"]', '["碣館英靈在，瑤山美諡尊。","剪桐悲曩戲，攻玉愴新恩。","宮仗傳驰道，朝衣送国门。","千秋穀门外，明月照西园。"]', '诗', 'shi', '', NULL, '惠文太子挽歌二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85f2427-bdca-4033-8bbf-b4cf2debc7b4', '惠文太子挽歌二首 二', '惠文太子挽歌二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["梁國深文雅，淮王愛道仙。","帝歡同宴日，神奪上賓年。","旒旐飛行樹，帷宮宿野煙。","指言君愛弟，揮淚滿山川。"]', '["梁国深文雅，淮王愛道仙。","帝歡同宴日，神奪上賓年。","旒旐飞行樹，帷宮宿野煙。","指言君愛弟，揮泪满山川。"]', '诗', 'shi', '', NULL, '惠文太子挽歌二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e401c1-6bb0-42fb-accc-789d8445dd89', '節義太子楊妃挽歌二首 一', '節義太子楊妃挽歌二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西華三公族，東闈五可才。","玉環初受慶，金玦反逢灾。","桂殿花空落，桐園月自開。","朝雲將暮雨，長繞望思臺。"]', '["西华三公族，东闈五可才。","玉环初受慶，金玦反逢灾。","桂殿花空落，桐园月自开。","朝云將暮雨，长繞望思台。"]', '诗', 'shi', '', NULL, '節義太子楊妃挽歌二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4a4baf-acda-4286-9b8e-3442a2208daf', '節義太子楊妃挽歌二首 二', '節義太子楊妃挽歌二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["昔日三朝路，逶迤四望車。","繡腰長命綺，隱髻連枝花。","今春戾園樹，索然無歲華。","共傷千載後，惟號一王家。"]', '["昔日三朝路，逶迤四望车。","繡腰长命綺，隐髻連枝花。","今春戾园樹，索然無歲华。","共傷千載後，惟號一王家。"]', '诗', 'shi', '', NULL, '節義太子楊妃挽歌二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe43f0a-2fae-408e-ba7f-a28867154a48', '韋譙公挽歌二首 一', '韋譙公挽歌二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["五瑞分王國，雙珠映后家。","文飛書上鳳，武結笥中蛇。","出豫榮前馬，迴鸞喪後車。","衮衣將錫命，泉路有光華。"]', '["五瑞分王国，雙珠映后家。","文飞书上鳳，武結笥中蛇。","出豫榮前马，迴鸾喪後车。","衮衣將錫命，泉路有光华。"]', '诗', 'shi', '', NULL, '韋譙公挽歌二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f02e3d7-6f8b-449b-b638-6ca1ebdb645a', '韋譙公挽歌二首 二', '韋譙公挽歌二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["國騁雙騏驥，庭儀兩鳳皇。","將星連相位，玉樹伴金鄉。","歌舞侯家豔，軒裘戚里光。","安知杜陵下，碑版已相望。"]', '["国騁雙騏驥，庭儀兩鳳皇。","將星連相位，玉樹伴金乡。","歌舞侯家豔，軒裘戚里光。","安知杜陵下，碑版已相望。"]', '诗', 'shi', '', NULL, '韋譙公挽歌二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f360d9-fbcf-4ef8-b887-44f20f394df6', '右丞相蘇公挽歌二首 一', '右丞相蘇公挽歌二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["王宰丹青化，春卿禮樂才。","緇衣傳舊職，華衮贈新哀。","路泣羣官送，山嘶駟馬廻。","佳辰無白日，賓閣有青苔。"]', '["王宰丹青化，春卿禮乐才。","緇衣傳旧職，华衮贈新哀。","路泣羣官送，山嘶駟马廻。","佳辰無白日，賓閣有青苔。"]', '诗', 'shi', '', NULL, '右丞相蘇公挽歌二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a9936c-251a-4570-869c-d27d9ccde5d5', '右丞相蘇公挽歌二首 二', '右丞相蘇公挽歌二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["門歌出野田，冠帶寢窮泉。","萬事皆身外，平生尚目前。","西垣紫泥綍，東岳白雲篇。","自惜同聲處，從今遂絕弦。"]', '["门歌出野田，冠带寢窮泉。","万事皆身外，平生尚目前。","西垣紫泥綍，东岳白云篇。","自惜同声处，從今遂絕弦。"]', '诗', 'shi', '', NULL, '右丞相蘇公挽歌二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2985672d-34c2-4224-9006-61772e1f5b7d', '崔尚書挽詞', '崔尚书挽词', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["相宅隆坤寶，承家占海封。","庭中男執雁，門外女乘龍。","鳴玉遊三省，摐金侍九重。","一朝賓客散，留劒在青松。"]', '["相宅隆坤寶，承家占海封。","庭中男執雁，门外女乘龙。","鳴玉游三省，摐金侍九重。","一朝賓客散，留劒在青松。"]', '诗', 'shi', '', NULL, '崔尚書挽詞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d4ffa6b-ecd0-4c9a-82c0-464dae572bfa', '右侍郎集賢院學士徐公挽詞二首 一', '右侍郎集賢院学士徐公挽词二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["才美臨淄北，名高淮海東。","羽儀三省遍，漁獵五車通。","玉殿孤新榜，珠英落舊叢。"]', '["才美臨淄北，名高淮海东。","羽儀三省遍，漁獵五车通。","玉殿孤新榜，珠英落旧叢。"]', '诗', 'shi', '', NULL, '右侍郎集賢院學士徐公挽詞二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('289a1980-a537-48ab-bd28-8f16368277bc', '右侍郎集賢院學士徐公挽詞二首 二', '右侍郎集賢院学士徐公挽词二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["歎息書林友，才華天下選。","並賦三陽宮，集詩集賢殿。","具物衣如在，咄嗟長不見。","既哀薤露詞，豈忘平生眷。"]', '["歎息书林友，才华天下選。","並賦三陽宮，集诗集賢殿。","具物衣如在，咄嗟长不见。","既哀薤露词，豈忘平生眷。"]', '诗', 'shi', '', NULL, '右侍郎集賢院學士徐公挽詞二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4f7b09-d23a-46b6-90f9-c6c1dd2ceb48', '崔司業挽歌二首 一', '崔司業挽歌二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["海岱英靈氣，膠庠禮樂資。","風流滿天下，人物擅京師。","疾起揚雄賦，魂遊謝客詩。","從今好文主，遺恨不同時。"]', '["海岱英靈氣，膠庠禮乐資。","风流满天下，人物擅京師。","疾起揚雄賦，魂游謝客诗。","從今好文主，遺恨不同时。"]', '诗', 'shi', '', NULL, '崔司業挽歌二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71b62c64-fd71-4f74-af58-7fdc4bd8a035', '崔司業挽歌二首 二', '崔司業挽歌二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["象設存華館，威儀下墓田。","鳳池傷舊草，麟史泣遺編。","帷蓋墟煙沒，干旌隴日懸。","古來埋玉樹，流恨滿山川。"]', '["象設存华館，威儀下墓田。","鳳池傷旧草，麟史泣遺編。","帷蓋墟煙沒，干旌隴日懸。","古来埋玉樹，流恨满山川。"]', '诗', 'shi', '', NULL, '崔司業挽歌二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3804fdf5-85f5-447b-8637-abb3630009f2', '李工部挽歌三首 一', '李工部挽歌三首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["錦帳爲郎日，金門待詔時。","楊宮先上賦，柏殿幾連詩。","瞬息琴歌斷，淒涼簫挽悲。","那堪霸陵岸，回首望京師。"]', '["錦帳爲郎日，金门待詔时。","楊宮先上賦，柏殿幾連诗。","瞬息琴歌斷，淒涼簫挽悲。","那堪霸陵岸，回首望京師。"]', '诗', 'shi', '', NULL, '李工部挽歌三首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4061d4-62c7-4d83-a110-62c949eb5be6', '李工部挽歌三首 二', '李工部挽歌三首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["宅兆西陵上，平生雅志從。","城臨丹闕近，山望白雲重。","會葬知元伯，看碑識蔡邕。","無由接神理，揮涕向青松。"]', '["宅兆西陵上，平生雅志從。","城臨丹闕近，山望白云重。","會葬知元伯，看碑識蔡邕。","無由接神理，揮涕向青松。"]', '诗', 'shi', '', NULL, '李工部挽歌三首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fce41df-6ee8-4dae-b8e6-846a6a7651a1', '李工部挽歌三首 三', '李工部挽歌三首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["常時好賓客，永日對弦歌。","是日歸泉下，傷心無奈何。","墓庭人已散，祭處鳥來過。","碑石生苔蘚，榮名豈復多。"]', '["常时好賓客，永日对弦歌。","是日归泉下，傷心無奈何。","墓庭人已散，祭处鸟来過。","碑石生苔蘚，榮名豈复多。"]', '诗', 'shi', '', NULL, '李工部挽歌三首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0a82f01-5e36-40d9-a73c-da9112eaffe3', '贈工部尚書馮公挽歌三首 一', '贈工部尚书馮公挽歌三首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["忠鯁難爲事，平生盡畏途。","如弦心自直，秀木勢恆孤。","詔葬南陵道，神遊北斗樞。","貴門傳萬石，餘慶在雙珠。"]', '["忠鯁难爲事，平生尽畏途。","如弦心自直，秀木勢恆孤。","詔葬南陵道，神游北斗樞。","貴门傳万石，餘慶在雙珠。"]', '诗', 'shi', '', NULL, '贈工部尚書馮公挽歌三首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac6a73d5-8d2a-47a2-8c79-99359b13ce5b', '贈工部尚書馮公挽歌三首 二', '贈工部尚书馮公挽歌三首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["爵位題龍旐，威儀出鳳城。","路傍人泣送，門外馬嘶迎。","萬事非吾有，千悲是世情。","昔焉稱夏日，今也謚冬卿。"]', '["爵位題龙旐，威儀出鳳城。","路傍人泣送，门外马嘶迎。","万事非吾有，千悲是世情。","昔焉稱夏日，今也謚冬卿。"]', '诗', 'shi', '', NULL, '贈工部尚書馮公挽歌三首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('436eb066-ab58-4779-bb03-7919b4f66201', '贈工部尚書馮公挽歌三首 三', '贈工部尚书馮公挽歌三首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["窅然長夜臺，舉世可哀哉。","泉戶一朝閉，松風四面來。","石碑填駮蘚，珠服聚塵埃。","誰言遼東鶴，千年往復廻。"]', '["窅然长夜台，舉世可哀哉。","泉戶一朝閉，松风四面来。","石碑填駮蘚，珠服聚塵埃。","誰言遼东鹤，千年往复廻。"]', '诗', 'shi', '', NULL, '贈工部尚書馮公挽歌三首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39148525-f5ba-45a7-a457-f2a67bbd5ffe', '徐高御挽歌', '徐高御挽歌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["蒲密遙千載，鳴琴始一追。","公卿傳世範，仁義續靈基。","不待南遊祿，何先北帝期。","玉棺從此閉，金鼎代相欺。"]', '["蒲密遙千載，鳴琴始一追。","公卿傳世範，仁義續靈基。","不待南游祿，何先北帝期。","玉棺從此閉，金鼎代相欺。"]', '诗', 'shi', '', NULL, '徐高御挽歌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be118625-70d0-41ac-a76d-b4811a9208cb', '奉和聖製春日幸望春宮應制', '奉和聖製春日幸望春宮應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["別館芳菲上苑東，飛花澹蕩御筵紅。","城臨渭水天河靜，闕對南山雨露通。","繞殿流鶯凡幾樹，當蹊亂蝶許多叢。","春園既醉心和樂，共識皇恩造化同。"]', '["別館芳菲上苑东，飞花澹蕩御筵紅。","城臨渭水天河静，闕对南山雨露通。","繞殿流鶯凡幾樹，當蹊亂蝶許多叢。","春园既醉心和乐，共識皇恩造化同。"]', '诗', 'shi', '', NULL, '奉和聖製春日幸望春宮應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5dee431-e8d1-49ce-ba8f-5ce10b4af5e7', '侍宴隆慶池應制', '侍宴隆慶池應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["靈池月滿直城隈，黻帳天臨御路開。","東沼初陽疑吐出，南山曉翠若浮來。","魚龍百戲紛容與，鳧鷁雙舟較泝洄。","願似金隄青草馥，長承瑤水白雲杯。"]', '["靈池月满直城隈，黻帳天臨御路开。","东沼初陽疑吐出，南山晓翠若浮来。","鱼龙百戲紛容與，鳧鷁雙舟較泝洄。","願似金隄青草馥，长承瑤水白云杯。"]', '诗', 'shi', '', NULL, '侍宴隆慶池應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf840dc-3998-4f70-aecc-033e36f0f619', '奉和聖製春日出苑應制', '奉和聖製春日出苑應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["禁林豔裔發青陽，春望逍遙出畫堂。","雨洗亭臯千畝綠，風吹梅李一園香。","鶴飛不去隨青管，魚躍翻來入綵航。","睿賞歡承天保定，遒文更覩日重光。"]', '["禁林豔裔發青陽，春望逍遙出畫堂。","雨洗亭臯千畝綠，风吹梅李一园香。","鹤飞不去隨青管，鱼躍翻来入綵航。","睿賞歡承天保定，遒文更覩日重光。"]', '诗', 'shi', '', NULL, '奉和聖製春日出苑應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc7d36b-792f-44e1-9e97-cad3f39947b7', '扈從溫泉宮獻詩', '扈從溫泉宮獻诗', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["溫泉啓蟄氣氛氳，渭浦歸鴻日數羣。","騎仗聯聯環北極，鳴笳步步引南熏。","松間彩殿籠佳氣，山上朱旗繞瑞雲。","不知遠夢華胥國，何如親奉帝堯君。"]', '["溫泉啓蟄氣氛氳，渭浦归鴻日數羣。","騎仗聯聯环北極，鳴笳步步引南熏。","松间彩殿籠佳氣，山上朱旗繞瑞云。","不知远梦华胥国，何如親奉帝堯君。"]', '诗', 'shi', '', NULL, '扈從溫泉宮獻詩 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7986eede-077b-4351-8589-a8ceb6b7104e', '三月三日詔宴定昆池宮莊賦得筵字', '三月三日詔宴定昆池宮莊賦得筵字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["鳳皇樓下對天泉，鸚鵡洲中匝管弦。","舊識平陽佳麗地，今逢上巳盛明年。","舟將水動千尋日，幕共林橫兩岸煙。","不降玉人觀禊飲，誰令醉舞拂賓筵。"]', '["鳳皇楼下对天泉，鸚鵡洲中匝管弦。","旧識平陽佳丽地，今逢上巳盛明年。","舟將水动千尋日，幕共林橫兩岸煙。","不降玉人观禊饮，誰令醉舞拂賓筵。"]', '诗', 'shi', '', NULL, '三月三日詔宴定昆池宮莊賦得筵字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b8aca24-fba7-4b5b-8f05-97a9f0e4eb0f', '先天應令', '先天應令', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["三陽麗景早芳辰，四序嘉園物候新。","梅花百般障行路，垂柳千條暗迴津。","鳥驚直爲飛風葉，魚躍都由怯岸人。","唯願聖主南山壽，何愁不賞萬年春。"]', '["三陽丽景早芳辰，四序嘉园物候新。","梅花百般障行路，垂柳千條暗迴津。","鸟驚直爲飞风葉，鱼躍都由怯岸人。","唯願聖主南山壽，何愁不賞万年春。"]', '诗', 'shi', '', NULL, '先天應令 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f1b1a1-703e-42fa-9754-35a1c8f2fb7b', '舞馬千秋萬歲樂府詞三首 一', '舞马千秋万歲乐府词三首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["金天誕聖千秋節，玉醴還分萬壽觴。","試聽紫騮歌樂府，何如騄驥舞華岡。","連鶱勢出魚龍變，躞蹀驕生鳥獸行。","歲歲相傳指樹日，翩翩來伴慶雲翔。"]', '["金天誕聖千秋節，玉醴還分万壽觴。","試听紫騮歌乐府，何如騄驥舞华岡。","連鶱勢出鱼龙变，躞蹀驕生鸟獸行。","歲歲相傳指樹日，翩翩来伴慶云翔。"]', '诗', 'shi', '', NULL, '舞馬千秋萬歲樂府詞三首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546c301e-b8a4-4333-9b5e-20bc82180d86', '舞馬千秋萬歲樂府詞三首 二', '舞马千秋万歲乐府词三首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖皇至德與天齊，天馬來儀自海西。","腕足徐行拜兩膝，繁驕不進踏千蹄。","髬髵奮鬣時蹲踏，鼓怒驤身忽上躋。","更有銜杯終宴曲，垂頭掉尾醉如泥。"]', '["聖皇至德與天齊，天马来儀自海西。","腕足徐行拜兩膝，繁驕不進踏千蹄。","髬髵奮鬣时蹲踏，鼓怒驤身忽上躋。","更有銜杯終宴曲，垂头掉尾醉如泥。"]', '诗', 'shi', '', NULL, '舞馬千秋萬歲樂府詞三首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('904f6a28-a66b-4a94-850a-1d9f03f65ab1', '舞馬千秋萬歲樂府詞三首 三', '舞马千秋万歲乐府词三首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["遠聽明君愛逸才，玉鞭金翅引龍媒。","不因茲白人間有，定是飛黃天上來。","影弄日華相照耀，噴含雲色且裴徊。","莫言闕下桃花舞，別有河中蘭葉開。"]', '["远听明君愛逸才，玉鞭金翅引龙媒。","不因茲白人间有，定是飞黄天上来。","影弄日华相照耀，噴含云色且裴徊。","莫言闕下桃花舞，別有河中蘭葉开。"]', '诗', 'shi', '', NULL, '舞馬千秋萬歲樂府詞三首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('796b97c1-a1bf-4fb7-bd0e-b48141358668', '同趙侍御巴陵早春作', '同趙侍御巴陵早春作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["江上春來早可觀，巧將春物妬餘寒。","水苔共繞留烏石，花鳥爭開鬬鴨欄。","佩勝芳辰日漸暖，然燈美夜月初圓。","意隨北雁雲飛去，直待南州蕙草殘。"]', '["江上春来早可观，巧將春物妬餘寒。","水苔共繞留烏石，花鸟爭开鬬鴨欄。","佩勝芳辰日漸暖，然灯美夜月初圓。","意隨北雁云飞去，直待南州蕙草殘。"]', '诗', 'shi', '', NULL, '同趙侍御巴陵早春作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf457d67-27e9-41b1-9fb0-27cf241502c6', '㴩湖山寺', '㴩湖山寺', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["空山寂歷道心生，虛谷迢遙野鳥聲。","禪室從來塵外賞，香臺豈是世中情。","雲間東嶺千尋出，樹裏南湖一片明。","若使巢由知此意，不將蘿薜易簪纓。"]', '["空山寂歷道心生，虛谷迢遙野鸟声。","禪室從来塵外賞，香台豈是世中情。","云间东嶺千尋出，樹裏南湖一片明。","若使巢由知此意，不將蘿薜易簪纓。"]', '诗', 'shi', '', NULL, '㴩湖山寺 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406985ef-4d98-470b-8ff4-93a9335892ca', '幽州新歲作', '幽州新歲作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["去歲荆南梅似雪，今年薊北雪如梅。","共知人事何常定，且喜年華去復來。","邊鎮戍歌連夜動，京城燎火徹明開。","遙遙西向長安日，願上南山壽一杯。"]', '["去歲荆南梅似雪，今年薊北雪如梅。","共知人事何常定，且喜年华去复来。","邊鎮戍歌連夜动，京城燎火徹明开。","遙遙西向长安日，願上南山壽一杯。"]', '诗', 'shi', '', NULL, '幽州新歲作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f05767-bc92-4dfb-8abb-59c60be53882', '扈從幸韋嗣立山莊應制', '扈從幸韋嗣立山莊應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寒灰飛玉琯，湯井駐金輿。","既得方明相，還尋大隗居。","懸泉珠貫下，列帳錦屏舒。","騎遠林逾密，笳繁谷自虛。","門旗塹複磴，殿幕裹通渠。","舞鳳迎公主，雕龍賦婕妤。","地幽天賞洽，酒樂御筵初。","菲才叨侍從，連藻媿應徐。"]', '["寒灰飞玉琯，湯井駐金輿。","既得方明相，還尋大隗居。","懸泉珠貫下，列帳錦屏舒。","騎远林逾密，笳繁谷自虛。","门旗塹複磴，殿幕裹通渠。","舞鳳迎公主，雕龙賦婕妤。","地幽天賞洽，酒乐御筵初。","菲才叨侍從，連藻媿應徐。"]', '诗', 'shi', '', NULL, '扈從幸韋嗣立山莊應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5550ac21-e186-4317-ae8f-7bd85c4a2ccc', '奉和聖製喜雪應制', '奉和聖製喜雪應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖德與天同，封巒欲報功。","詔書期日下，靈感應時通。","觸石雲呈瑞，含花雪告豐。","積如沙照月，散似麵從風。","舞集仙臺上，歌流帝樂中。","遙知百神喜，灑路待行宮。"]', '["聖德與天同，封巒欲報功。","詔书期日下，靈感應时通。","觸石云呈瑞，含花雪告豐。","積如沙照月，散似麵從风。","舞集仙台上，歌流帝乐中。","遙知百神喜，灑路待行宮。"]', '诗', 'shi', '', NULL, '奉和聖製喜雪應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3156c1e6-f199-45fb-b87b-37cfefaf84e1', '奉和聖製寒食作應制', '奉和聖製寒食作應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寒食春過半，花穠鳥復嬌。","從來禁火日，會接清明朝。","鬬敵雞殊勝，爭毬馬絕調。","晴空數雲點，香樹百風搖。","改木迎新燧，封田表舊燒。","皇情愛嘉節，傳曲與簫韶。"]', '["寒食春過半，花穠鸟复嬌。","從来禁火日，會接清明朝。","鬬敵雞殊勝，爭毬马絕調。","晴空數云点，香樹百风搖。","改木迎新燧，封田表旧燒。","皇情愛嘉節，傳曲與簫韶。"]', '诗', 'shi', '', NULL, '奉和聖製寒食作應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6f5d77-cfd5-420f-a6fa-1d0a5cc4fa1b', '奉和聖製賜崔日知往潞州應制', '奉和聖製賜崔日知往潞州應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖情留曩鎮，佳氣翊興王。","增戟雄都府，高車轉太常。","川橫八練闊，山帶五龍長。","連帥初恩命，天人舊紀綱。","餞塗飛御藻，闔境自生光。","明主徵循吏，何年下鳳皇。"]', '["聖情留曩鎮，佳氣翊兴王。","增戟雄都府，高车轉太常。","川橫八練闊，山带五龙长。","連帥初恩命，天人旧紀綱。","餞塗飞御藻，闔境自生光。","明主徵循吏，何年下鳳皇。"]', '诗', 'shi', '', NULL, '奉和聖製賜崔日知往潞州應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0408bd50-a69b-4161-b507-70bc87699e38', '春晚侍宴麗正殿探得開字', '春晚侍宴丽正殿探得开字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖政惟稽古，賓門引上才。","坊因購書立，殿爲集賢開。","髦彥星辰下，仙章日月回。","字如龍負出，韻是鳳銜來。","庭柳餘春駐，宮鶯早夏催。","喜承芸閣宴，幸奉柏梁杯。"]', '["聖政惟稽古，賓门引上才。","坊因購书立，殿爲集賢开。","髦彥星辰下，仙章日月回。","字如龙負出，韻是鳳銜来。","庭柳餘春駐，宮鶯早夏催。","喜承芸閣宴，幸奉柏梁杯。"]', '诗', 'shi', '', NULL, '春晚侍宴麗正殿探得開字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5441029e-e14b-4109-9ec1-8245c15d8b0f', '奉和聖製花蕚樓下宴應制', '奉和聖製花蕚楼下宴應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["萬心翹樂宴，三舍緩昌時。","山接夏雲險，臺留春日遲。","節移芳未歇，興隔賞仍追。","醉後傳嘉惠，樓前舞聖慈。","皇恩與時合，天意若人期。","故發前旬雨，新垂湛露詩。"]', '["万心翹乐宴，三舍緩昌时。","山接夏云險，台留春日遲。","節移芳未歇，兴隔賞仍追。","醉後傳嘉惠，楼前舞聖慈。","皇恩與时合，天意若人期。","故發前旬雨，新垂湛露诗。"]', '诗', 'shi', '', NULL, '奉和聖製花蕚樓下宴應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4929ef3-9b06-4638-a965-b76109edd2f6', '奉和聖製度蒲關應制', '奉和聖製度蒲关應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["蒲坂橫臨晉，華芝曉望秦。","關城雄地險，橋路扼天津。","樓映行宮日，隄含宮樹春。","黃雲隨寶鼎，紫氣逐真人。","東詠唐虞跡，西觀周漢塵。","山河非國寶，明主愛忠臣。"]', '["蒲坂橫臨晉，华芝晓望秦。","关城雄地險，橋路扼天津。","楼映行宮日，隄含宮樹春。","黄云隨寶鼎，紫氣逐真人。","东詠唐虞跡，西观周漢塵。","山河非国寶，明主愛忠臣。"]', '诗', 'shi', '', NULL, '奉和聖製度蒲關應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21cc6cd3-4c8a-4aa1-bd43-4e827ab52e42', '奉和聖製途經華嶽應制', '奉和聖製途經华嶽應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西嶽鎮皇京，中峰入太清。","玉鑾重嶺應，緹[騎]薄雲迎。","霽日懸高掌，寒空類削成。","軒遊會神處，漢幸望仙情。","舊廟青林古，新碑綠字生。","羣臣願封岱，還駕勒鴻名。"]', '["西嶽鎮皇京，中峰入太清。","玉鑾重嶺應，緹[騎]薄云迎。","霽日懸高掌，寒空類削成。","軒游會神处，漢幸望仙情。","旧廟青林古，新碑綠字生。","羣臣願封岱，還駕勒鴻名。"]', '诗', 'shi', '', NULL, '奉和聖製途經華嶽應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac5c501-71e2-4249-90b3-3f1923527877', '奉和聖製過王濬墓應制', '奉和聖製過王濬墓應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["牛斗三分國，龍驤一統年。","智高寧受制，風急肯廻船。","有策擒吳嚭，無言讓范宣。","援孤因勢屈，功重爲讒偏。","舊迹灰塵散，枯墳故老傳。","百代逢明主，何辭死道邊。"]', '["牛斗三分国，龙驤一統年。","智高寧受制，风急肯廻船。","有策擒吳嚭，無言讓范宣。","援孤因勢屈，功重爲讒偏。","旧迹灰塵散，枯墳故老傳。","百代逢明主，何辞死道邊。"]', '诗', 'shi', '', NULL, '奉和聖製過王濬墓應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34afa291-66ce-4c8f-8ad6-94e64adb721c', '奉和聖製經河上公廟應制', '奉和聖製經河上公廟應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["河上無名老，知非漢代人。","先探道德要，留待聖明辰。","玄妙爲天下，清虛用谷神。","化將和氣一，風與太初鄰。","靈廟觀遺像，仙歌入至真。","皇心齊萬物，何處不同塵。"]', '["河上無名老，知非漢代人。","先探道德要，留待聖明辰。","玄妙爲天下，清虛用谷神。","化將和氣一，风與太初鄰。","靈廟观遺像，仙歌入至真。","皇心齊万物，何处不同塵。"]', '诗', 'shi', '', NULL, '奉和聖製經河上公廟應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a0fe809-af8c-48c6-b28d-fd5613e48125', '奉和聖製幸鳳湯泉應制', '奉和聖製幸鳳湯泉應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["周狩聞岐禮，秦都辨雍名。","獻禽天子孝，存老聖皇情。","溫潤宜冬幸，遊畋樂歲成。","湯雲出水殿，暖氣入山營。","坎意無私潔，乾心稱物平。","帝歌流樂府，溪谷也增榮。"]', '["周狩闻岐禮，秦都辨雍名。","獻禽天子孝，存老聖皇情。","溫潤宜冬幸，游畋乐歲成。","湯云出水殿，暖氣入山營。","坎意無私潔，乾心稱物平。","帝歌流乐府，溪谷也增榮。"]', '诗', 'shi', '', NULL, '奉和聖製幸鳳湯泉應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab02dc3e-1178-4cc6-b8dd-025035177173', '恩賜樂遊園宴', '恩賜乐游园宴', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["漢苑佳遊地，軒庭近侍臣。","共持榮幸日，來賞豔陽春。","饌玉頒王篚，摐金下帝鈞。","池臺草色徧，宮觀柳條新。","花綬光連榻，朱顏暢飲醇。","聖朝多樂事，天意每隨人。"]', '["漢苑佳游地，軒庭近侍臣。","共持榮幸日，来賞豔陽春。","饌玉頒王篚，摐金下帝鈞。","池台草色徧，宮观柳條新。","花綬光連榻，朱顏暢饮醇。","聖朝多乐事，天意每隨人。"]', '诗', 'shi', '', NULL, '恩賜樂遊園宴 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0456de-cb76-4033-81a3-6a5df94c3dd2', '三月二十日詔宴樂遊園賦得風字', '三月二十日詔宴乐游园賦得风字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["樂遊形勝地，表裏望郊宮。","北闕連天頂，南山對掌中。","皇恩貸芳月，旬宴美成功。","魚戲芙蓉水，鶯啼楊柳風。","春光看欲暮，天澤戀無窮。","長袖招斜日，留光待曲終。"]', '["乐游形勝地，表裏望郊宮。","北闕連天頂，南山对掌中。","皇恩貸芳月，旬宴美成功。","鱼戲芙蓉水，鶯啼楊柳风。","春光看欲暮，天澤戀無窮。","长袖招斜日，留光待曲終。"]', '诗', 'shi', '', NULL, '三月二十日詔宴樂遊園賦得風字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b333cc-6dd5-4809-bd21-81ab59b81716', '赴集賢院學士上賜宴應制得輝字', '赴集賢院学士上賜宴應制得輝字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["侍帝金華講，千齡道固稀。","位將賢士設，書共學徒歸。","首命深燕隗，通經淺漢韋。","列筵榮賜食，送客愧儒衣。","賀燕窺簷下，遷鶯入殿飛。","欲知朝野慶，文教日光輝。"]', '["侍帝金华講，千齡道固稀。","位將賢士設，书共学徒归。","首命深燕隗，通經淺漢韋。","列筵榮賜食，送客愧儒衣。","賀燕窺簷下，遷鶯入殿飞。","欲知朝野慶，文教日光輝。"]', '诗', 'shi', '', NULL, '赴集賢院學士上賜宴應制得輝字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66978161-9cb0-4c2b-8c0b-1f86394c4ce9', '端午三殿侍宴應制探得魚字', '端午三殿侍宴應制探得鱼字', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["小暑夏弦應，徽音商管初。","願齎長命縷，來續大恩餘。","三殿褰珠箔，羣官上玉除。","助陽嘗麥彘，順節進龜魚。","甘露垂天酒，芝花捧御書。","合丹同蝘蜓，灰骨共蟾蜍。","今日傷蛇意，銜珠遂闕如。"]', '["小暑夏弦應，徽音商管初。","願齎长命縷，来續大恩餘。","三殿褰珠箔，羣官上玉除。","助陽嘗麦彘，順節進龟鱼。","甘露垂天酒，芝花捧御书。","合丹同蝘蜓，灰骨共蟾蜍。","今日傷蛇意，銜珠遂闕如。"]', '诗', 'shi', '', NULL, '端午三殿侍宴應制探得魚字 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6872be3d-cd6b-4609-b54a-e481006f6cf6', '奉和聖製春中興慶宮酺宴應制', '奉和聖製春中兴慶宮酺宴應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["千齡逢啓聖，萬域共來威。","慶接郊禋後，酺承農事稀。","御樓橫廣路，天樂下重闈。","鸞鳳調歌曲，虹霓動舞衣。","合聲雲上聚，連步月中歸。","物覩恩無外，神和道入微。","鎬京陪樂飲，柏殿奉文飛。","徒竭秋雲影，何資春日暉。"]', '["千齡逢啓聖，万域共来威。","慶接郊禋後，酺承農事稀。","御楼橫廣路，天乐下重闈。","鸾鳳調歌曲，虹霓动舞衣。","合声云上聚，連步月中归。","物覩恩無外，神和道入微。","鎬京陪乐饮，柏殿奉文飞。","徒竭秋云影，何資春日暉。"]', '诗', 'shi', '', NULL, '奉和聖製春中興慶宮酺宴應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92eb245c-24b2-4d9b-ae54-3482880121f0', '奉和聖製千秋節宴應制', '奉和聖製千秋節宴應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["五德生王者，千齡啓聖人。","赤光來照夜，黃雲上覆晨。","海縣銜恩久，朝章獻舞新。","高居帝座出，夾道衆官陳。","槊杖洗清景，磬管凝秋旻。","珠囊含瑞露，金鏡抱仙輪。","何歲無鄉飲，何田不報神。","薰歌與名節，傳代幸羣臣。"]', '["五德生王者，千齡啓聖人。","赤光来照夜，黄云上覆晨。","海縣銜恩久，朝章獻舞新。","高居帝座出，夾道衆官陳。","槊杖洗清景，磬管凝秋旻。","珠囊含瑞露，金镜抱仙輪。","何歲無乡饮，何田不報神。","薰歌與名節，傳代幸羣臣。"]', '诗', 'shi', '', NULL, '奉和聖製千秋節宴應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0eeec37-c3fc-4537-911b-3cf28df7ebaf', '奉和聖製太行山中言志應制', '奉和聖製太行山中言志應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["六龍鳴玉鑾，九折步雲端。","河絡南浮近，山經北上難。","羽儀映松雪，戈甲帶春寒。","百谷晨笳動，千巖曉仗攢。","皇心感韶節，敷藻念人安。","既立省方館，復建禮神壇。","扈蹕參天老，承榮忝夏官。","長勤百年意，思見一勝殘。"]', '["六龙鳴玉鑾，九折步云端。","河絡南浮近，山經北上难。","羽儀映松雪，戈甲带春寒。","百谷晨笳动，千巖晓仗攢。","皇心感韶節，敷藻念人安。","既立省方館，复建禮神壇。","扈蹕參天老，承榮忝夏官。","长勤百年意，思见一勝殘。"]', '诗', 'shi', '', NULL, '奉和聖製太行山中言志應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a31d196-ce21-429e-8779-20a2b779cffe', '奉和御製與宋璟源乾曜同日上官命宴東堂賜詩應制', '奉和御製與宋璟源乾曜同日上官命宴东堂賜诗應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["大塊鎔羣品，經生偶聖時。","猥承三事命，虛忝百僚師。","右揆謀華碩，前星傅重資。","連騫求舊禮，濫典樂賢詩。","賜釜同榮拜，摐金宴宰司。","菊花吹御酒，蘭葉捧天詞。","寶歷休明盛，頹年晷漏衰。","少留青史筆，未敢赤松期。"]', '["大塊鎔羣品，經生偶聖时。","猥承三事命，虛忝百僚師。","右揆謀华碩，前星傅重資。","連騫求旧禮，濫典乐賢诗。","賜釜同榮拜，摐金宴宰司。","菊花吹御酒，蘭葉捧天词。","寶歷休明盛，頹年晷漏衰。","少留青史笔，未敢赤松期。"]', '诗', 'shi', '', NULL, '奉和御製與宋璟源乾曜同日上官命宴東堂賜詩應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb69c41-9772-4ca3-895d-1cba459143f4', '奉和聖製暇日與兄弟同遊興慶宮作應制', '奉和聖製暇日與兄弟同游兴慶宮作應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["漢武橫汾日，周王宴鎬年。","何如造區夏，復此睦親賢。","巢鳳新成閣，飛龍舊躍泉。","棣華歌尚在，桐葉戲仍傳。","禁籞氛埃隔，平臺景物連。","聖慈良有裕，王道固無偏。","問俗兆人阜，觀風五教宣。","獻圖開益地，張樂奏鈞天。","侍酒衢樽滿，詢芻諫鼓懸。","永言形友愛，萬國共周旋。"]', '["漢武橫汾日，周王宴鎬年。","何如造區夏，复此睦親賢。","巢鳳新成閣，飞龙旧躍泉。","棣华歌尚在，桐葉戲仍傳。","禁籞氛埃隔，平台景物連。","聖慈良有裕，王道固無偏。","问俗兆人阜，观风五教宣。","獻圖开益地，張乐奏鈞天。","侍酒衢樽满，詢芻諫鼓懸。","永言形友愛，万国共周旋。"]', '诗', 'shi', '', NULL, '奉和聖製暇日與兄弟同遊興慶宮作應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc82492a-347d-4f10-a71e-a6352b980dd8', '奉和聖製送王晙巡邊應制', '奉和聖製送王晙巡邊應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["六月歌周雅，三邊遣夏卿。","欲施攻戰法，先作簡稽行。","禮樂知謀帥，春秋識用兵。","一勞堪定國，萬里即長城。","策有和戎利，威傳破虜名。","軍前雨灑道，樓上月臨營。","別藻瑤華降，同衣錦襮榮。","關山由義近，戎馬爲恩輕。","絲竹路傍散，風雲馬上生。","朝廷謂吉甫，邦國望君平。"]', '["六月歌周雅，三邊遣夏卿。","欲施攻戰法，先作簡稽行。","禮乐知謀帥，春秋識用兵。","一勞堪定国，万里即长城。","策有和戎利，威傳破虜名。","軍前雨灑道，楼上月臨營。","別藻瑤华降，同衣錦襮榮。","关山由義近，戎马爲恩轻。","絲竹路傍散，风云马上生。","朝廷謂吉甫，邦国望君平。"]', '诗', 'shi', '', NULL, '奉和聖製送王晙巡邊應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cbf7e5a-61ed-4f6e-b9c0-7b58a2c066d1', '將赴朔方軍應制', '將赴朔方軍應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["禮樂逢明主，韜鈐用老臣。","恭憑神武策，遠御鬼方人。","供帳榮恩餞，山川喜詔巡。","天文日月麗，朝賦管弦新。","幼志傳三略，衰材謝六鈞。","膽由忠作伴，心固道爲鄰。","漢保河南地，胡清塞北塵。","連年大軍後，不日小康辰。","劒舞輕離別，歌酣忘苦辛。","從來思博望，許國不謀身。"]', '["禮乐逢明主，韜鈐用老臣。","恭憑神武策，远御鬼方人。","供帳榮恩餞，山川喜詔巡。","天文日月丽，朝賦管弦新。","幼志傳三略，衰材謝六鈞。","膽由忠作伴，心固道爲鄰。","漢保河南地，胡清塞北塵。","連年大軍後，不日小康辰。","劒舞轻離別，歌酣忘苦辛。","從来思博望，許国不謀身。"]', '诗', 'shi', '', NULL, '將赴朔方軍應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a2e5449-302c-4739-932b-407dc9f89bc5', '奉和聖製爰因巡省途次舊居應制', '奉和聖製爰因巡省途次旧居應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["葱鬱興王郡，殷憂啓聖圖。","周成會西土，漢武幸南都。","歲卜鑾輿邁，農祠鴈政敷。","武威稜外域，文教靡中區。","警蹕干戈捧，朝宗萬玉趨。","舊藩人事革，新化國容殊。","壁有真龍畫，庭餘鳴鳳梧。","叢觴祝堯壽，合鼎獻湯廚。","陽樂寒初變，春恩蟄更蘇。","三耆頒命服，五稔復田輸。","君賦大風起，人歌湛露濡。","從臣觀玉葉，方願紀靈符。"]', '["葱鬱兴王郡，殷憂啓聖圖。","周成會西土，漢武幸南都。","歲卜鑾輿邁，農祠鴈政敷。","武威稜外域，文教靡中區。","警蹕干戈捧，朝宗万玉趨。","旧藩人事革，新化国容殊。","壁有真龙畫，庭餘鳴鳳梧。","叢觴祝堯壽，合鼎獻湯廚。","陽乐寒初变，春恩蟄更蘇。","三耆頒命服，五稔复田輸。","君賦大风起，人歌湛露濡。","從臣观玉葉，方願紀靈符。"]', '诗', 'shi', '', NULL, '奉和聖製爰因巡省途次舊居應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('873123a2-3936-4271-8564-43d88d124a5b', '宿直溫泉宮羽林獻詩', '宿直溫泉宮羽林獻诗', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["冬狩美秦正，新豐樂漢行。","星陳玄武閣，月對羽林營。","寒木羅霜仗，空山響夜更。","恩深靈液暖，節勁古松貞。","文武皆王事，輸心不爲名。"]', '["冬狩美秦正，新豐乐漢行。","星陳玄武閣，月对羽林營。","寒木羅霜仗，空山响夜更。","恩深靈液暖，節勁古松貞。","文武皆王事，輸心不爲名。"]', '诗', 'shi', '', NULL, '宿直溫泉宮羽林獻詩 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec65055-96a1-418f-a7e6-ad6fcfc0630a', '玄武門侍射', '玄武门侍射', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["射觀通玄闕，兵欄闢御筵。","雕弧月半上，畫的暈重圓。","羿后神幽贊，靈王法暗傳。","貫心精四返，飲羽妙三聯。","雪鶴來銜箭，星麟下集弦。","一逢軍宴洽，萬慶武功宣。"]', '["射观通玄闕，兵欄闢御筵。","雕弧月半上，畫的暈重圓。","羿后神幽贊，靈王法暗傳。","貫心精四返，饮羽妙三聯。","雪鹤来銜箭，星麟下集弦。","一逢軍宴洽，万慶武功宣。"]', '诗', 'shi', '', NULL, '玄武門侍射 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595957c3-e3a1-475c-a24e-6bdfee3569de', '扈從南出雀鼠谷', '扈從南出雀鼠谷', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["豫動三靈贊，時巡四海威。","陝關凌曙出，平路半春歸。","霍鎮迎雲罕，汾河送羽旂。","山南柳半密，谷北草全稀。","遲日宜華蓋，和風入袷衣。","上林千里近，應見百花飛。"]', '["豫动三靈贊，时巡四海威。","陝关凌曙出，平路半春归。","霍鎮迎云罕，汾河送羽旂。","山南柳半密，谷北草全稀。","遲日宜华蓋，和风入袷衣。","上林千里近，應见百花飞。"]', '诗', 'shi', '', NULL, '扈從南出雀鼠谷 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ecf712-eb17-4d6c-9240-b7f4856e725e', '洛橋北亭詔餞諸刺史', '洛橋北亭詔餞諸刺史', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["離亭拂御溝，別曲舞船樓。","詔餞朝廷牧，符分海縣憂。","股肱還入郡，父母更臨州。","扇逐仁風傳，車隨霖雨流。","恩光水上溢，榮色柳間浮。","預待羣方最，三公不遠求。"]', '["離亭拂御溝，別曲舞船楼。","詔餞朝廷牧，符分海縣憂。","股肱還入郡，父母更臨州。","扇逐仁风傳，车隨霖雨流。","恩光水上溢，榮色柳间浮。","預待羣方最，三公不远求。"]', '诗', 'shi', '', NULL, '洛橋北亭詔餞諸刺史 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa8dde6-7163-4287-b30e-2bacd113924d', '東都酺宴', '东都酺宴', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["堯舜傳天下，同心致太平。","吾君內舉聖，遠合至公情。","錫命承丕業，崇親享大名。","二天資廣運，兩曜益齊明。","道暢昆蟲樂，恩深朽蠹榮。","皇輿久西幸，留鎮在東京。","合宴千官入，分曹百戲呈。","樂來嫌景遽，酒著訝寒輕。","喜氣連雲閣，歡呼動洛城。","人間知幾代，今日見河清。"]', '["堯舜傳天下，同心致太平。","吾君內舉聖，远合至公情。","錫命承丕業，崇親享大名。","二天資廣運，兩曜益齊明。","道暢昆蟲乐，恩深朽蠹榮。","皇輿久西幸，留鎮在东京。","合宴千官入，分曹百戲呈。","乐来嫌景遽，酒著訝寒轻。","喜氣連云閣，歡呼动洛城。","人间知幾代，今日见河清。"]', '诗', 'shi', '', NULL, '東都酺宴 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cae151d-99d7-4a50-a9f2-0d142c7f5a61', '奉酬韋祭酒嗣立偶遊龍門北溪忽懷驪山別業呈諸留守之作', '奉酬韋祭酒嗣立偶游龙门北溪忽懷驪山別業呈諸留守之作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["石澗泉虛落，松崖路曲迴。","聞君北溪下，想像南山隈。","近念鼎湖別，遙思雲嶂陪。","不同奇覯往，空覩斯文來。","歲後寒初變，春前芳未開。","黃蕤嫋岸柳，紫蕚折村梅。","盡室茲遊玩，盈門幾樂哉。","嗟留洛陽陌，夢詣建章臺。","野失巢由性，朝非元凱才。","布懷欽遠迹，幽意日塵埃。"]', '["石澗泉虛落，松崖路曲迴。","闻君北溪下，想像南山隈。","近念鼎湖別，遙思云嶂陪。","不同奇覯往，空覩斯文来。","歲後寒初变，春前芳未开。","黄蕤嫋岸柳，紫蕚折村梅。","尽室茲游玩，盈门幾乐哉。","嗟留洛陽陌，梦詣建章台。","野失巢由性，朝非元凱才。","布懷欽远迹，幽意日塵埃。"]', '诗', 'shi', '', NULL, '奉酬韋祭酒嗣立偶遊龍門北溪忽懷驪山別業呈諸留守之作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec7fe3b3-c036-4fa2-82e4-e5a015475df3', '奉酬韋祭酒自湯還都經龍門北溪莊見貽之作', '奉酬韋祭酒自湯還都經龙门北溪莊见貽之作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聞君湯井至，瀟灑憇郊林。","拂曙攜清賞，披雲覯綠岑。","歡言遊覽意，款曲望歸心。","是日期佳客，同山忽異尋。","桃花迂路轉，楊柳間門深。","泛舟伊水漲，繫馬香樹陰。","繁弦弄水族，嬌吹狎沙禽。","春滿汀色媚，景斜嵐氣侵。","懷仁殊未遠，重德匪專臨。","來藻敷幽思，連詞報所欽。"]', '["闻君湯井至，瀟灑憇郊林。","拂曙携清賞，披云覯綠岑。","歡言游覽意，款曲望归心。","是日期佳客，同山忽異尋。","桃花迂路轉，楊柳间门深。","泛舟伊水漲，繫马香樹陰。","繁弦弄水族，嬌吹狎沙禽。","春满汀色媚，景斜嵐氣侵。","懷仁殊未远，重德匪專臨。","来藻敷幽思，連词報所欽。"]', '诗', 'shi', '', NULL, '奉酬韋祭酒自湯還都經龍門北溪莊見貽之作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc52f325-9edf-4fe3-ad7a-6261535df837', '酬崔光祿冬日述懷贈答', '酬崔光祿冬日述懷贈答', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["徐陳嘗並作，枚馬亦同時。","各負當朝譽，俱承明主私。","夫君邁前侶，觀國騁奇姿。","山似鳴威鳳，泉如出寶龜。","才雄子雲筆，學廣仲舒帷。","紫綬拂三寺，朱門臨九逵。","昔我含香日，聯爾縉雲司。","朝攜蘭省步，夕退竹林期。","中路一分手，數載來何遲。","求友還相得，羣英復在茲。","留臺少人務，方駕遞尋追。","涉玩懷同賞，霑芳憶共持。","迎賓南澗飲，載妓東城嬉。","春郊綠畝秀，秋澗白雲滋。","名畫披人物，良書討滯疑。","興來光不惜，歡往迹如遺。","歲晏罷行樂，層城間所思。","夜魂燈處厭，朝髪鏡前衰。","忽枉崔駰什，兼流韋孟詞。","曲高彌寡和，主善代爲師。","齊戒觀華玉，留連歎色絲。","終慙起予者，何足與言詩。"]', '["徐陳嘗並作，枚马亦同时。","各負當朝譽，俱承明主私。","夫君邁前侶，观国騁奇姿。","山似鳴威鳳，泉如出寶龟。","才雄子云笔，学廣仲舒帷。","紫綬拂三寺，朱门臨九逵。","昔我含香日，聯爾縉云司。","朝携蘭省步，夕退竹林期。","中路一分手，數載来何遲。","求友還相得，羣英复在茲。","留台少人務，方駕遞尋追。","涉玩懷同賞，霑芳憶共持。","迎賓南澗饮，載妓东城嬉。","春郊綠畝秀，秋澗白云滋。","名畫披人物，良书討滯疑。","兴来光不惜，歡往迹如遺。","歲晏罷行乐，層城间所思。","夜魂灯处厭，朝髪镜前衰。","忽枉崔駰什，兼流韋孟词。","曲高彌寡和，主善代爲師。","齊戒观华玉，留連歎色絲。","終慙起予者，何足與言诗。"]', '诗', 'shi', '', NULL, '酬崔光祿冬日述懷贈答 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da06a8dc-4ab5-452f-8722-b3598aa961eb', '同劉給事城南宴集', '同劉給事城南宴集', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["水竹幽閑地，簪纓近侍臣。","雍容乘暇日，瀟灑出囂塵。","樹對思朋鳥，池深入養鱗。","管弦高逐吹，歌舞妙含春。","老子叨專席，歡邀隔縉紳。","此中情不淺，遙寄賞心人。"]', '["水竹幽闲地，簪纓近侍臣。","雍容乘暇日，瀟灑出囂塵。","樹对思朋鸟，池深入養鱗。","管弦高逐吹，歌舞妙含春。","老子叨專席，歡邀隔縉紳。","此中情不淺，遙寄賞心人。"]', '诗', 'shi', '', NULL, '同劉給事城南宴集 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5383bba-c471-4356-855c-86d8e484de01', '溫泉馮劉二監客舍觀妓', '溫泉馮劉二監客舍观妓', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["溫谷寒林薄，羣遊樂事多。","佳人蹀駿馬，乘月夜相過。","秀色然紅黛，嬌香發綺羅。","鏡前鸞對舞，琴裏鳳傳歌。","妬寵傾新意，銜恩奈老何。","爲君留上客，歡笑斂雙蛾。"]', '["溫谷寒林薄，羣游乐事多。","佳人蹀駿马，乘月夜相過。","秀色然紅黛，嬌香發綺羅。","镜前鸾对舞，琴裏鳳傳歌。","妬寵傾新意，銜恩奈老何。","爲君留上客，歡笑斂雙蛾。"]', '诗', 'shi', '', NULL, '溫泉馮劉二監客舍觀妓 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a591aab-55b1-42d4-b988-5d97e6765026', '寄許八', '寄許八', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["萬類春皆樂，徂顏獨不怡。","年來人更老，花發意先衰。","乳鵲穿壇畫，巢蜂觸網絲。","平生美容色，宿昔影中疑。","遠道何由夢，同心在者誰。","西風欲誰語，憫默遂無詞。"]', '["万類春皆乐，徂顏独不怡。","年来人更老，花發意先衰。","乳鵲穿壇畫，巢蜂觸網絲。","平生美容色，宿昔影中疑。","远道何由梦，同心在者誰。","西风欲誰語，憫默遂無词。"]', '诗', 'shi', '', NULL, '寄許八 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e335dccd-55a2-4885-8c2a-baf7553ce7aa', '送蘇合宮頲', '送蘇合宮頲', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["都邑羣方首，商泉舊俗訛。","變風須愷悌，成化佇弦歌。","疇昔珪璋友，雍容文雅多。","振纓遊省闥，鏘玉宰京河。","別曲鸞初下，行軒雉尚過。","百壺非餞意，流詠在人和。"]', '["都邑羣方首，商泉旧俗訛。","变风須愷悌，成化佇弦歌。","疇昔珪璋友，雍容文雅多。","振纓游省闥，鏘玉宰京河。","別曲鸾初下，行軒雉尚過。","百壺非餞意，流詠在人和。"]', '诗', 'shi', '', NULL, '送蘇合宮頲 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c119ce-2f92-439d-b771-c0d91f2224f0', '送喬安邑備', '送喬安邑備', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["書閣移年歲，文明難復辭。","歡言冬雪滿，恨別夏雲滋。","外尹方爲政，高明自不欺。","老人驂馭往，童子狎雛嬉。","日茂西河俗，寂寥東觀期。","遙懷秀才令，京洛見新詩。"]', '["书閣移年歲，文明难复辞。","歡言冬雪满，恨別夏云滋。","外尹方爲政，高明自不欺。","老人驂馭往，童子狎雛嬉。","日茂西河俗，寂寥东观期。","遙懷秀才令，京洛见新诗。"]', '诗', 'shi', '', NULL, '送喬安邑備 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0f3ede-d7f5-4f17-8a82-5cdb15699ada', '送趙二尚書彥昭北伐', '送趙二尚书彥昭北伐', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["虜地河冰合，邊城備此時。","兵連紫塞路，將舉白雲司。","提劒榮中貴，銜珠盛出師。","日華光組練，風色焰旌旗。","投筆尊前起，橫戈馬上辭。","梅花吹別引，楊柳賦歸詩。"]', '["虜地河冰合，邊城備此时。","兵連紫塞路，將舉白云司。","提劒榮中貴，銜珠盛出師。","日华光組練，风色焰旌旗。","投笔尊前起，橫戈马上辞。","梅花吹別引，楊柳賦归诗。"]', '诗', 'shi', '', NULL, '送趙二尚書彥昭北伐 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3634f7ff-333d-49cf-a3d8-509be0fc8ea0', '石門別楊六欽望', '石门別楊六欽望', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["燕人同竄越，萬里自相哀。","影響無期會，江山此地來。","暮年傷泛梗，累日慰寒灰。","潮水東南落，浮雲西北回。","俱看石門遠，倚棹兩悲哉。"]', '["燕人同竄越，万里自相哀。","影响無期會，江山此地来。","暮年傷泛梗，累日慰寒灰。","潮水东南落，浮云西北回。","俱看石门远，倚棹兩悲哉。"]', '诗', 'shi', '', NULL, '石門別楊六欽望 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b4d3049-52ed-4354-a03d-8e01c9a2ca54', '南中送北使二首 一', '南中送北使二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["傳聞合浦葉，曾向洛陽飛。","何日南風至，還隨北使歸。","紅顏渡嶺歇，白首對秋衰。","高歌何由見，層堂不可違。","誰憐炎海曲，淚盡血沾衣。"]', '["傳闻合浦葉，曾向洛陽飞。","何日南风至，還隨北使归。","紅顏渡嶺歇，白首对秋衰。","高歌何由见，層堂不可違。","誰怜炎海曲，泪尽血沾衣。"]', '诗', 'shi', '', NULL, '南中送北使二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798dd3aa-d668-407d-af17-9bc0c998ec6a', '南中送北使二首 二', '南中送北使二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["待罪居重譯，窮愁暮雨秋。","山臨鬼門路，城繞瘴江流。","人事今如此，生涯尚可求。","逢君入鄉縣，傳我念京周。","別恨歸途遠，離言暮景遒。","夷歌翻下淚，蘆酒未消愁。","聞有胡兵急，深懷漢國羞。","和親先是詐，款塞果爲讐。","釋繫應分爵，蠲徒幾復侯。","廉頗誠未老，孫叔宜無謀。","若道馮唐事，皇恩尚可收。"]', '["待罪居重譯，窮愁暮雨秋。","山臨鬼门路，城繞瘴江流。","人事今如此，生涯尚可求。","逢君入乡縣，傳我念京周。","別恨归途远，離言暮景遒。","夷歌翻下泪，蘆酒未消愁。","闻有胡兵急，深懷漢国羞。","和親先是詐，款塞果爲讐。","釋繫應分爵，蠲徒幾复侯。","廉頗誠未老，孫叔宜無謀。","若道馮唐事，皇恩尚可收。"]', '诗', 'shi', '', NULL, '南中送北使二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863e2d68-af9b-41ce-a110-ba80ee8a2bc0', '送趙順直郎中赴安西副大都督', '送趙順直郎中赴安西副大都督', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["絕鎮功難立，懸軍命匪輕。","復承遷相後，彌重任賢情。","將起神仙地，才稱禮樂英。","長心堪繫虜，短語足論兵。","日授休門法，星教置陣名。","龍泉恩已著，燕頷相終成。","月窟窮天遠，河源入塞清。","老天操別翰，承旨頌升平。"]', '["絕鎮功难立，懸軍命匪轻。","复承遷相後，彌重任賢情。","將起神仙地，才稱禮乐英。","长心堪繫虜，短語足論兵。","日授休门法，星教置陣名。","龙泉恩已著，燕頷相終成。","月窟窮天远，河源入塞清。","老天操別翰，承旨頌升平。"]', '诗', 'shi', '', NULL, '送趙順直郎中赴安西副大都督 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b2259e-8988-4ec4-8bd1-31e12a2a6c2d', '送宋休遠之蜀任', '送宋休远之蜀任', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["求友殊損益，行道異窮申。","綴我平生氣，吐贈薄遊人。","結恩事明主，忍愛遠辭親。","色麗成都俗，膏腴蜀水濱。","如何從宦子，堅白共緇磷。","日月千齡旦，河山萬族春。","懷鉛書瑞府，橫草事邊塵。","不及安人吏，能令王化淳。"]', '["求友殊損益，行道異窮申。","綴我平生氣，吐贈薄游人。","結恩事明主，忍愛远辞親。","色丽成都俗，膏腴蜀水濱。","如何從宦子，堅白共緇磷。","日月千齡旦，河山万族春。","懷鉛书瑞府，橫草事邊塵。","不及安人吏，能令王化淳。"]', '诗', 'shi', '', NULL, '送宋休遠之蜀任 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7093fd5c-e451-48e4-b4ff-f462c22a8f17', '岳州別梁六入朝', '岳州別梁六入朝', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["遠蒞長沙渚，欣逢賈誼才。","江山疲應接，風日復晴開。","江樹雲間斷，湘山水上來。","近洲朝鷺集，古戍夜猿哀。","岸杼含蒼捄，河蒲秀紫臺。","月餘偏地賞，心盡故人杯。","自我違京洛，嗟君此泝洄。","容華因別老，交舊與年頹。","夢見長安陌，朝宗實盛哉。"]', '["远蒞长沙渚，欣逢賈誼才。","江山疲應接，风日复晴开。","江樹云间斷，湘山水上来。","近洲朝鷺集，古戍夜猿哀。","岸杼含蒼捄，河蒲秀紫台。","月餘偏地賞，心尽故人杯。","自我違京洛，嗟君此泝洄。","容华因別老，交旧與年頹。","梦见长安陌，朝宗實盛哉。"]', '诗', 'shi', '', NULL, '岳州別梁六入朝 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9f8eae-15d1-4281-9c51-9f5b69f576e4', '相州冬日早衙', '相州冬日早衙', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["城外宵鐘斂，閨中曙火殘。","朝光曜庭雪，宿凍聚池寒。","正色臨廳事，疑詞定筆端。","除苛囹圄息，伐枳吏人寬。","河內功猶淺，淮陽疾未安。","鏡中星髪變，頓使世情闌。"]', '["城外宵鐘斂，閨中曙火殘。","朝光曜庭雪，宿凍聚池寒。","正色臨廳事，疑词定笔端。","除苛囹圄息，伐枳吏人寬。","河內功猶淺，淮陽疾未安。","镜中星髪变，頓使世情闌。"]', '诗', 'shi', '', NULL, '相州冬日早衙 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc82e62-b5ca-4442-b12f-559b3425b1d4', '岳州西城', '岳州西城', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["水國何遼曠，風波遂極天。","西江三紀合，南浦二湖連。","危堞臨清境，煩憂暫豁然。","九圍觀掌內，萬象閱眸前。","日去長沙渚，山橫雲夢田。","汀葭變秋色，津樹入寒煙。","潛穴探靈詭，浮生揖聖仙。","至今人不見，跡滅事空傳。"]', '["水国何遼曠，风波遂極天。","西江三紀合，南浦二湖連。","危堞臨清境，煩憂暫豁然。","九圍观掌內，万象閱眸前。","日去长沙渚，山橫云梦田。","汀葭变秋色，津樹入寒煙。","潛穴探靈詭，浮生揖聖仙。","至今人不见，跡滅事空傳。"]', '诗', 'shi', '', NULL, '岳州西城 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141c2c9c-d642-4188-b7fc-0939eceed0e8', '岳州觀競渡', '岳州观競渡', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["畫作飛鳧艇，雙雙競拂流。","低裝山色變，急棹水華浮。","土尚三閭俗，江傳二女遊。","齊歌迎孟姥，獨舞送陽侯。","鼓發南湖溠，標爭西驛樓。","並驅常詫速，非畏日光遒。"]', '["畫作飞鳧艇，雙雙競拂流。","低裝山色变，急棹水华浮。","土尚三閭俗，江傳二女游。","齊歌迎孟姥，独舞送陽侯。","鼓發南湖溠，標爭西驛楼。","並驱常詫速，非畏日光遒。"]', '诗', 'shi', '', NULL, '岳州觀競渡 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192c44aa-ba73-4533-8289-991da168a7ba', '對酒行巴陵作', '对酒行巴陵作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["留侯封萬戶，園令壽千金。","本爲成王業，初由賦上林。","繁榮安足恃，霜露遞相尋。","鳥哭楚山外，猿啼湘水陰。","夢中城闕近，天畔海雲深。","空對忘憂酌，離憂不去心。"]', '["留侯封万戶，园令壽千金。","本爲成王業，初由賦上林。","繁榮安足恃，霜露遞相尋。","鸟哭楚山外，猿啼湘水陰。","梦中城闕近，天畔海云深。","空对忘憂酌，離憂不去心。"]', '诗', 'shi', '', NULL, '對酒行巴陵作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7a85bf-1dd4-47a5-87b6-010e77b5b017', '岳州宴姚紹之', '岳州宴姚紹之', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["杞梓滯江濱，光華向日新。","難兄金作友，媚子玉爲人。","山水含秋興，池亭借善鄰。","簷松風送靜，院竹鳥來馴。","翠斝吹黃菊，琱盤鱠紫鱗。","緩歌將醉舞，爲拂繡衣塵。"]', '["杞梓滯江濱，光华向日新。","难兄金作友，媚子玉爲人。","山水含秋兴，池亭借善鄰。","簷松风送静，院竹鸟来馴。","翠斝吹黄菊，琱盤鱠紫鱗。","緩歌將醉舞，爲拂繡衣塵。"]', '诗', 'shi', '', NULL, '岳州宴姚紹之 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b80b56-eedc-418a-aeb2-30ed70563622', '岳州九日宴道觀西閣', '岳州九日宴道观西閣', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["搖落長年歎，蹉跎遠宦心。","北風嘶代馬，南浦宿陽禽。","佳此黃花酌，酣餘白首吟。","涼雲霾楚望，濛雨蔽荆岑。","登眺思清景，誰將眷濁陰。","釣歌出江霧，樵唱入山林。","魚以嘉名采，木爲美材侵。","大道由中悟，逍遙匪外尋。","參佐多君子，詞華妙賞音。","留題洞庭觀，望古意何深。"]', '["搖落长年歎，蹉跎远宦心。","北风嘶代马，南浦宿陽禽。","佳此黄花酌，酣餘白首吟。","涼云霾楚望，濛雨蔽荆岑。","登眺思清景，誰將眷濁陰。","釣歌出江霧，樵唱入山林。","鱼以嘉名采，木爲美材侵。","大道由中悟，逍遙匪外尋。","參佐多君子，词华妙賞音。","留題洞庭观，望古意何深。"]', '诗', 'shi', '', NULL, '岳州九日宴道觀西閣 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f01288-1b08-48a8-8a82-2ef23fac71b7', '岳州作', '岳州作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["水國生秋草，離居再及瓜。","山川臨洞穴，風日望長沙。","物土南州異，關河北信賒。","日昏聞怪鳥，地熱見修虵。","遠人夢歸路，瘦馬嘶去家。","正有江潭月，徘徊戀九華。"]', '["水国生秋草，離居再及瓜。","山川臨洞穴，风日望长沙。","物土南州異，关河北信賒。","日昏闻怪鸟，地熱见修虵。","远人梦归路，瘦马嘶去家。","正有江潭月，徘徊戀九华。"]', '诗', 'shi', '', NULL, '岳州作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362ff17d-e5ce-45cb-b273-c23651772264', '遊洞庭湖', '游洞庭湖', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["平湖曉望分，仙嶠氣氛氳。","鼓枻乘清渚，尋峰弄白雲。","江寒天一色，日靜水重紋。","樹坐參猿嘯，沙行入鷺羣。","緣源斑篠密，罥徑綠蘿紛。","洞穴傳虛應，楓林覺自熏。","雙童有靈藥，願取獻明君。"]', '["平湖晓望分，仙嶠氣氛氳。","鼓枻乘清渚，尋峰弄白云。","江寒天一色，日静水重紋。","樹坐參猿嘯，沙行入鷺羣。","緣源斑篠密，罥徑綠蘿紛。","洞穴傳虛應，楓林覺自熏。","雙童有靈藥，願取獻明君。"]', '诗', 'shi', '', NULL, '遊洞庭湖 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0133ca9a-89ec-4317-87c0-4f9ab2af8ee4', '巴丘春作', '巴丘春作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["日出洞庭水，春山挂斷霞。","江涔相映發，卉木共紛華。","湘戍南浮闊，荆關北望賒。","湖陰窺魍魎，丘勢辨巴蛇。","島戶巢爲館，漁人艇作家。","自憐心問景，三歲客長沙。"]', '["日出洞庭水，春山挂斷霞。","江涔相映發，卉木共紛华。","湘戍南浮闊，荆关北望賒。","湖陰窺魍魎，丘勢辨巴蛇。","島戶巢爲館，漁人艇作家。","自怜心问景，三歲客长沙。"]', '诗', 'shi', '', NULL, '巴丘春作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80dc2409-d246-45b6-a2ed-85e575ab7bdf', '岳州夜坐', '岳州夜坐', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["炎洲苦三伏，永日臥孤城。","賴此閑庭夜，蕭條夜月明。","獨歌還太息，幽感見餘聲。","江近鶴時呌，山深猿屢鳴。","息心觀有欲，棄知返無名。","五十知天命，吾其達此生。"]', '["炎洲苦三伏，永日臥孤城。","賴此闲庭夜，蕭條夜月明。","独歌還太息，幽感见餘声。","江近鹤时呌，山深猿屢鳴。","息心观有欲，棄知返無名。","五十知天命，吾其達此生。"]', '诗', 'shi', '', NULL, '岳州夜坐 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb99e167-6931-4251-9270-0b0bf5616302', '別㴩湖', '別㴩湖', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["念別㴩湖去，浮舟更一臨。","千峰出浪險，萬木抱煙深。","南郡延恩渥，東山戀宿心。","露花香欲醉，時鳥囀餘音。","涉趣皆留賞，無奇不徧尋。","莫言山水間，幽意在鳴琴。"]', '["念別㴩湖去，浮舟更一臨。","千峰出浪險，万木抱煙深。","南郡延恩渥，东山戀宿心。","露花香欲醉，时鸟囀餘音。","涉趣皆留賞，無奇不徧尋。","莫言山水间，幽意在鳴琴。"]', '诗', 'shi', '', NULL, '別㴩湖 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1f2c713-612e-4d82-8dd7-8c8d2804ea5a', '伯奴邊見歸田賦因投趙侍御', '伯奴邊见归田賦因投趙侍御', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["爾家歎窮鳥，吾族賦歸田。","莫道榮枯異，同嗟世網牽。","黃陵浮汨渚，青草會湘川。","去國逾三歲，茲山老二年。","寒鴞鳴舍下，昏虎臥籬前。","客淚堪斑竹，離亭欲贈荃。","放言久無次，觸興感成篇。"]', '["爾家歎窮鸟，吾族賦归田。","莫道榮枯異，同嗟世網牽。","黄陵浮汨渚，青草會湘川。","去国逾三歲，茲山老二年。","寒鴞鳴舍下，昏虎臥籬前。","客泪堪斑竹，離亭欲贈荃。","放言久無次，觸兴感成篇。"]', '诗', 'shi', '', NULL, '伯奴邊見歸田賦因投趙侍御 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642951c0-7c42-4816-b704-bed74f385bd9', '清遠江峽山寺', '清远江峽山寺', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["流落經荒外，逍遙此梵宮。","雲峰吐月白，石壁淡烟紅。","寶塔靈仙湧，懸龕造化功。","天香涵竹氣，虛唄引松風。","簷牖飛花入，廊房激水通。","猿鳴知谷靜，魚戲辨江空。","靜默將何貴，惟應心境同。"]', '["流落經荒外，逍遙此梵宮。","云峰吐月白，石壁淡烟紅。","寶塔靈仙湧，懸龕造化功。","天香涵竹氣，虛唄引松风。","簷牖飞花入，廊房激水通。","猿鳴知谷静，鱼戲辨江空。","静默將何貴，惟應心境同。"]', '诗', 'shi', '', NULL, '清遠江峽山寺 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9786bece-644a-42cc-9835-826a4ba3af3c', '春雨早雷', '春雨早雷', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["東北春風至，飄飄帶雨來。","拂黃先變柳，點素早驚梅。","樹藹懸書閣，煙含作賦臺。","河魚未上凍，江蟄已聞雷。","美人宵夢著，金屏曙不開。","無緣一啓齒，空酌萬年杯。"]', '["东北春风至，飄飄带雨来。","拂黄先变柳，点素早驚梅。","樹藹懸书閣，煙含作賦台。","河鱼未上凍，江蟄已闻雷。","美人宵梦著，金屏曙不开。","無緣一啓齒，空酌万年杯。"]', '诗', 'shi', '', NULL, '春雨早雷 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac03285d-80c4-472f-8d6e-959166125761', '聞雨', '闻雨', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["窮冬萬花匝，永夜百憂攢。","危戍臨江火，空齋入雨寒。","斷猿知屢別，嘶鴈覺虛彈。","心對爐灰死，顏隨庭樹殘。","舊恩懷未報，傾膽鏡中看。"]', '["窮冬万花匝，永夜百憂攢。","危戍臨江火，空斋入雨寒。","斷猿知屢別，嘶鴈覺虛彈。","心对爐灰死，顏隨庭樹殘。","旧恩懷未報，傾膽镜中看。"]', '诗', 'shi', '', NULL, '聞雨 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('120201c1-1410-4a74-9e69-72d689f979de', '赦歸在道中作', '赦归在道中作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["陳焦心息盡，死意不期生。","何幸光華旦，流人歸上京。","愁將網共解，服與代俱明。","復是三階正，還逢四海平。","誰能定禮樂，爲國著功成。"]', '["陳焦心息尽，死意不期生。","何幸光华旦，流人归上京。","愁將網共解，服與代俱明。","复是三階正，還逢四海平。","誰能定禮乐，爲国著功成。"]', '诗', 'shi', '', NULL, '赦歸在道中作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca392e5-dfb8-4386-921c-0b6dc6abf9a0', '喜度嶺', '喜度嶺', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["東漢興唐曆，南河復禹謀。","寧知瘴癘地，生入帝皇州。","雷雨蘇蟲蟄，春陽放鷽鳩。","洄沿炎海畔，登降閩山陬。","嶺路分中夏，川源得上流。","見花便獨笑，看草即忘憂。","自始居重譯，天星已再周。","鄉關絕歸望，親戚不相求。","棄杖枯還植，窮鱗涸更浮。","道消黃鶴去，運啓白駒留。","江妾晨炊黍，津童夜櫂舟。","盛明良可遇，莫後洛城遊。"]', '["东漢兴唐曆，南河复禹謀。","寧知瘴癘地，生入帝皇州。","雷雨蘇蟲蟄，春陽放鷽鳩。","洄沿炎海畔，登降閩山陬。","嶺路分中夏，川源得上流。","见花便独笑，看草即忘憂。","自始居重譯，天星已再周。","乡关絕归望，親戚不相求。","棄杖枯還植，窮鱗涸更浮。","道消黄鹤去，運啓白駒留。","江妾晨炊黍，津童夜櫂舟。","盛明良可遇，莫後洛城游。"]', '诗', 'shi', '', NULL, '喜度嶺 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079ce365-2d9b-4ca8-a8d0-6610c9552857', '奉和聖製潼關口號應制', '奉和聖製潼关口號應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天德平無外，關門東復西。","不將千里隔，何用一丸泥。"]', '["天德平無外，关门东复西。","不將千里隔，何用一丸泥。"]', '诗', 'shi', '', NULL, '奉和聖製潼關口號應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6748a93d-2047-4c93-a2bf-b0a63186ceb8', '奉蕭令嵩酒幷詩', '奉蕭令嵩酒幷诗', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["樂奏天恩滿，杯來秋興高。","更蒙蕭相國，對席飲醇醪。"]', '["乐奏天恩满，杯来秋兴高。","更蒙蕭相国，对席饮醇醪。"]', '诗', 'shi', '', NULL, '奉蕭令嵩酒幷詩 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac670df7-5a42-46d9-b756-a99da3f90ff1', '奉宇文黃門融酒', '奉宇文黄门融酒', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖德垂甘露，天章下大風。","又乘黃閣賞，願作黑頭公。"]', '["聖德垂甘露，天章下大风。","又乘黄閣賞，願作黑头公。"]', '诗', 'shi', '', NULL, '奉宇文黃門融酒 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad46b11e-f3a1-4a89-942b-3e9e8f96c0bc', '奉裴中書光庭酒', '奉裴中书光庭酒', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西掖恩華降，南宮命席闌。","詎知雞樹後，更接鳳池歡。"]', '["西掖恩华降，南宮命席闌。","詎知雞樹後，更接鳳池歡。"]', '诗', 'shi', '', NULL, '奉裴中書光庭酒 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('038112c9-7c9c-4cf5-9511-85b6032a011f', '清夜酌', '清夜酌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["秋陰士多感，雨息夜無塵。","清樽宜明月，復有平生人。"]', '["秋陰士多感，雨息夜無塵。","清樽宜明月，复有平生人。"]', '诗', 'shi', '', NULL, '清夜酌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491c51fa-7f8f-4a59-b9c2-aedaf2b3add9', '醉中作', '醉中作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["醉後樂無極，彌勝未醉時。","動容皆是舞，出語總成詩。"]', '["醉後乐無極，彌勝未醉时。","动容皆是舞，出語總成诗。"]', '诗', 'shi', '', NULL, '醉中作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298eebb4-4352-4e21-9c0e-257c570c1e43', '送梁知微渡海東', '送梁知微渡海东', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["今日此相送，明年此相待。","天上客星回，知君渡東海。"]', '["今日此相送，明年此相待。","天上客星回，知君渡东海。"]', '诗', 'shi', '', NULL, '送梁知微渡海東 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d506b4fe-8601-4518-a5c9-2f5fede55b71', '寄劉道士舃', '寄劉道士舃', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["真人降紫氣，邀我丹田宮。","遠寄雙飛舄，飛飛不礙空。"]', '["真人降紫氣，邀我丹田宮。","远寄雙飞舄，飞飞不礙空。"]', '诗', 'shi', '', NULL, '寄劉道士舃 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c1c696-51ac-40ad-acd2-ffb47f654b8d', '書香能和尚塔', '书香能和尚塔', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["大師捐世去，空餘法力在。","遠寄無礙香，心隨到南海。"]', '["大師捐世去，空餘法力在。","远寄無礙香，心隨到南海。"]', '诗', 'shi', '', NULL, '書香能和尚塔 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5227d95f-56ff-4728-82a5-aeacff85383a', '被使在蜀', '被使在蜀', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["即今三伏盡，尚自在臨邛。","歸途千里外，秋月定相逢。"]', '["即今三伏尽，尚自在臨邛。","归途千里外，秋月定相逢。"]', '诗', 'shi', '', NULL, '被使在蜀 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('558ffb46-5d66-4900-a1a9-08faaa1114de', '正朝摘梅', '正朝摘梅', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["蜀地寒猶暖，正朝發早梅。","偏驚萬里客，已復一年來。"]', '["蜀地寒猶暖，正朝發早梅。","偏驚万里客，已复一年来。"]', '诗', 'shi', '', NULL, '正朝摘梅 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c206849-80c6-4994-a9bb-8dde5aa5cd18', '蜀道後期', '蜀道後期', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["客心爭日月，來往預期程。","秋風不相待，先至洛陽城。"]', '["客心爭日月，来往預期程。","秋风不相待，先至洛陽城。"]', '诗', 'shi', '', NULL, '蜀道後期 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7448d60f-4828-410b-be11-d9b5c5f0163a', '廣州江中作', '廣州江中作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["去國年方晏，愁心轉不堪。","離人與江水，終日向西南。"]', '["去国年方晏，愁心轉不堪。","離人與江水，終日向西南。"]', '诗', 'shi', '', NULL, '廣州江中作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c77faa-1a12-435b-9e98-6d864de22597', '江中誦經', '江中誦經', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["實相歸懸解，虛心暗在通。","澄江明月內，應是色成空。"]', '["實相归懸解，虛心暗在通。","澄江明月內，應是色成空。"]', '诗', 'shi', '', NULL, '江中誦經 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d12b31-49b4-4905-ad8f-a3e0d7e6afb2', '江中遇黃領子劉隆', '江中遇黄領子劉隆', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["危石江中起，孤雲嶺上還。","相逢皆得意，何處是鄉關。"]', '["危石江中起，孤云嶺上還。","相逢皆得意，何处是乡关。"]', '诗', 'shi', '', NULL, '江中遇黃領子劉隆 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('696b11f5-3f54-47be-91e1-5f80ca2db4f1', '欽州守歲', '欽州守歲', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["故歲今宵盡，新年明旦來。","愁心隨斗柄，東北望春回。"]', '["故歲今宵尽，新年明旦来。","愁心隨斗柄，东北望春回。"]', '诗', 'shi', '', NULL, '欽州守歲 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee5d854-7170-47b5-aaa8-d52965765e0c', '岳州守歲二首 一', '岳州守歲二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["夜風吹醉舞，庭戶對酣歌。","愁逐前年少，歡迎今歲多。"]', '["夜风吹醉舞，庭戶对酣歌。","愁逐前年少，歡迎今歲多。"]', '诗', 'shi', '', NULL, '岳州守歲二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bfbf6d1-ee07-4a90-a6e1-60a3541f60eb', '岳州守歲二首 二', '岳州守歲二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["桃枝堪辟惡，爆竹好驚眠。","歌舞留今夕，猶言惜舊年。"]', '["桃枝堪辟惡，爆竹好驚眠。","歌舞留今夕，猶言惜旧年。"]', '诗', 'shi', '', NULL, '岳州守歲二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00aa4574-beb2-4a98-b3db-830f8442770b', '元朝', '元朝', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["今歲元日樂，不謝往年春。","知向來心道，誰爲昨夜人。"]', '["今歲元日乐，不謝往年春。","知向来心道，誰爲昨夜人。"]', '诗', 'shi', '', NULL, '元朝 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7983a68a-b434-4af0-a855-2e296aa658e3', '耗磨日飲二首 一', '耗磨日饮二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["耗磨傳茲日，縱橫道未宜。","但令不忌醉，翻是樂無爲。"]', '["耗磨傳茲日，縱橫道未宜。","但令不忌醉，翻是乐無爲。"]', '诗', 'shi', '', NULL, '耗磨日飲二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd1e5cdb-fdad-4a11-a994-ab2be03a7f47', '耗磨日飲二首 二', '耗磨日饮二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["上月今朝減，流傳耗磨辰。","還將不事事，同醉俗中人。"]', '["上月今朝減，流傳耗磨辰。","還將不事事，同醉俗中人。"]', '诗', 'shi', '', NULL, '耗磨日飲二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07679001-c11e-4ba3-84e8-abd569408298', '耗磨日飲', '耗磨日饮', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["春來半月度，俗忌一時閑。","不酌他鄉酒，惟堪對楚山。"]', '["春来半月度，俗忌一时闲。","不酌他乡酒，惟堪对楚山。"]', '诗', 'shi', '', NULL, '耗磨日飲 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('040c35ef-c7ac-4f3d-912a-14df1c1d7fef', '九日進茱萸山詩五首 一', '九日進茱萸山诗五首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["家居洛陽下，舉目見嵩山。","刻作茱萸節，情生造化間。"]', '["家居洛陽下，舉目见嵩山。","刻作茱萸節，情生造化间。"]', '诗', 'shi', '', NULL, '九日進茱萸山詩五首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69c804b2-a045-46ed-8d81-f79bbe4c6460', '九日進茱萸山詩五首 二', '九日進茱萸山诗五首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["黃花宜泛酒，青嶽好登高。","稽首明廷內，心爲天下勞。"]', '["黄花宜泛酒，青嶽好登高。","稽首明廷內，心爲天下勞。"]', '诗', 'shi', '', NULL, '九日進茱萸山詩五首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb155458-97a1-4501-92a4-8ed5e7e16696', '九日進茱萸山詩五首 三', '九日進茱萸山诗五首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["菊酒攜山客，萸囊繫牧童。","路疑隨大隗，心似問鴻蒙。"]', '["菊酒携山客，萸囊繫牧童。","路疑隨大隗，心似问鴻蒙。"]', '诗', 'shi', '', NULL, '九日進茱萸山詩五首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1c94af-0a17-487b-b6f3-3682d7c41713', '九日進茱萸山詩五首 四', '九日進茱萸山诗五首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["九日重陽數，三秋萬實成。","時來謁軒后，罷去坐蓬瀛。"]', '["九日重陽數，三秋万實成。","时来謁軒后，罷去坐蓬瀛。"]', '诗', 'shi', '', NULL, '九日進茱萸山詩五首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('843ba2b5-e612-4720-97c5-a81e1e43599a', '九日進茱萸山詩五首 五', '九日進茱萸山诗五首 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["晚節歡重九，高山上五千。","醉中知遇聖，夢裏見尋仙。"]', '["晚節歡重九，高山上五千。","醉中知遇聖，梦裏见尋仙。"]', '诗', 'shi', '', NULL, '九日進茱萸山詩五首 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c85a05da-3863-4ff6-8ec4-4fc9f32be0ea', '岳州看黃葉', '岳州看黄葉', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["白首看黃葉，徂顏復幾何。","空慙棠樹下，不見政成歌。"]', '["白首看黄葉，徂顏复幾何。","空慙棠樹下，不见政成歌。"]', '诗', 'shi', '', NULL, '岳州看黃葉 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d27c1e19-1d48-4015-bd16-fb4bf273ef20', '嶺南送使二首 一', '嶺南送使二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["獄中生白髮，嶺外罷紅顏。","古來相送處，凡得幾人還。"]', '["獄中生白髮，嶺外罷紅顏。","古来相送处，凡得幾人還。"]', '诗', 'shi', '', NULL, '嶺南送使二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1910f3-ed7b-48f9-9b7c-3539b7cbd69f', '嶺南送使二首 二', '嶺南送使二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["萬里投荒裔，來時不見親。","一朝成白首，看取報家人。"]', '["万里投荒裔，来时不见親。","一朝成白首，看取報家人。"]', '诗', 'shi', '', NULL, '嶺南送使二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8a3ef4-3362-4393-be41-9eb55e920b75', '傷妓人董氏四首 一', '傷妓人董氏四首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["董氏嬌嬈性，多爲窈窕名。","人隨秋月落，韻入擣衣聲。"]', '["董氏嬌嬈性，多爲窈窕名。","人隨秋月落，韻入擣衣声。"]', '诗', 'shi', '', NULL, '傷妓人董氏四首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93363b6c-616d-4948-b066-ddfdffafebb7', '傷妓人董氏四首 二', '傷妓人董氏四首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["粉蘂粘妝簏，金花竭翠條。","夜臺無戲伴，魂影向誰嬌。"]', '["粉蘂粘妝簏，金花竭翠條。","夜台無戲伴，魂影向誰嬌。"]', '诗', 'shi', '', NULL, '傷妓人董氏四首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c2287d-651f-404b-a250-4fc0e81752d5', '傷妓人董氏四首 三', '傷妓人董氏四首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["舊亭紅粉閣，宿處白雲關。","春日雙飛去，秋風獨不還。"]', '["旧亭紅粉閣，宿处白云关。","春日雙飞去，秋风独不還。"]', '诗', 'shi', '', NULL, '傷妓人董氏四首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9033c0f-261b-4846-b7e1-888236217900', '傷妓人董氏四首 四', '傷妓人董氏四首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["舞席沾殘粉，歌梁委舊塵。","獨傷窗裏月，不見帳中人。"]', '["舞席沾殘粉，歌梁委旧塵。","独傷窗裏月，不见帳中人。"]', '诗', 'shi', '', NULL, '傷妓人董氏四首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d404d2b5-2912-4a07-b5c3-18dad54c2c5b', '三月閨怨', '三月閨怨', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["三月時將盡，空房妾獨居。","蛾眉愁自結，鬢髪沒情梳。"]', '["三月时將尽，空房妾独居。","蛾眉愁自結，鬢髪沒情梳。"]', '诗', 'shi', '', NULL, '三月閨怨 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab916ad3-0429-4762-8124-61f7b09dc34d', '破陳樂詞二首 一', '破陳乐词二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["漢兵出頓金微，照日光明鐵衣。","百里火旛焰焰，千行雲騎霏霏。","蹙踏遼河自竭，鼓噪燕山可飛。","正屬四方朝賀，端知萬舞皇威。"]', '["漢兵出頓金微，照日光明鐵衣。","百里火旛焰焰，千行云騎霏霏。","蹙踏遼河自竭，鼓噪燕山可飞。","正屬四方朝賀，端知万舞皇威。"]', '诗', 'shi', '', NULL, '破陳樂詞二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81d9630-4b23-4d3f-a578-56887e0059fb', '破陳樂詞二首 二', '破陳乐词二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["少年膽氣凌雲，共許驍雄出羣。","匹馬城西挑戰，單刀薊北從軍。","一鼓鮮卑送款，五餌單于解紛。","誓欲成名報國，羞將開閤論勳。"]', '["少年膽氣凌云，共許驍雄出羣。","匹马城西挑戰，單刀薊北從軍。","一鼓鲜卑送款，五餌單于解紛。","誓欲成名報国，羞將开閤論勳。"]', '诗', 'shi', '', NULL, '破陳樂詞二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abfdc954-18b9-48f4-a173-a0f2709fd5fe', '舞馬詞六首 一', '舞马词六首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["萬玉朝宗鳳扆，千金率領龍媒。","眄鼓凝驕躞蹀，聽歌弄影徘徊。"]', '["万玉朝宗鳳扆，千金率領龙媒。","眄鼓凝驕躞蹀，听歌弄影徘徊。"]', '诗', 'shi', '', NULL, '舞馬詞六首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626219e4-cb9f-4c7f-8024-e023efa007c5', '舞馬詞六首 二', '舞马词六首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天鹿遙徵衞叔，日龍上借羲和。","將共兩驂爭舞，來隨八駿齊歌。"]', '["天鹿遙徵衞叔，日龙上借羲和。","將共兩驂爭舞，来隨八駿齊歌。"]', '诗', 'shi', '', NULL, '舞馬詞六首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ac7b6b-af04-4966-a1cc-91933788e526', '舞馬詞六首 三', '舞马词六首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["綵旄八佾成行，時龍五色因方。","屈膝銜杯赴節，傾心獻壽無疆。"]', '["綵旄八佾成行，时龙五色因方。","屈膝銜杯赴節，傾心獻壽無疆。"]', '诗', 'shi', '', NULL, '舞馬詞六首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35226c69-1cdd-4f8a-a7f7-6b77702b2a1a', '舞馬詞六首 四', '舞马词六首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝皁龍駒沛艾，星蘭驥子權奇。","騰倚驤洋應節，繁驕接迹不移。"]', '["帝皁龙駒沛艾，星蘭驥子權奇。","腾倚驤洋應節，繁驕接迹不移。"]', '诗', 'shi', '', NULL, '舞馬詞六首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1ab8c1-d16f-41a8-a519-31bda2d014a4', '舞馬詞六首 五', '舞马词六首 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["二聖先天合德，羣靈率土可封。","擊石驂驔紫燕，摐金顧步蒼龍。"]', '["二聖先天合德，羣靈率土可封。","擊石驂驔紫燕，摐金顧步蒼龙。"]', '诗', 'shi', '', NULL, '舞馬詞六首 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca663822-6301-41b9-a95b-b8b43983194d', '舞馬詞六首 六', '舞马词六首 六', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖君出震應籙，神馬浮河獻圖。","足踏天庭鼓舞，心將帝樂躊躕。"]', '["聖君出震應籙，神马浮河獻圖。","足踏天庭鼓舞，心將帝乐躊躕。"]', '诗', 'shi', '', NULL, '舞馬詞六首 六 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d38ed24-9e7c-46ea-916b-b8b4b3f4fb94', '奉和三日祓禊渭濱應制', '奉和三日祓禊渭濱應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["青郊上巳豔陽年，紫禁皇遊祓渭川。","幸得歡娛承湛露，心同草樹樂春天。"]', '["青郊上巳豔陽年，紫禁皇游祓渭川。","幸得歡娛承湛露，心同草樹乐春天。"]', '诗', 'shi', '', NULL, '奉和三日祓禊渭濱應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('254582ef-ba23-496d-817b-dcf8c42ddcd5', '桃花園馬上應制', '桃花园马上應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["林間豔色驕天馬，苑裏穠華伴麗人。","願逐南風飛帝席，年年含笑舞青春。"]', '["林间豔色驕天马，苑裏穠华伴丽人。","願逐南风飞帝席，年年含笑舞青春。"]', '诗', 'shi', '', NULL, '桃花園馬上應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7afb1b97-846c-4398-8049-a908a2476656', '奉和聖製幸韋嗣立山莊應制', '奉和聖製幸韋嗣立山莊應制', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["西京上相出扶陽，東郊別業好池塘。","自非仁智符天賞，安能日月共回光。"]', '["西京上相出扶陽，东郊別業好池塘。","自非仁智符天賞，安能日月共回光。"]', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立山莊應制 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25836f25-4af5-4009-93e4-f48be67950c8', '奉和聖製同玉真公主遊大哥山池題石壁', '奉和聖製同玉真公主游大哥山池題石壁', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["池如明鏡月華開，山學香爐雲氣來。","神藻飛爲鶺鴒賦，仙聲颺出鳳皇臺。"]', '["池如明镜月华开，山学香爐云氣来。","神藻飞爲鶺鴒賦，仙声颺出鳳皇台。"]', '诗', 'shi', '', NULL, '奉和聖製同玉真公主遊大哥山池題石壁 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c65835-25f2-49bc-87ae-5372346c2016', '十五日夜御前口號踏歌詞二首 一', '十五日夜御前口號踏歌词二首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["花蕚樓前雨露新，長安城裏太平人。","龍銜火樹千重焰，雞踏蓮花萬歲春。"]', '["花蕚楼前雨露新，长安城裏太平人。","龙銜火樹千重焰，雞踏蓮花万歲春。"]', '诗', 'shi', '', NULL, '十五日夜御前口號踏歌詞二首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f128d34-a677-48f2-a6f0-24ce76c3b3b1', '十五日夜御前口號踏歌詞二首 二', '十五日夜御前口號踏歌词二首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝宮三五戲春臺，行雨流風莫妬來。","西域燈輪千影合，東華金闕萬重開。"]', '["帝宮三五戲春台，行雨流风莫妬来。","西域灯輪千影合，东华金闕万重开。"]', '诗', 'shi', '', NULL, '十五日夜御前口號踏歌詞二首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ca44f5-898b-451f-910d-8b49eec10403', '蘇摩遮五首 一', '蘇摩遮五首 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["摩遮本出海西胡，琉璃寶服紫髯鬍。","聞道皇恩遍宇宙，來將歌舞助歡娛。"]', '["摩遮本出海西胡，琉璃寶服紫髯鬍。","闻道皇恩遍宇宙，来將歌舞助歡娛。"]', '诗', 'shi', '', NULL, '蘇摩遮五首 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb81343-e10f-4150-afaf-0864a89ff97b', '蘇摩遮五首 二', '蘇摩遮五首 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["繡裝帕額寶花冠，夷歌騎舞借人看。","自能激水成陰氣，不慮今年寒不寒。"]', '["繡裝帕額寶花冠，夷歌騎舞借人看。","自能激水成陰氣，不慮今年寒不寒。"]', '诗', 'shi', '', NULL, '蘇摩遮五首 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4d335a-3221-48e1-9141-f190de48cc29', '蘇摩遮五首 三', '蘇摩遮五首 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["臘月凝陰積帝臺，豪歌急鼓送寒來。","油囊取得天河水，將添上壽萬年杯。"]', '["臘月凝陰積帝台，豪歌急鼓送寒来。","油囊取得天河水，將添上壽万年杯。"]', '诗', 'shi', '', NULL, '蘇摩遮五首 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67b9ca0-1db4-446e-ad63-5d8b66b64087', '蘇摩遮五首 四', '蘇摩遮五首 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寒氣宜人最可憐，故將寒水散庭前。","惟願聖君無限壽，長取新年續舊年。"]', '["寒氣宜人最可怜，故將寒水散庭前。","惟願聖君無限壽，长取新年續旧年。"]', '诗', 'shi', '', NULL, '蘇摩遮五首 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b1c7b3-37eb-4adb-8d67-80214c5eecaf', '蘇摩遮五首 五', '蘇摩遮五首 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["昭成皇后帝家親，榮樂諸人不比倫。","往日霜前花委地，今年雪後樹逢春。"]', '["昭成皇后帝家親，榮乐諸人不比倫。","往日霜前花委地，今年雪後樹逢春。"]', '诗', 'shi', '', NULL, '蘇摩遮五首 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8d87e1-66d8-42ec-96d0-2bf8c8977178', '三月三日定昆池奉和蕭令得潭字韻', '三月三日定昆池奉和蕭令得潭字韻', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["暮春三月日重三，春水桃花滿禊潭。","廣樂逶迤天上下，仙舟搖衍鏡中酣。"]', '["暮春三月日重三，春水桃花满禊潭。","廣乐逶迤天上下，仙舟搖衍镜中酣。"]', '诗', 'shi', '', NULL, '三月三日定昆池奉和蕭令得潭字韻 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d66bbafe-3ce1-4eb0-a641-a43200c68809', '和尹從事懋泛洞庭', '和尹從事懋泛洞庭', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["平湖一望上連天，林景千尋下洞泉。","忽驚水上光華滿，疑是乘舟到日邊。"]', '["平湖一望上連天，林景千尋下洞泉。","忽驚水上光华满，疑是乘舟到日邊。"]', '诗', 'shi', '', NULL, '和尹從事懋泛洞庭 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81528b6-c58c-4e04-a337-a714fdd8cf94', '送梁六自洞庭山作', '送梁六自洞庭山作', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["巴陵一望洞庭秋，日見孤峰水上浮。","聞道神仙不可接，心隨湖水共悠悠。"]', '["巴陵一望洞庭秋，日见孤峰水上浮。","闻道神仙不可接，心隨湖水共悠悠。"]', '诗', 'shi', '', NULL, '送梁六自洞庭山作 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f09aa13a-9059-4e7d-831d-3c313ab44069', '同趙侍御望歸舟', '同趙侍御望归舟', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["山庭迥迥面長川，江樹重重極遠煙。","形影相追高翥鳥，心腸倂斷北風船。"]', '["山庭迥迥面长川，江樹重重極远煙。","形影相追高翥鸟，心腸倂斷北风船。"]', '诗', 'shi', '', NULL, '同趙侍御望歸舟 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c35271cf-b6d2-4618-85fb-085966fdab8d', '襄陽路逢寒食', '襄陽路逢寒食', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["去年寒食洞庭波，今年寒食襄陽路。","不辭著處尋山水，秪畏還家落春暮。"]', '["去年寒食洞庭波，今年寒食襄陽路。","不辞著处尋山水，秪畏還家落春暮。"]', '诗', 'shi', '', NULL, '襄陽路逢寒食 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f6dc36a-219d-4c16-909c-e27d6af78407', '詠方圓動靜示李泌', '詠方圓动静示李泌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["方如棋局，圓如棋子。","動如棋生，靜如棋死。"]', '["方如棋局，圓如棋子。","动如棋生，静如棋死。"]', '诗', 'shi', '', NULL, '詠方圓動靜示李泌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d05891a1-7d4b-4589-997f-54624d59456d', '和尹懋登南樓', '和尹懋登南楼', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["客來已兩春，更瞻韶光早。","花鳥既環合，江山復駢抱。","樓形寫北潭，堞勢凌青島。","白雲謝歸鴈，馳懷洛陽道。"]', '["客来已兩春，更瞻韶光早。","花鸟既环合，江山复駢抱。","楼形寫北潭，堞勢凌青島。","白云謝归鴈，驰懷洛陽道。"]', '诗', 'shi', '', NULL, '和尹懋登南樓 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183a10e7-fb03-47fc-9c8b-6353795dbdd1', '江上逢春', '江上逢春', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["離憂耿未和，春慮忽蹉跎。","擇木猿知去，尋泥燕獨過。","驚花飜霽日，垂柳拂煙波。","激意屢怡賞，無如鄉念何。"]', '["離憂耿未和，春慮忽蹉跎。","擇木猿知去，尋泥燕独過。","驚花飜霽日，垂柳拂煙波。","激意屢怡賞，無如乡念何。"]', '诗', 'shi', '', NULL, '江上逢春 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27eea95-87c4-4875-bc83-ab64f9766158', '九日巴丘登高', '九日巴丘登高', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["客心驚暮序，賓鴈下滄洲。","共賞重陽節，言尋戲馬遊。","湖風扶戍柳，江雨暗山樓。","且酌東籬酒，聊祛南國憂。"]', '["客心驚暮序，賓鴈下滄洲。","共賞重陽節，言尋戲马游。","湖风扶戍柳，江雨暗山楼。","且酌东籬酒，聊祛南国憂。"]', '诗', 'shi', '', NULL, '九日巴丘登高 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68353013-d25d-4a71-afd9-d0e5d88e5e1c', '和尹懋秋夜遊㴩湖二首 一', '和尹懋秋夜游㴩湖二首 一', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["遠水沈西日，寒沙聚夜鷗。","平湖乘月滿，飛棹接星流。","黃葉鳴淒吹，蒼葭掃暗洲。","願移滄浦賞，歸待潁川遊。"]', '["远水沈西日，寒沙聚夜鷗。","平湖乘月满，飞棹接星流。","黄葉鳴淒吹，蒼葭掃暗洲。","願移滄浦賞，归待潁川游。"]', '诗', 'shi', '', NULL, '和尹懋秋夜遊㴩湖二首 一 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7f64dc-3b06-46d2-8616-18435b5e44c9', '和尹懋秋夜遊㴩湖二首 二', '和尹懋秋夜游㴩湖二首 二', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["灣潭幽意深，杳靄涌寒岑。","石痕秋水落，嵐氣夕陽沈。","澄徹天爲底，淵玄月作心。","青溪非大隱，歸弄白雲潯。"]', '["灣潭幽意深，杳靄涌寒岑。","石痕秋水落，嵐氣夕陽沈。","澄徹天爲底，淵玄月作心。","青溪非大隐，归弄白云潯。"]', '诗', 'shi', '', NULL, '和尹懋秋夜遊㴩湖二首 二 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491c8a76-3c01-4b0b-9184-a2b95f1fb7de', '岳陽晚景', '岳陽晚景', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["晚景寒鵶集，秋風旅鴈歸。","水光浮日出，霞彩暎江飛。","洲白蘆花吐，園紅柿葉稀。","長沙卑溼地，九月未成衣。"]', '["晚景寒鵶集，秋风旅鴈归。","水光浮日出，霞彩暎江飞。","洲白蘆花吐，园紅柿葉稀。","长沙卑溼地，九月未成衣。"]', '诗', 'shi', '', NULL, '岳陽晚景 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04f138b-14ce-4b40-9d78-ef385648a345', '流合浦嶺外作', '流合浦嶺外作', 'af2079dd-061f-4db3-b3fe-da0bd86505cb', '唐', '["瘴江西去火爲山，炎徼南窮鬼作關。","從此更投人境外，生涯應在有無間。"]', '["瘴江西去火爲山，炎徼南窮鬼作关。","從此更投人境外，生涯應在有無间。"]', '诗', 'shi', '', NULL, '流合浦嶺外作 張均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491b140f-eff7-4107-892e-b8f40570cecd', '奉和岳州山城', '奉和岳州山城', '81d65a2b-62c5-4bfe-8715-f10754403f3b', '唐', '["郡館臨清賞，開扃坐白雲。","訟虛棠戶曙，觀靜竹簷曛。","懸榻迎賓下，趨庭學禮聞。","風傳琴上意，遙向日華紛。"]', '["郡館臨清賞，开扃坐白云。","訟虛棠戶曙，观静竹簷曛。","懸榻迎賓下，趨庭学禮闻。","风傳琴上意，遙向日华紛。"]', '诗', 'shi', '', NULL, '奉和岳州山城 張垍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d4384e-fcc6-4588-b532-52566c856488', '偶遊龍門北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚', '偶游龙门北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["幽谷杜陵邊，風煙別幾年。","偶來伊水曲，溪嶂覺依然。","傍浦憐芳樹，尋崖愛綠泉。","嶺雲隨馬足，山鳥向人前。","地合心俱靜，言因理自玄。","短才叨重寄，尸祿愧妨賢。","每挹挂冠侶，思從初服旋。","稻粱仍欲報，歲月坐空捐。","助岳無纖塊，輸溟謝末涓。","還悟北轅失，方求南澗田。"]', '["幽谷杜陵邊，风煙別幾年。","偶来伊水曲，溪嶂覺依然。","傍浦怜芳樹，尋崖愛綠泉。","嶺云隨马足，山鸟向人前。","地合心俱静，言因理自玄。","短才叨重寄，尸祿愧妨賢。","每挹挂冠侶，思從初服旋。","稻粱仍欲報，歲月坐空捐。","助岳無纖塊，輸溟謝末涓。","還悟北轅失，方求南澗田。"]', '诗', 'shi', '', NULL, '偶遊龍門北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d4eee0-1214-4964-a126-490d1fb54268', '奉和九日幸臨渭亭登高應制得深字', '奉和九日幸臨渭亭登高應制得深字', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["層觀遠沈沈，鸞旗九日臨。","帷宮壓水岸，步輦入煙岑。","枝上萸新採，樽中菊始斟。","願陪歡樂事，長與歲時深。"]', '["層观远沈沈，鸾旗九日臨。","帷宮壓水岸，步輦入煙岑。","枝上萸新採，樽中菊始斟。","願陪歡乐事，长與歲时深。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得深字 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('667e8b3a-fdbc-45c6-ab3e-04dd6f31bfe4', '奉和張岳州王潭州別詩二首 一', '奉和張岳州王潭州別诗二首 一', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["茂先王佐才，作牧楚江隈。","登樓正欲賦，復遇仲宣來。","黃鵠飛將遠，雕龍文爲開。","寧知昔聯事，聽曲有餘哀。"]', '["茂先王佐才，作牧楚江隈。","登楼正欲賦，复遇仲宣来。","黄鵠飞將远，雕龙文爲开。","寧知昔聯事，听曲有餘哀。"]', '诗', 'shi', '', NULL, '奉和張岳州王潭州別詩二首 一 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd40c3f-9460-4f6a-99bb-45809579fb32', '奉和張岳州王潭州別詩二首 二', '奉和張岳州王潭州別诗二首 二', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["昔時陪二賢，纓冕會神仙。","一去馳江海，相逢共播遷。","無因千里駕，忽覩四愁篇。","覽諷歡何已，歡終徒愴然。"]', '["昔时陪二賢，纓冕會神仙。","一去驰江海，相逢共播遷。","無因千里駕，忽覩四愁篇。","覽諷歡何已，歡終徒愴然。"]', '诗', 'shi', '', NULL, '奉和張岳州王潭州別詩二首 二 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef539abc-b6bf-49fc-a49a-be7df5eb902e', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["主第巖扃架鵲橋，天門閶闔降鸞鑣。","歷亂旌旗轉雲樹，參差臺榭入煙霄。","林間花雜平陽舞，谷裏鶯和弄玉簫。","已陪沁水追歡日，行奉茅山訪道朝。"]', '["主第巖扃架鵲橋，天门閶闔降鸾鑣。","歷亂旌旗轉云樹，參差台榭入煙霄。","林间花杂平陽舞，谷裏鶯和弄玉簫。","已陪沁水追歡日，行奉茅山訪道朝。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8461b4b5-f9b8-416f-b654-04824aa9a0e4', '自湯還都經龍門北溪贈張左丞崔禮部崔光祿', '自湯還都經龙门北溪贈張左丞崔禮部崔光祿', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["栖閑有愚谷，好事枉朝軒。","樹接前驅擁，巖傳後騎喧。","褰簾出野院，植杖候柴門。","既拂林下席，仍攜池上樽。","深期契幽賞，實謂展歡言。","末眷誠未易，佳遊時更敦。","俄看嘯儔侶，各已共飛鶱。","延睇盡朝日，長懷通夜魂。","空聞岸竹動，徒見浦花繁。","多愧春鶯曲，相求意獨存。"]', '["栖闲有愚谷，好事枉朝軒。","樹接前驱擁，巖傳後騎喧。","褰簾出野院，植杖候柴门。","既拂林下席，仍携池上樽。","深期契幽賞，實謂展歡言。","末眷誠未易，佳游时更敦。","俄看嘯儔侶，各已共飞鶱。","延睇尽朝日，长懷通夜魂。","空闻岸竹动，徒见浦花繁。","多愧春鶯曲，相求意独存。"]', '诗', 'shi', '', NULL, '自湯還都經龍門北溪贈張左丞崔禮部崔光祿 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ccb8b1-eba5-4084-ae01-bf5aa91a077e', '酬崔光祿冬日述懷贈答', '酬崔光祿冬日述懷贈答', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["亭伯負高名，羽儀稱上京。","魏珠能燭乘，秦璧許連城。","六月飛將遠，三冬學已精。","洛陽推賈誼，江夏貴黃瓊。","推演中都術，旋參河尹聲。","累遷登御府，移拜踐名卿。","庭聚歌鍾麗，門羅棨戟榮。","鸚杯飛廣席，獸火列前楹。","散誕林園意，殷勤敬愛情。","無容抱衰疾，良宴每招迎。","契得心逾重，言忘道益真。","相勗忠義節，共談詞賦英。","雕蟲曾靡棄，白鳳已先鳴。","光接神愈駭，音來味不成。","短歌甘自思，鴻藻彌難清。","東里方希潤，西河敢竊明。","厚誣空見迫，喪德豈無誠。","端守宮闈地，寒煙朝暮平。","顧才無術淺，懷器識憂盈。","月下對雲闕，風前聞夜更。","昌年雖共偶，歡會此難幷。","爲憐漳浦曲，沈痼有劉楨。"]', '["亭伯負高名，羽儀稱上京。","魏珠能燭乘，秦璧許連城。","六月飞將远，三冬学已精。","洛陽推賈誼，江夏貴黄瓊。","推演中都術，旋參河尹声。","累遷登御府，移拜踐名卿。","庭聚歌鍾丽，门羅棨戟榮。","鸚杯飞廣席，獸火列前楹。","散誕林园意，殷勤敬愛情。","無容抱衰疾，良宴每招迎。","契得心逾重，言忘道益真。","相勗忠義節，共談词賦英。","雕蟲曾靡棄，白鳳已先鳴。","光接神愈駭，音来味不成。","短歌甘自思，鴻藻彌难清。","东里方希潤，西河敢竊明。","厚誣空见迫，喪德豈無誠。","端守宮闈地，寒煙朝暮平。","顧才無術淺，懷器識憂盈。","月下对云闕，风前闻夜更。","昌年雖共偶，歡會此难幷。","爲怜漳浦曲，沈痼有劉楨。"]', '诗', 'shi', '', NULL, '酬崔光祿冬日述懷贈答 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d677ca21-32b3-44c8-8c78-bafc28276100', '上巳日祓禊渭濱應制', '上巳日祓禊渭濱應制', '41569311-3115-4709-85bc-9c3e48a9ab0e', '唐', '["乘春祓禊逐風光，扈蹕陪鑾渭渚傍。","還笑當時水濱老，衰年八十待文王。"]', '["乘春祓禊逐风光，扈蹕陪鑾渭渚傍。","還笑當时水濱老，衰年八十待文王。"]', '诗', 'shi', '', NULL, '上巳日祓禊渭濱應制 韋嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec3eb9f-1bb9-4494-b72e-998ee1bf70bf', '奉酬韋祭酒偶遊龍門北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚之作', '奉酬韋祭酒偶游龙门北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚之作', '731e9b49-ee20-4ff8-bd91-ec0de109c10a', '唐', '["有美朝爲貴，幽尋地自偏。","踐臨伊水汭，想望灞池邊。","是遇皆新賞，茲遊若舊年。","藤蘿隱路接，楊柳御溝聯。","道愜神情王，機忘俗理捐。","遂初誠已重，兼濟實爲賢。","跡是東山戀，心惟北闕懸。","顧慙經拾紫，多謝賦思玄。","未躧中林步，空承麗藻傳。","陽春和已寡，扣寂竟徒然。"]', '["有美朝爲貴，幽尋地自偏。","踐臨伊水汭，想望灞池邊。","是遇皆新賞，茲游若旧年。","藤蘿隐路接，楊柳御溝聯。","道愜神情王，機忘俗理捐。","遂初誠已重，兼濟實爲賢。","跡是东山戀，心惟北闕懸。","顧慙經拾紫，多謝賦思玄。","未躧中林步，空承丽藻傳。","陽春和已寡，扣寂竟徒然。"]', '诗', 'shi', '', NULL, '奉酬韋祭酒偶遊龍門北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚之作 魏奉古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee8d5c4-8293-4940-8222-1576d891ed4d', '奉酬韋祭酒偶遊龍門北溪忽懷驪山別業因以言志示弟淑並呈諸大僚之作', '奉酬韋祭酒偶游龙门北溪忽懷驪山別業因以言志示弟淑並呈諸大僚之作', '4d2cd608-fcb9-4c2d-896e-89a94b1c657e', '唐', '["夙齡秉微尚，中年忽有鄰。","以茲山水癖，遂得狎通人。","迨我咸京道，聞君別業新。","巖前窺石鏡，河畔踏芳茵。","既憐伊浦綠，復憶灞池春。","連詞謝家子，同歡冀野賓。","趣閑魚共樂，情洽鳥來馴。","詎念昔遊者，祇命獨留秦。","蕭條穎陽戀，沖漠漢陰真。","無由陪勝躅，空此翫書筠。"]', '["夙齡秉微尚，中年忽有鄰。","以茲山水癖，遂得狎通人。","迨我咸京道，闻君別業新。","巖前窺石镜，河畔踏芳茵。","既怜伊浦綠，复憶灞池春。","連词謝家子，同歡冀野賓。","趣闲鱼共乐，情洽鸟来馴。","詎念昔游者，祇命独留秦。","蕭條穎陽戀，沖漠漢陰真。","無由陪勝躅，空此翫书筠。"]', '诗', 'shi', '', NULL, '奉酬韋祭酒偶遊龍門北溪忽懷驪山別業因以言志示弟淑並呈諸大僚之作 崔日知 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31ab924-a0c9-410d-9a90-7b36deef7918', '冬日述懷奉呈韋祭酒張左丞蘭臺名賢', '冬日述懷奉呈韋祭酒張左丞蘭台名賢', '4d2cd608-fcb9-4c2d-896e-89a94b1c657e', '唐', '["弱齡好經籍，披卷即怡然。","覃精四十載，馳騁數千言。","孔壁採遺篆，周韋考絕編。","袁公論劒術，孫子敘兵篇。","魯史君臣道，姬書日月懸。","從師改炎燠，負笈遍山川。","上異西河夏，中非北海玄。","光榮拾青紫，名價接通賢。","既重萬鍾樂，寧思二頃田。","長戟同分虎，高冠亞附蟬。","晚懷重虛曠，養志息雕鐫。","登高慚思拙，匠物謝情妍。","不慕張平子，寧希王仲宣。","誰謂登龍日，翻成刻鵠年。","循循勞善誘，軋軋思微牽。","琢磨才既竭，鑽仰德彌堅。","朽木誠爲諭，捫心徒自憐。","終期吞鳥夢，振翼上雲煙。","賦成先擲地，詞高直掞天。","更執摳衣禮，仍開函丈筵。","霧披槐市藹，水靜璧池圓。","願逐從風葉，飛舞翰林前。"]', '["弱齡好經籍，披卷即怡然。","覃精四十載，驰騁數千言。","孔壁採遺篆，周韋考絕編。","袁公論劒術，孫子敘兵篇。","魯史君臣道，姬书日月懸。","從師改炎燠，負笈遍山川。","上異西河夏，中非北海玄。","光榮拾青紫，名價接通賢。","既重万鍾乐，寧思二頃田。","长戟同分虎，高冠亞附蟬。","晚懷重虛曠，養志息雕鐫。","登高慚思拙，匠物謝情妍。","不慕張平子，寧希王仲宣。","誰謂登龙日，翻成刻鵠年。","循循勞善誘，軋軋思微牽。","琢磨才既竭，鑽仰德彌堅。","朽木誠爲諭，捫心徒自怜。","終期吞鸟梦，振翼上云煙。","賦成先擲地，词高直掞天。","更執摳衣禮，仍开函丈筵。","霧披槐市藹，水静璧池圓。","願逐從风葉，飞舞翰林前。"]', '诗', 'shi', '', NULL, '冬日述懷奉呈韋祭酒張左丞蘭臺名賢 崔日知 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81232f93-42d2-47be-a714-1cfac8a255f0', '奉酬韋嗣立祭酒偶遊龍門北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚之作', '奉酬韋嗣立祭酒偶游龙门北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚之作', '69486548-12a1-434b-926d-e5ea9b2bec01', '唐', '["關塞臨伊水，驪山枕灞川。","俱臨隱路側，同在帝城邊。","謝公兼出處，攜妓翫林泉。","鳴騶噴梅雪，飛蓋曳松煙。","聞琴幽谷裏，看[弈]古巖前。","落日低幃帳，歸雲繞管弦。","叨榮慚北闕，微尚愛東田。","寂寞灰心盡，蕭條塵事捐。","朝思登嶃絕，夜夢弄潺湲。","宿懷南澗意，況覩北谿篇。"]', '["关塞臨伊水，驪山枕灞川。","俱臨隐路側，同在帝城邊。","謝公兼出处，携妓翫林泉。","鳴騶噴梅雪，飞蓋曳松煙。","闻琴幽谷裏，看[弈]古巖前。","落日低幃帳，归云繞管弦。","叨榮慚北闕，微尚愛东田。","寂寞灰心尽，蕭條塵事捐。","朝思登嶃絕，夜梦弄潺湲。","宿懷南澗意，況覩北谿篇。"]', '诗', 'shi', '', NULL, '奉酬韋嗣立祭酒偶遊龍門北溪忽懷驪山別業因以言志示弟淑奉呈諸大僚之作 崔泰之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaeee0c3-dc64-4c33-9013-4b5d5823491c', '同光祿弟冬日述懷', '同光祿弟冬日述懷', '69486548-12a1-434b-926d-e5ea9b2bec01', '唐', '["吾族白眉良，才華動洛陽。","觀光初入仕，應宿始爲郎。","飛螢翫書籍，白鳳吐文章。","海卿逾往雅，河尹冠前張。","擇材綏鄢郢，殊化被江湘。","高樓臨廣陌，甲第敞通莊。","列館邙山下，疏亭洛水傍。","昌年賞豐陌，暇日悅林塘。","衣冠皆秀彥，羅綺盡名倡。","隔岸聞歌度，臨池見舞行。","門庭寒變色，棨戟日生光。","窮陰方靉靆，殺氣正蒼茫。","感時興盛作，晚歲共多傷。","積德韋丞相，通神張子房。","吟草徧簪紱，逸韻合宮商。","功名守留省，濫迹在文昌。","家園遙可見，臺寺近相望。","無庸乘侍謁，有暇共翱翔。","棣華依雁序，竹葉拂鸞觴。","水坐憐秋月，山行弄晚芳。","恩華慙服冕，友愛勗垂堂。","無由報天德，相顧詠時康。"]', '["吾族白眉良，才华动洛陽。","观光初入仕，應宿始爲郎。","飞螢翫书籍，白鳳吐文章。","海卿逾往雅，河尹冠前張。","擇材綏鄢郢，殊化被江湘。","高楼臨廣陌，甲第敞通莊。","列館邙山下，疏亭洛水傍。","昌年賞豐陌，暇日悅林塘。","衣冠皆秀彥，羅綺尽名倡。","隔岸闻歌度，臨池见舞行。","门庭寒变色，棨戟日生光。","窮陰方靉靆，殺氣正蒼茫。","感时兴盛作，晚歲共多傷。","積德韋丞相，通神張子房。","吟草徧簪紱，逸韻合宮商。","功名守留省，濫迹在文昌。","家园遙可见，台寺近相望。","無庸乘侍謁，有暇共翱翔。","棣华依雁序，竹葉拂鸾觴。","水坐怜秋月，山行弄晚芳。","恩华慙服冕，友愛勗垂堂。","無由報天德，相顧詠时康。"]', '诗', 'shi', '', NULL, '同光祿弟冬日述懷 崔泰之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a4bc98-2179-44ff-9655-2a6155043226', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', '69486548-12a1-434b-926d-e5ea9b2bec01', '唐', '["南庭胡運盡，北斗將星飛。","旗鼓臨沙漠，旌旄出洛畿。","關山遶玉塞，烽火映金微。","屢獻帷謀策，頻承廟勝威。","躞蹀臨河騎，逶迤度隴旂。","地脈平千古，天聲振九圍。","車馬生邊氣，戈鋋駐落暉。","夏近蓬猶轉，秋深草木腓。","餞送紆天什，恩榮賜御衣。","佇勒燕然頌，鳴騶計日歸。"]', '["南庭胡運尽，北斗將星飞。","旗鼓臨沙漠，旌旄出洛畿。","关山遶玉塞，烽火映金微。","屢獻帷謀策，頻承廟勝威。","躞蹀臨河騎，逶迤度隴旂。","地脈平千古，天声振九圍。","车马生邊氣，戈鋋駐落暉。","夏近蓬猶轉，秋深草木腓。","餞送紆天什，恩榮賜御衣。","佇勒燕然頌，鳴騶計日归。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 崔泰之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('517d08ab-c3fd-4d70-8a6b-7c0c52922a88', '春夜寓直鳳閣懷羣公', '春夜寓直鳳閣懷羣公', '8b82646e-3034-4796-b02e-db89010d2b39', '唐', '["拜門傳漏晚，寓直索居時。","昔重安仁賦，今稱伯玉詩。","鴛池滿不溢，雞樹久逾滋。","夙夜懷山甫，清風詠所思。"]', '["拜门傳漏晚，寓直索居时。","昔重安仁賦，今稱伯玉诗。","鴛池满不溢，雞樹久逾滋。","夙夜懷山甫，清风詠所思。"]', '诗', 'shi', '', NULL, '春夜寓直鳳閣懷羣公 魏知古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513e1820-323e-405a-a3d5-6db10b3403b4', '奉和春日途中喜雨應詔', '奉和春日途中喜雨應詔', '8b82646e-3034-4796-b02e-db89010d2b39', '唐', '["皇輿向洛城，時雨應天行。","麗日登巖送，陰雲出野迎。","濯枝林杏發，潤葉渚蒲生。","絲入綸言喜，花依錦字明。","微臣忝東觀，載筆佇西成。"]', '["皇輿向洛城，时雨應天行。","丽日登巖送，陰云出野迎。","濯枝林杏發，潤葉渚蒲生。","絲入綸言喜，花依錦字明。","微臣忝东观，載笔佇西成。"]', '诗', 'shi', '', NULL, '奉和春日途中喜雨應詔 魏知古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a704799c-a4ca-455d-b356-6c7a41cf53e3', '從獵渭川獻詩', '從獵渭川獻诗', '8b82646e-3034-4796-b02e-db89010d2b39', '唐', '["嘗聞夏太康，五弟訓禽荒。","我后來冬狩，三驅盛禮張。","順時鷹隼擊，講事武功揚。","奔走未及去，翾飛豈暇翔。","非熊從渭水，瑞翟想陳倉。","此欲誠難縱，茲遊不可常。","子雲陳羽獵，僖伯諫漁棠。","得失鑒齊楚，仁思念禹湯。","雍熙亮在宥，亭毒匪多傷。","辛甲今爲史，虞箴遂孔彰。"]', '["嘗闻夏太康，五弟訓禽荒。","我后来冬狩，三驱盛禮張。","順时鷹隼擊，講事武功揚。","奔走未及去，翾飞豈暇翔。","非熊從渭水，瑞翟想陳倉。","此欲誠难縱，茲游不可常。","子云陳羽獵，僖伯諫漁棠。","得失鑒齊楚，仁思念禹湯。","雍熙亮在宥，亭毒匪多傷。","辛甲今爲史，虞箴遂孔彰。"]', '诗', 'shi', '', NULL, '從獵渭川獻詩 魏知古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b5cbcd-8b87-46b2-b526-b4bdcfadb0ac', '玄元觀尋李先生不遇', '玄元观尋李先生不遇', '8b82646e-3034-4796-b02e-db89010d2b39', '唐', '["羽客今何在，空尋伊洛間。","忽聞歸苦縣，復想入函關。","未作千年別，猶應七日還。","神仙不可見，寂寞返蓬山。"]', '["羽客今何在，空尋伊洛间。","忽闻归苦縣，复想入函关。","未作千年別，猶應七日還。","神仙不可见，寂寞返蓬山。"]', '诗', 'shi', '', NULL, '玄元觀尋李先生不遇 魏知古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c0802f-6e2b-4b50-9374-52a8c14b78d6', '招諭有懷贈同行人', '招諭有懷贈同行人', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["遠遊冒艱阻，深入勞存諭。","春去辭國門，秋還在邊戍。","軒車行未返，節序催難駐。","陌上悲轉蓬，園中想芳樹。","蜀山自紛糾，岷水恆奔注。","臨泛多苦懷，登攀寡歡趣。","永夕飛淫雨，崇朝蒸毒霧。","不求綏嶺桃，寧美邛鄉蒟。","白浪行欲靜，驄馬何嘗驅。","願接軺斾塵，聯翩東北騖。"]', '["远游冒艱阻，深入勞存諭。","春去辞国门，秋還在邊戍。","軒车行未返，節序催难駐。","陌上悲轉蓬，园中想芳樹。","蜀山自紛糾，岷水恆奔注。","臨泛多苦懷，登攀寡歡趣。","永夕飞淫雨，崇朝蒸毒霧。","不求綏嶺桃，寧美邛乡蒟。","白浪行欲静，驄马何嘗驱。","願接軺斾塵，聯翩东北騖。"]', '诗', 'shi', '', NULL, '招諭有懷贈同行人 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af7cf29-11ca-43fa-8d90-ed954467f262', '春日侍宴芙蓉園應制', '春日侍宴芙蓉园應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["水殿臨丹籞，山樓繞翠微。","昔遊人託乘，今幸帝垂衣。","澗篠緣峰合，巖花逗浦飛。","朝來江曲地，無處不光輝。"]', '["水殿臨丹籞，山楼繞翠微。","昔游人託乘，今幸帝垂衣。","澗篠緣峰合，巖花逗浦飞。","朝来江曲地，無处不光輝。"]', '诗', 'shi', '', NULL, '春日侍宴芙蓉園應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e90b3aa8-8ac4-4de3-947c-10ff1c29ed28', '奉和登驪山高頂寓目應制', '奉和登驪山高頂寓目應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["崖巘萬尋懸，居高敞御筵。","行戈疑駐日，步輦若登天。","城闕霧中近，關河雲外連。","謬陪登岱駕，欣奉濟汾篇。"]', '["崖巘万尋懸，居高敞御筵。","行戈疑駐日，步輦若登天。","城闕霧中近，关河云外連。","謬陪登岱駕，欣奉濟汾篇。"]', '诗', 'shi', '', NULL, '奉和登驪山高頂寓目應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a2540b-7690-4b2b-9d18-0bbdbe31c0e7', '奉和七夕兩儀殿會宴應制', '奉和七夕兩儀殿會宴應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["桂宮明月夜，蘭殿起秋風。","雲漢彌年阻，星筵此夕同。","倏來疑有處，旋去已成空。","睿作鈞天響，魂飛在夢中。"]', '["桂宮明月夜，蘭殿起秋风。","云漢彌年阻，星筵此夕同。","倏来疑有处，旋去已成空。","睿作鈞天响，魂飞在梦中。"]', '诗', 'shi', '', NULL, '奉和七夕兩儀殿會宴應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b95c4772-cdc9-4d19-9bb7-ffdca2ca2fa3', '奉和春日遊苑喜雨應詔', '奉和春日游苑喜雨應詔', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["仙蹕九成臺，香筵萬壽杯。","一旬初降雨，二月早聞雷。","葉向朝霽密，花含宿潤開。","幸承天澤豫，無使日光催。"]', '["仙蹕九成台，香筵万壽杯。","一旬初降雨，二月早闻雷。","葉向朝霽密，花含宿潤开。","幸承天澤豫，無使日光催。"]', '诗', 'shi', '', NULL, '奉和春日遊苑喜雨應詔 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e3f44d-76dd-46cf-90e1-67c9872da25e', '奉和人日清暉閣宴羣臣遇雪應制', '奉和人日清暉閣宴羣臣遇雪應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["上日登樓賞，中天御輦飛。","後庭聯舞唱，前席仰恩輝。","睿作風雲起，農祥雨雪霏。","幸陪人勝節，長願奉垂衣。"]', '["上日登楼賞，中天御輦飞。","後庭聯舞唱，前席仰恩輝。","睿作风云起，農祥雨雪霏。","幸陪人勝節，长願奉垂衣。"]', '诗', 'shi', '', NULL, '奉和人日清暉閣宴羣臣遇雪應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d467ba-e879-49b1-a3c5-c2ef10ec33c0', '陪幸臨渭亭遇雪應制', '陪幸臨渭亭遇雪應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["青陽御紫微，白雲下彤闈。","浹壤流天霈，綿區灑帝輝。","水如銀度燭，雲似玉披衣。","爲得因風起，還來就日飛。"]', '["青陽御紫微，白云下彤闈。","浹壤流天霈，綿區灑帝輝。","水如銀度燭，云似玉披衣。","爲得因风起，還来就日飞。"]', '诗', 'shi', '', NULL, '陪幸臨渭亭遇雪應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6585d5-7508-4074-8f18-634d7a467edd', '奉和九日侍宴應制得濃字', '奉和九日侍宴應制得濃字', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["望幸紆千乘，登高自九重。","臺疑臨戲馬，殿似接疏龍。","捧篋萸香遍，稱觴菊氣濃。","更看仙鶴舞，來此慶時雍。"]', '["望幸紆千乘，登高自九重。","台疑臨戲马，殿似接疏龙。","捧篋萸香遍，稱觴菊氣濃。","更看仙鹤舞，来此慶时雍。"]', '诗', 'shi', '', NULL, '奉和九日侍宴應制得濃字 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27fe9d0b-b513-45d3-b84a-f438ba9dd879', '送沙門弘景道俊玄奘還荆州應制', '送沙门弘景道俊玄奘還荆州應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["初日承歸旨，秋風起贈言。","漢珠留道味，江璧返真源。","地出南關遠，天迴北斗尊。","寧知一柱觀，却啓四禪門。"]', '["初日承归旨，秋风起贈言。","漢珠留道味，江璧返真源。","地出南关远，天迴北斗尊。","寧知一柱观，却啓四禪门。"]', '诗', 'shi', '', NULL, '送沙門弘景道俊玄奘還荆州應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5618a138-258d-4ebf-8380-5e1bbd4e932b', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["湧塔臨玄地，高層瞰紫微。","鳴鑾陪帝出，攀橑翊天飛。","慶洽重陽壽，文含列象輝。","小臣叨載筆，欣此頌巍巍。"]', '["湧塔臨玄地，高層瞰紫微。","鳴鑾陪帝出，攀橑翊天飞。","慶洽重陽壽，文含列象輝。","小臣叨載笔，欣此頌巍巍。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b318f9fc-a9b8-438b-9c2a-34c042eb24fc', '閏九月九日幸總持寺登浮圖應制', '閏九月九日幸總持寺登浮圖應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["清蹕幸禪樓，前驅歷御溝。","還疑九日豫，更想六年遊。","聖藻輝纓絡，仙花綴冕旒。","所欣延億載，寧祗慶重秋。"]', '["清蹕幸禪楼，前驱歷御溝。","還疑九日豫，更想六年游。","聖藻輝纓絡，仙花綴冕旒。","所欣延億載，寧祗慶重秋。"]', '诗', 'shi', '', NULL, '閏九月九日幸總持寺登浮圖應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f65f3d6d-da62-453a-bdc1-497931bb8da0', '侍宴長寧公主東莊應制', '侍宴长寧公主东莊應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["紫禁乘宵動，青門訪水嬉。","貴遊鱣序集，仙女鳳樓期。","合宴簪紳滿，承恩雨露滋。","北辰還捧日，東館幸逢時。"]', '["紫禁乘宵动，青门訪水嬉。","貴游鱣序集，仙女鳳楼期。","合宴簪紳满，承恩雨露滋。","北辰還捧日，东館幸逢时。"]', '诗', 'shi', '', NULL, '侍宴長寧公主東莊應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffecb949-9b13-4aaa-9400-1e42b7782107', '幸白鹿觀應制', '幸白鹿观應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["制蹕乘驪阜，迴輿指鳳京。","南山四皓謁，西嶽兩童迎。","雲幄臨懸圃，霞杯薦赤城。","神明近茲地，何必往蓬瀛。"]', '["制蹕乘驪阜，迴輿指鳳京。","南山四皓謁，西嶽兩童迎。","云幄臨懸圃，霞杯薦赤城。","神明近茲地，何必往蓬瀛。"]', '诗', 'shi', '', NULL, '幸白鹿觀應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3540344f-4e27-4952-8464-5e4a5b9875c8', '次蘇州', '次蘇州', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["洛渚問吳潮，吳門想洛橋。","夕煙楊柳岸，春水木蘭橈。","城邑南樓近，星辰北斗遙。","無因生羽翼，輕舉托還飆。"]', '["洛渚问吳潮，吳门想洛橋。","夕煙楊柳岸，春水木蘭橈。","城邑南楼近，星辰北斗遙。","無因生羽翼，轻舉托還飆。"]', '诗', 'shi', '', NULL, '次蘇州 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59bd532-32fd-4f64-afd1-a3ad470fc2a7', '寄胡皓時在南中', '寄胡皓时在南中', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["徭役苦流滯，風波限泝洄。","江流通地骨，山道繞天台。","有鳥圖南去，無人見北來。","閉門滄海曲，雲霧待君開。"]', '["徭役苦流滯，风波限泝洄。","江流通地骨，山道繞天台。","有鸟圖南去，無人见北来。","閉门滄海曲，云霧待君开。"]', '诗', 'shi', '', NULL, '寄胡皓時在南中 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc497ec-2a0e-4ecf-8b26-f4ff4da2344d', '餞許州宋司馬赴任', '餞許州宋司马赴任', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["展驥旌時傑，談雞美代賢。","暫離仙掖務，追送近郊筵。","地慘金商節，人康璧假田。","從來昆友事，咸以佩刀傳。"]', '["展驥旌时傑，談雞美代賢。","暫離仙掖務，追送近郊筵。","地慘金商節，人康璧假田。","從来昆友事，咸以佩刀傳。"]', '诗', 'shi', '', NULL, '餞許州宋司馬赴任 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b41f31-8852-4bbc-b5b5-41ef9cfaf507', '餞唐州高使君赴任', '餞唐州高使君赴任', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["淮源之水清，可以濯君纓。","彼美稱才傑，親人佇政聲。","歲寒疇曩意，春晚別離情。","終歎臨岐遠，行看擁傳榮。"]', '["淮源之水清，可以濯君纓。","彼美稱才傑，親人佇政声。","歲寒疇曩意，春晚別離情。","終歎臨岐远，行看擁傳榮。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1357578-718a-485c-a9be-fb0223213615', '哭僕射鄂公楊再思', '哭僕射鄂公楊再思', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["端揆凝邦績，台階闡國猷。","方崇大廈棟，忽逝巨川舟。","白日銘安在，清風頌獨留。","死生恩命畢，零落掩山丘。"]', '["端揆凝邦績，台階闡国猷。","方崇大廈棟，忽逝巨川舟。","白日銘安在，清风頌独留。","死生恩命畢，零落掩山丘。"]', '诗', 'shi', '', NULL, '哭僕射鄂公楊再思 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27637fd6-64db-4794-a8c8-fb4a2a9e8d66', '故趙王屬贈黃門侍郎上官公挽詞', '故趙王屬贈黄门侍郎上官公挽词', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["暮歸泉壤隔，朝發城池戀。","漢畤結愁陰，秦陵下悲霰。","駸駸百駟馳，憫憫羣龍餞。","石馬徒自施，玉人終不見。"]', '["暮归泉壤隔，朝發城池戀。","漢畤結愁陰，秦陵下悲霰。","駸駸百駟驰，憫憫羣龙餞。","石马徒自施，玉人終不见。"]', '诗', 'shi', '', NULL, '故趙王屬贈黃門侍郎上官公挽詞 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a5969e0-ce97-44ac-b004-fb626e8b6a7e', '淮陽公主挽歌', '淮陽公主挽歌', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["玉顏生漢渚，湯沐榮天女。","金縷化邙塵，哀榮感路人。","鳳皇曾作伴，螻蟻忽爲親。","疇日成蹊處，穠華不復春。"]', '["玉顏生漢渚，湯沐榮天女。","金縷化邙塵，哀榮感路人。","鳳皇曾作伴，螻蟻忽爲親。","疇日成蹊处，穠华不复春。"]', '诗', 'shi', '', NULL, '淮陽公主挽歌 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079828a5-83da-4191-838c-a392b2f6053f', '故西臺侍郎上官公挽歌', '故西台侍郎上官公挽歌', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["宇內文儒重，朝端禮命優。","立言多啓沃，論道盛謀猷。","顧日琴安在，衝星劍不留。","徒懷東武襚，更掩北原丘。"]', '["宇內文儒重，朝端禮命優。","立言多啓沃，論道盛謀猷。","顧日琴安在，衝星劍不留。","徒懷东武襚，更掩北原丘。"]', '诗', 'shi', '', NULL, '故西臺侍郎上官公挽歌 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('563204d2-74ba-42a3-932d-24445639dc18', '高安公主挽歌二首 一', '高安公主挽歌二首 一', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["湯沐三千賦，樓臺十二重。","銀鑪稱貴幸，玉輦盛過逢。","嬪則留中饋，娥輝沒下舂。","平陽百歲後，歌舞爲誰容。"]', '["湯沐三千賦，楼台十二重。","銀鑪稱貴幸，玉輦盛過逢。","嬪則留中饋，娥輝沒下舂。","平陽百歲後，歌舞爲誰容。"]', '诗', 'shi', '', NULL, '高安公主挽歌二首 一 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f97a09-1c3e-4790-a553-5d89ede4531e', '高安公主挽歌二首 二', '高安公主挽歌二首 二', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["賓衞儼相依，橫門啓曙扉。","靈陰蟾兔缺，仙影鳳皇飛。","一水秋難渡，三泉夜不歸。","況臨青女節，瑤草更前哀。"]', '["賓衞儼相依，橫门啓曙扉。","靈陰蟾兔缺，仙影鳳皇飞。","一水秋难渡，三泉夜不归。","況臨青女節，瑤草更前哀。"]', '诗', 'shi', '', NULL, '高安公主挽歌二首 二 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17a3540-79d9-4a1f-8a45-7b0c81370181', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["平陽館外有仙家，沁水園中好物華。","地出東郊迴日御，城臨南斗度雲車。","風泉韻繞幽林竹，雨霰光搖雜樹花。","已慶時來千億壽，還言日暮九重賒。"]', '["平陽館外有仙家，沁水园中好物华。","地出东郊迴日御，城臨南斗度云车。","风泉韻繞幽林竹，雨霰光搖杂樹花。","已慶时来千億壽，還言日暮九重賒。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a228aae3-e5db-4a88-b8a4-06d6e705f610', '興慶池侍宴應制', '兴慶池侍宴應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["神池泛濫水盈科，仙蹕紆徐步輦過。","縱棹洄沿萍溜合，開軒眺賞麥風和。","潭魚在藻供遊詠，谷鳥含櫻入賦歌。","寄語乘槎溟海客，回頭來此問天河。"]', '["神池泛濫水盈科，仙蹕紆徐步輦過。","縱棹洄沿萍溜合，开軒眺賞麦风和。","潭鱼在藻供游詠，谷鸟含櫻入賦歌。","寄語乘槎溟海客，回头来此问天河。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1492d1df-92d6-4a28-8a46-829a41cf53e3', '侍宴安樂公主山莊應制', '侍宴安乐公主山莊應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["金輿玉輦背三條，水閣山樓望九霄。","野外初迷七聖道，河邊忽覩二靈橋。","懸冰滴滴依虬箭，清吹泠泠雜鳳簫。","回晚平陽歌舞合，前溪更轉木蘭橈。"]', '["金輿玉輦背三條，水閣山楼望九霄。","野外初迷七聖道，河邊忽覩二靈橋。","懸冰滴滴依虬箭，清吹泠泠杂鳳簫。","回晚平陽歌舞合，前溪更轉木蘭橈。"]', '诗', 'shi', '', NULL, '侍宴安樂公主山莊應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a102797-0a30-48c9-91c7-815b29fe5fe4', '奉和春日幸望春宮應制', '奉和春日幸望春宮應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["東城結宇敞千尋，北闕迴輿具四臨。","麗日祥煙承罕畢，輕荑弱草藉衣簪。","秦商重沓雲巖近，河渭縈紆霧壑深。","謬接鵷鴻陪賞樂，還欣魚鳥遂飛沈。"]', '["东城結宇敞千尋，北闕迴輿具四臨。","丽日祥煙承罕畢，轻荑弱草藉衣簪。","秦商重沓云巖近，河渭縈紆霧壑深。","謬接鵷鴻陪賞乐，還欣鱼鸟遂飞沈。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('791740b2-81d8-426a-b356-035e6f5ed5f1', '人日重宴大明宮恩賜綵縷人勝應制', '人日重宴大明宮恩賜綵縷人勝應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["詰旦行春上苑中，憑高却下大明宮。","千年執象寰瀛泰，七日爲人慶賞隆。","鐵鳳曾鶱搖瑞雪，銅烏細轉入祥風。","此時朝野歡無算，此歲雲天樂未窮。"]', '["詰旦行春上苑中，憑高却下大明宮。","千年執象寰瀛泰，七日爲人慶賞隆。","鐵鳳曾鶱搖瑞雪，銅烏細轉入祥风。","此时朝野歡無算，此歲云天乐未窮。"]', '诗', 'shi', '', NULL, '人日重宴大明宮恩賜綵縷人勝應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432cbb04-09a0-4e9e-9ae7-a56f73ce6fd9', '享龍池樂第八章', '享龙池乐第八章', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["星分邑里四人居，水洊源流萬頃餘。","魏國君王稱象處，晉家蕃邸化龍初。","青蒲暫似遊梁馬，綠藻還疑宴鎬魚。","自有神靈滋液地，年年雲物史官書。"]', '["星分邑里四人居，水洊源流万頃餘。","魏国君王稱象处，晉家蕃邸化龙初。","青蒲暫似游梁马，綠藻還疑宴鎬鱼。","自有神靈滋液地，年年云物史官书。"]', '诗', 'shi', '', NULL, '享龍池樂第八章 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5eea35b-0a38-45bf-be0c-d7227e227393', '奉和幸禮部尚書竇希玠宅應制', '奉和幸禮部尚书竇希玠宅應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["家住千門側，亭臨二水傍。","貴遊開北地，宸眷幸西鄉。","曳履迎中谷，鳴絲出後堂。","浦疑觀萬象，峰似駐三光。","草向瓊筵樂，花承繡扆香。","聖情思舊重，留飲賦雕章。"]', '["家住千门側，亭臨二水傍。","貴游开北地，宸眷幸西乡。","曳履迎中谷，鳴絲出後堂。","浦疑观万象，峰似駐三光。","草向瓊筵乐，花承繡扆香。","聖情思旧重，留饮賦雕章。"]', '诗', 'shi', '', NULL, '奉和幸禮部尚書竇希玠宅應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91b36c5-bb4d-4138-9c84-1a99929465d0', '奉和晦日幸昆明池應制', '奉和晦日幸昆明池應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["玉輅尋春賞，金堤重晦遊。","川通黑水浸，地派紫泉流。","晃朗扶桑出，綿聯杞樹周。","烏疑填海處，人似隔河秋。","劫盡灰猶識，年移石故留。","汀洲歸棹晚，簫鼓雜汾謳。"]', '["玉輅尋春賞，金堤重晦游。","川通黑水浸，地派紫泉流。","晃朗扶桑出，綿聯杞樹周。","烏疑填海处，人似隔河秋。","劫尽灰猶識，年移石故留。","汀洲归棹晚，簫鼓杂汾謳。"]', '诗', 'shi', '', NULL, '奉和晦日幸昆明池應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874a53f4-0e84-48aa-b541-6d9efa0214de', '奉和幸長安故城未央宮應制', '奉和幸长安故城未央宮應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["鳳輦乘春陌，龍山訪故臺。","北宮纔盡處，南斗獨昭回。","肆覽飛宸札，稱觴引御杯。","已觀蓬海變，誰厭柏梁災。","代挹孫通禮，朝稱賈誼才。","忝儕文雅地，先後各時來。"]', '["鳳輦乘春陌，龙山訪故台。","北宮纔尽处，南斗独昭回。","肆覽飞宸札，稱觴引御杯。","已观蓬海变，誰厭柏梁災。","代挹孫通禮，朝稱賈誼才。","忝儕文雅地，先後各时来。"]', '诗', 'shi', '', NULL, '奉和幸長安故城未央宮應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c95c95-7e52-464f-9dd2-34233f2eddb7', '陪幸韋嗣立山莊應制', '陪幸韋嗣立山莊應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["樞掖調梅暇，林園種槿初。","入朝榮劒履，退食偶琴書。","地隱東巖室，天迴北斗車。","旌門臨䆗窱，輦道屬扶疎。","雲罕明丹谷，霜笳徹紫虛。","水疑投石處，谿似釣璜餘。","帝澤頒巵酒，人歡頌里閭。","一承黃竹詠，長奉白茆居。"]', '["樞掖調梅暇，林园種槿初。","入朝榮劒履，退食偶琴书。","地隐东巖室，天迴北斗车。","旌门臨䆗窱，輦道屬扶疎。","云罕明丹谷，霜笳徹紫虛。","水疑投石处，谿似釣璜餘。","帝澤頒巵酒，人歡頌里閭。","一承黄竹詠，长奉白茆居。"]', '诗', 'shi', '', NULL, '陪幸韋嗣立山莊應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250f92d6-67d8-4383-96b8-c7fdb97067a0', '奉和幸望春宮送朔方軍大總管張仁亶', '奉和幸望春宮送朔方軍大總管張仁亶', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["邊郊草具腓，河塞有兵機。","上宰調梅寄，元戎細柳威。","武貔東道出，鷹隼北庭飛。","玉匣謀中野，金輿下太微。","投醪銜餞酌，緝衮事征衣。","勿謂公孫老，行聞奏凱歸。"]', '["邊郊草具腓，河塞有兵機。","上宰調梅寄，元戎細柳威。","武貔东道出，鷹隼北庭飞。","玉匣謀中野，金輿下太微。","投醪銜餞酌，緝衮事征衣。","勿謂公孫老，行闻奏凱归。"]', '诗', 'shi', '', NULL, '奉和幸望春宮送朔方軍大總管張仁亶 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5278f787-c0d0-48af-8821-a43a27b1f733', '奉和幸三會寺應制', '奉和幸三會寺應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["睿德總無邊，神臯擇勝緣。","二儀齊法駕，三會禮香筵。","漢闕中黃近，秦山太白連。","臺疑觀鳥日，池似刻鯨年。","滿月臨真境，秋風入御弦。","小臣叨下列，持管謬窺天。"]', '["睿德總無邊，神臯擇勝緣。","二儀齊法駕，三會禮香筵。","漢闕中黄近，秦山太白連。","台疑观鸟日，池似刻鯨年。","满月臨真境，秋风入御弦。","小臣叨下列，持管謬窺天。"]', '诗', 'shi', '', NULL, '奉和幸三會寺應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1124caea-f531-4e63-90f8-8a19f7f49681', '奉和幸大薦福寺', '奉和幸大薦福寺', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["象設隆新宇，龍潛想舊居。","碧樓披玉額，丹仗導金輿。","代日興光近，周星掩曜初。","空歌清沛筑，梵樂奏胡書。","帝造環三界，天文賁六虛。","康哉孝理日，崇德在真如。"]', '["象設隆新宇，龙潛想旧居。","碧楼披玉額，丹仗導金輿。","代日兴光近，周星掩曜初。","空歌清沛筑，梵乐奏胡书。","帝造环三界，天文賁六虛。","康哉孝理日，崇德在真如。"]', '诗', 'shi', '', NULL, '奉和幸大薦福寺 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7917ec7-c159-425a-bdfe-37c4e19f937a', '夏日都門送司馬員外逸客孫員外佺北征', '夏日都门送司马員外逸客孫員外佺北征', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["日逐滋南寇，天威撫北垂。","析珪行仗節，持印且分麾。","羽檄雙鳧去，兵車駟馬馳。","虎旗懸氣色，龍劍抱雄雌。","候月期戡翦，經時念別離。","坐聞關隴外，無復引弓兒。"]', '["日逐滋南寇，天威撫北垂。","析珪行仗節，持印且分麾。","羽檄雙鳧去，兵车駟马驰。","虎旗懸氣色，龙劍抱雄雌。","候月期戡翦，經时念別離。","坐闻关隴外，無复引弓兒。"]', '诗', 'shi', '', NULL, '夏日都門送司馬員外逸客孫員外佺北征 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8eb4cff-a052-4634-bb6a-1285a0f124fe', '元日恩賜柏葉應制', '元日恩賜柏葉應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["勁節凌冬勁，芳心待歲芳。","能令人益壽，非止麝含香。"]', '["勁節凌冬勁，芳心待歲芳。","能令人益壽，非止麝含香。"]', '诗', 'shi', '', NULL, '元日恩賜柏葉應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2012f4da-450a-4ae1-b949-989f9f57e7c2', '侍宴桃花園詠桃花應制', '侍宴桃花园詠桃花應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["綺蕚成蹊遍籞芳，紅英撲地滿筵香。","莫將秋宴傳王母，來比春華奉聖皇。"]', '["綺蕚成蹊遍籞芳，紅英撲地满筵香。","莫將秋宴傳王母，来比春华奉聖皇。"]', '诗', 'shi', '', NULL, '侍宴桃花園詠桃花應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89338671-f2fe-40e2-8689-b3f72618a6aa', '奉和三日祓禊渭濱', '奉和三日祓禊渭濱', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["上林花鳥暮春時，上巳陪遊樂在茲。","此日欣逢臨渭賞，昔年空道濟汾詞。"]', '["上林花鸟暮春时，上巳陪游乐在茲。","此日欣逢臨渭賞，昔年空道濟汾词。"]', '诗', 'shi', '', NULL, '奉和三日祓禊渭濱 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa296c2c-61c4-4d34-b2e4-cf511c9ac3ab', '奉和幸韋嗣立山莊侍宴應制', '奉和幸韋嗣立山莊侍宴應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["曲榭迴廊繞澗幽，飛泉噴下溢池流。","祗應感發明王夢，遂得邀迎聖帝遊。"]', '["曲榭迴廊繞澗幽，飞泉噴下溢池流。","祗應感發明王梦，遂得邀迎聖帝游。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍宴應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da37f3a0-2e60-4ff7-a46e-9041ebfc392b', '侍宴安樂公主新宅應制', '侍宴安乐公主新宅應制', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["牽牛南渡象昭回，學鳳樓成帝女來。","平旦鵷鸞歌舞席，方宵鸚鵡獻酬杯。"]', '["牽牛南渡象昭回，学鳳楼成帝女来。","平旦鵷鸾歌舞席，方宵鸚鵡獻酬杯。"]', '诗', 'shi', '', NULL, '侍宴安樂公主新宅應制 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb3bf7ec-e1ca-42e6-b22e-f95d3aae09f9', '餞唐永昌', '餞唐永昌', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["田郎才貌出咸京，潘子文華向洛城。","願以深心留善政，當令強項謝高名。"]', '["田郎才貌出咸京，潘子文华向洛城。","願以深心留善政，當令強項謝高名。"]', '诗', 'shi', '', NULL, '餞唐永昌 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11de58b1-2fe5-4e18-b2be-b4d062aa5d54', '九日幸臨渭亭登高應制得開字', '九日幸臨渭亭登高應制得开字', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["上月重陽滿，中天萬乘來。","萸依佩裏發，菊向酒邊開。","聖澤煙雲動，宸文象緯迴。","小臣無以荅，願奉億千杯。"]', '["上月重陽满，中天万乘来。","萸依佩裏發，菊向酒邊开。","聖澤煙云动，宸文象緯迴。","小臣無以荅，願奉億千杯。"]', '诗', 'shi', '', NULL, '九日幸臨渭亭登高應制得開字 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce559a1-f2f7-4b8a-b2e7-0dc48a07a002', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["化塔龍山起，中天鳳輦迂。","綵旒牽畫剎，雜珮冒香萸。","寶葉擎千座，金英漬百盂。","秋雲飄聖藻，霄極捧連珠。"]', '["化塔龙山起，中天鳳輦迂。","綵旒牽畫剎，杂珮冒香萸。","寶葉擎千座，金英漬百盂。","秋云飄聖藻，霄極捧連珠。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fd4790-64c5-45f5-bc89-e431bfc14af3', '宋主簿鳴臯夢趙六予未及報而陳子云亡今追爲此詩荅宋兼貽平昔遊舊', '宋主簿鳴臯梦趙六予未及報而陳子云亡今追爲此诗荅宋兼貽平昔游旧', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["暮川罕停波，朝雲無留色。","故人琴與詩，可存不可識。","識心尚可親，琴詩非故人。","鳴臯初夢趙，蜀國已悲陳。","感化傷淪滅，魂交惜未申。","冥期失幽報，茲理復今晨。","前嗟成後泣，已矣將何及。","舊感與新悲，虛懷酬昔時。","趙侯鴻寶氣，獨負青雲姿。","羣有含妙識，衆象懸清機。","雄談盡物變，精義解人頤。","在陰既獨善，幽躍自爲疑。","踠彼千里足，傷哉一尉欺。","陳生富清理，卓犖兼文史。","思縟巫山雲，調逸岷江水。","鏗鏘哀忠義，感激懷知己。","負劒登薊門，孤遊入燕市。","浩歌去京國，歸守西山趾。","幽居探元化，立言見千祀。","埋沒經濟情，良圖竟云已。","坐憶平生遊，十載懷嵩丘。","題書滿古壁，採藥遍巖幽。","子微化金鼎，仙笙不可求。","榮哉宋與陸，名宦美中州。","存亡一暌阻，岐路方悠悠。","自予事山海，及茲人世改。","傳聞當世榮，皆入古人名。","無復平原賦，空餘鄰笛聲。","泣對西州使，悲訪北邙塋。","新墳蔓宿草，舊闕毀殘銘。","爲君成此曲，因言寄友生。","默語無窮事，凋傷共此情。"]', '["暮川罕停波，朝云無留色。","故人琴與诗，可存不可識。","識心尚可親，琴诗非故人。","鳴臯初梦趙，蜀国已悲陳。","感化傷淪滅，魂交惜未申。","冥期失幽報，茲理复今晨。","前嗟成後泣，已矣將何及。","旧感與新悲，虛懷酬昔时。","趙侯鴻寶氣，独負青云姿。","羣有含妙識，衆象懸清機。","雄談尽物变，精義解人頤。","在陰既独善，幽躍自爲疑。","踠彼千里足，傷哉一尉欺。","陳生富清理，卓犖兼文史。","思縟巫山云，調逸岷江水。","鏗鏘哀忠義，感激懷知己。","負劒登薊门，孤游入燕市。","浩歌去京国，归守西山趾。","幽居探元化，立言见千祀。","埋沒經濟情，良圖竟云已。","坐憶平生游，十載懷嵩丘。","題书满古壁，採藥遍巖幽。","子微化金鼎，仙笙不可求。","榮哉宋與陸，名宦美中州。","存亡一暌阻，岐路方悠悠。","自予事山海，及茲人世改。","傳闻當世榮，皆入古人名。","無复平原賦，空餘鄰笛声。","泣对西州使，悲訪北邙塋。","新墳蔓宿草，旧闕毀殘銘。","爲君成此曲，因言寄友生。","默語無窮事，凋傷共此情。"]', '诗', 'shi', '', NULL, '宋主簿鳴臯夢趙六予未及報而陳子云亡今追爲此詩荅宋兼貽平昔遊舊 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5c5600-854d-4d08-af09-10e6593f0ace', '餞唐州高使君赴任', '餞唐州高使君赴任', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["餞酒臨豐樹，褰帷出魯陽。","蕙蘭春已晚，桐柏路猶長。","祖逖方城鎮，安期外氏鄉。","從來二千石，天子命唯良。"]', '["餞酒臨豐樹，褰帷出魯陽。","蕙蘭春已晚，桐柏路猶长。","祖逖方城鎮，安期外氏乡。","從来二千石，天子命唯良。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94ea0f5-1cbb-430b-8005-104bfb0ffb56', '餞許州宋司馬赴任', '餞許州宋司马赴任', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["國爲休徵選，輿因仲舉題。","山川襄野隔，朋酒灞亭暌。","零雨征軒騖，秋風別驥嘶。","驪歌一曲罷，愁望正淒淒。"]', '["国爲休徵選，輿因仲舉題。","山川襄野隔，朋酒灞亭暌。","零雨征軒騖，秋风別驥嘶。","驪歌一曲罷，愁望正淒淒。"]', '诗', 'shi', '', NULL, '餞許州宋司馬赴任 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de105dee-10c7-4431-9132-40100fd66753', '奉和立春遊苑迎春應制', '奉和立春游苑迎春應制', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["天遊龍輦駐城闉，上苑遲光晚更新。","瑤臺半入黃山路，玉檻傍臨玄霸津。","梅香欲待歌前落，蘭氣先過酒上春。","幸預柏臺稱獻壽，願陪千畝及農晨。"]', '["天游龙輦駐城闉，上苑遲光晚更新。","瑤台半入黄山路，玉檻傍臨玄霸津。","梅香欲待歌前落，蘭氣先過酒上春。","幸預柏台稱獻壽，願陪千畝及農晨。"]', '诗', 'shi', '', NULL, '奉和立春遊苑迎春應制 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b41bdad-7a93-4028-b579-5e19b73931fa', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["皇女璚臺天漢潯，星橋月宇構山林。","飛蘿半拂銀題影，瀑布環流玉砌陰。","菊浦香隨鸚鵡泛，簫樓韻逐鳳凰吟。","瑤池駐蹕恩方久，璧月無文興轉深。"]', '["皇女璚台天漢潯，星橋月宇構山林。","飞蘿半拂銀題影，瀑布环流玉砌陰。","菊浦香隨鸚鵡泛，簫楼韻逐鳳凰吟。","瑤池駐蹕恩方久，璧月無文兴轉深。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5c7c3b-ac0e-4150-9baa-c9b8fc2fc060', '夜宴安樂公主宅', '夜宴安乐公主宅', '2de705e9-df1b-4c89-8d19-ba7da48cb503', '唐', '["侯家主第一時新，上席華年不惜春。","珠釭綴日那知夜，玉斝流霞畏底晨。"]', '["侯家主第一时新，上席华年不惜春。","珠釭綴日那知夜，玉斝流霞畏底晨。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 盧藏用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db45ddd-88f7-4a02-9afa-2f0bd74749a7', '九月九日幸臨渭亭登高應制得涘字', '九月九日幸臨渭亭登高應制得涘字', 'c3ccce14-db50-4dbc-955d-82457c36c35e', '唐', '["重九開科曆，千齡逢聖紀。","爰豫矚秦坰，昇高臨灞涘。","玉醴浮仙菊，瓊筵薦芳芷。","一聞帝舜歌，歡娛良未已。"]', '["重九开科曆，千齡逢聖紀。","爰豫矚秦坰，昇高臨灞涘。","玉醴浮仙菊，瓊筵薦芳芷。","一闻帝舜歌，歡娛良未已。"]', '诗', 'shi', '', NULL, '九月九日幸臨渭亭登高應制得涘字 岑羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('addf6b4f-197c-43aa-bce3-4146ab380a68', '奉和九月九日登慈恩寺浮屠應制', '奉和九月九日登慈恩寺浮屠應制', 'c3ccce14-db50-4dbc-955d-82457c36c35e', '唐', '["寶臺聳天外，玉輦步雲端。","日麗重陽景，風搖季月寒。","梵堂遙集鴈，帝樂近翔鸞。","願獻延齡酒，長承湛露歡。"]', '["寶台聳天外，玉輦步云端。","日丽重陽景，风搖季月寒。","梵堂遙集鴈，帝乐近翔鸾。","願獻延齡酒，长承湛露歡。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮屠應制 岑羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b67fd9d-1da5-4f3e-9c2b-93a50b2eb317', '餞唐州高使君', '餞唐州高使君', 'c3ccce14-db50-4dbc-955d-82457c36c35e', '唐', '["蒼茫南塞地，明媚上春時。","目極傷千里，懷君不自持。","征車別岐路，斜日下崦嵫。","一歎軺軒阻，悠悠即所思。"]', '["蒼茫南塞地，明媚上春时。","目極傷千里，懷君不自持。","征车別岐路，斜日下崦嵫。","一歎軺軒阻，悠悠即所思。"]', '诗', 'shi', '', NULL, '餞唐州高使君 岑羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1cca902-ea39-4e7e-9d74-11516c22bb46', '奉和春日幸望春宮應制', '奉和春日幸望春宮應制', 'c3ccce14-db50-4dbc-955d-82457c36c35e', '唐', '["和風助律應韶年，清蹕乘高入望僊。","花笑鶯歌迎帝輦，雲披日霽俯皇川。","南山近壓仙樓上，北斗平臨御扆前。","一奉恩榮同鎬宴，空知率舞聽薰弦。"]', '["和风助律應韶年，清蹕乘高入望僊。","花笑鶯歌迎帝輦，云披日霽俯皇川。","南山近壓仙楼上，北斗平臨御扆前。","一奉恩榮同鎬宴，空知率舞听薰弦。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 岑羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606697de-45c2-462c-829a-f8b443879554', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', 'c3ccce14-db50-4dbc-955d-82457c36c35e', '唐', '["銀牓重樓出霧開，金輿步輦向天來。","泉聲迥入吹簫曲，山勢遙臨獻壽杯。","帝女含笑流飛電，乾文動色象昭回。","誠願北極拱堯日，微臣抃舞詠康哉。"]', '["銀牓重楼出霧开，金輿步輦向天来。","泉声迥入吹簫曲，山勢遙臨獻壽杯。","帝女含笑流飞電，乾文动色象昭回。","誠願北極拱堯日，微臣抃舞詠康哉。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 岑羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8db4b79-7a2c-43cf-96ec-6721b495a216', '夜宴安樂公主新宅', '夜宴安乐公主新宅', 'c3ccce14-db50-4dbc-955d-82457c36c35e', '唐', '["金牓重樓開夜扉，瓊筵愛客未言歸。","銜歡不覺銀河曙，盡醉那知玉漏稀。"]', '["金牓重楼开夜扉，瓊筵愛客未言归。","銜歡不覺銀河曙，尽醉那知玉漏稀。"]', '诗', 'shi', '', NULL, '夜宴安樂公主新宅 岑羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697cf483-287d-4001-86dc-63e62f421d24', '儀坤廟樂章二首 一', '儀坤廟乐章二首 一', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["陽靈配德，陰魄昭升。","堯壇鳳下，漢室龍興。","俔天作對，前旒是凝。","化行南國，道盛西陵。","造舟集灌，無德而稱。","我粢既潔，我醴既澄。","陰陰靈廟，光靈若憑。","德馨惟饗，孝思烝烝。"]', '["陽靈配德，陰魄昭升。","堯壇鳳下，漢室龙兴。","俔天作对，前旒是凝。","化行南国，道盛西陵。","造舟集灌，無德而稱。","我粢既潔，我醴既澄。","陰陰靈廟，光靈若憑。","德馨惟饗，孝思烝烝。"]', '诗', 'shi', '', NULL, '儀坤廟樂章二首 一 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f6b3aa-d7ed-4664-9a0e-63330bfc2c52', '儀坤廟樂章二首 二', '儀坤廟乐章二首 二', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["乾道既亨，坤元以貞。","肅雍攸在，輔佐斯成。","外睦九族，內光一庭。","克生睿哲，祚我休明。","欽若徽範，悠哉淑靈。","建茲清宮，於彼上京。","縮茅以獻，絜秬惟馨。","實受其福，斯乎億齡。"]', '["乾道既亨，坤元以貞。","肅雍攸在，輔佐斯成。","外睦九族，內光一庭。","克生睿哲，祚我休明。","欽若徽範，悠哉淑靈。","建茲清宮，於彼上京。","縮茅以獻，絜秬惟馨。","實受其福，斯乎億齡。"]', '诗', 'shi', '', NULL, '儀坤廟樂章二首 二 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c6c5dc-c1b3-4edf-8245-e24f38facc9b', '九日幸臨渭亭登高應制得曆字', '九日幸臨渭亭登高應制得曆字', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["暮節乘原野，宣遊俯崖壁。","秋登華實滿，氣嚴鷹隼擊。","仙菊含霜泛，聖藻臨雲錫。","願陪九九辰，長奉千千曆。"]', '["暮節乘原野，宣游俯崖壁。","秋登华實满，氣嚴鷹隼擊。","仙菊含霜泛，聖藻臨云錫。","願陪九九辰，长奉千千曆。"]', '诗', 'shi', '', NULL, '九日幸臨渭亭登高應制得曆字 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba33edea-2cb2-46a8-bb0d-e2f376408d13', '慈恩寺九日應制', '慈恩寺九日應制', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["寶宮星宿劫，香塔鬼神功。","王遊盛塵外，睿覽出區中。","日宇開初景，天詞掩大風。","微臣謝時菊，薄采入芳叢。"]', '["寶宮星宿劫，香塔鬼神功。","王游盛塵外，睿覽出區中。","日宇开初景，天词掩大风。","微臣謝时菊，薄采入芳叢。"]', '诗', 'shi', '', NULL, '慈恩寺九日應制 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1485bd4d-833c-4645-9d65-4df34eeea3df', '早春魚亭山', '早春鱼亭山', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["春氣動百草，紛榮時斷續。","白雲自高妙，裴回空山曲。","陽林花已紅，寒澗苔未綠。","伊余息人事，蕭寂無營欲。","客行雖云遠，翫之聊自足。"]', '["春氣动百草，紛榮时斷續。","白云自高妙，裴回空山曲。","陽林花已紅，寒澗苔未綠。","伊余息人事，蕭寂無營欲。","客行雖云远，翫之聊自足。"]', '诗', 'shi', '', NULL, '早春魚亭山 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2f687d-be09-4cb6-b503-d8e14ac6e8ec', '秋日還京陝西十里作', '秋日還京陝西十里作', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["驅車越陝郊，北顧臨大河。","隔河望鄉邑，秋風水增波。","西登咸陽途，日暮憂思多。","傅巖既紆鬱，首山亦嵯峨。","操築無昔老，採薇有遺歌。","客遊節回換，人生知幾何。"]', '["驱车越陝郊，北顧臨大河。","隔河望乡邑，秋风水增波。","西登咸陽途，日暮憂思多。","傅巖既紆鬱，首山亦嵯峨。","操築無昔老，採薇有遺歌。","客游節回換，人生知幾何。"]', '诗', 'shi', '', NULL, '秋日還京陝西十里作 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3713a59f-7659-4243-8c9c-b89e7d2c6620', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["天道寧殊俗，慈仁乃戢兵。","懷荒寄赤子，忍愛鞠蒼生。","月下瓊娥去，星分寶婺行。","關山馬上曲，相送不勝情。"]', '["天道寧殊俗，慈仁乃戢兵。","懷荒寄赤子，忍愛鞠蒼生。","月下瓊娥去，星分寶婺行。","关山马上曲，相送不勝情。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f686b3-963f-4162-885b-b8ea6b077698', '春日登樓野望', '春日登楼野望', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["憑軒聊一望，春色幾芬菲。","野外煙初合，樓前花正飛。","嬌鶯弄新響，斜日散餘暉。","誰忍孤遊客，言念獨依依。"]', '["憑軒聊一望，春色幾芬菲。","野外煙初合，楼前花正飞。","嬌鶯弄新响，斜日散餘暉。","誰忍孤游客，言念独依依。"]', '诗', 'shi', '', NULL, '春日登樓野望 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44786698-7126-4848-ad0f-d10fe8643fde', '餞許州宋司馬赴任', '餞許州宋司马赴任', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["令弟與名兄，高才振兩京。","別序聞鴻燕，離章動鶺鴒。","遠朋馳翰墨，勝地寫丹青。","風月相思夜，勞望潁川星。"]', '["令弟與名兄，高才振兩京。","別序闻鴻燕，離章动鶺鴒。","远朋驰翰墨，勝地寫丹青。","风月相思夜，勞望潁川星。"]', '诗', 'shi', '', NULL, '餞許州宋司馬赴任 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce57db7b-508f-4215-9b7e-687b108697b5', '奉和聖製春日幸望春宮應制', '奉和聖製春日幸望春宮應制', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["九春風景足林泉，四面雲霞敞御筵。","花鏤黃山繡作苑，草圖玄灞錦爲川。","飛觴競醉心迴日，走馬爭先眼著鞭。","喜奉仙遊歸路遠，直言行樂不言旋。"]', '["九春风景足林泉，四面云霞敞御筵。","花鏤黄山繡作苑，草圖玄灞錦爲川。","飞觴競醉心迴日，走马爭先眼著鞭。","喜奉仙游归路远，直言行乐不言旋。"]', '诗', 'shi', '', NULL, '奉和聖製春日幸望春宮應制 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06feb2e7-1b0c-4a40-a1ba-cdbef4611a4d', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["主家園囿極新規，帝郊遊豫奉天儀。","歡宴瑤臺鎬京集，賞賜銅山蜀道移。","曲閣交映金精板，飛花亂下珊瑚枝。","借問今朝八龍駕，何如昔日望仙池。"]', '["主家园囿極新規，帝郊游豫奉天儀。","歡宴瑤台鎬京集，賞賜銅山蜀道移。","曲閣交映金精板，飞花亂下珊瑚枝。","借问今朝八龙駕，何如昔日望仙池。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e058fa-f545-475e-9025-92262feaceaa', '秋朝覽鏡', '秋朝覽镜', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["客心驚落木，夜坐聽秋風。","朝日看容鬢，生涯在鏡中。"]', '["客心驚落木，夜坐听秋风。","朝日看容鬢，生涯在镜中。"]', '诗', 'shi', '', NULL, '秋朝覽鏡 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bab7bb-ed27-48c9-87d8-c92ad3c5427b', '夜宴安樂公主新宅', '夜宴安乐公主新宅', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["秦樓宴喜月裴回，妓筵銀燭滿庭開。","坐中香氣排花出，扇後歌聲逐酒來。"]', '["秦楼宴喜月裴回，妓筵銀燭满庭开。","坐中香氣排花出，扇後歌声逐酒来。"]', '诗', 'shi', '', NULL, '夜宴安樂公主新宅 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3fc9e8-8150-4f38-aab2-e04d9d82d608', '餞唐永昌', '餞唐永昌', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["河洛風煙壯市朝，送君飛鳧去漸遙。","更思明年桃李月，花紅柳綠宴浮橋。"]', '["河洛风煙壯市朝，送君飞鳧去漸遙。","更思明年桃李月，花紅柳綠宴浮橋。"]', '诗', 'shi', '', NULL, '餞唐永昌 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aaedd5d-f92c-4214-a9ba-981ec4670f6b', '九日幸臨渭亭登高應制得酒字', '九日幸臨渭亭登高應制得酒字', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["睿賞叶通三，宸遊契重九。","蘭將葉布席，菊用香浮酒。","落日下桑榆，秋風歇楊柳。","幸齊東戶慶，希薦南山壽。"]', '["睿賞叶通三，宸游契重九。","蘭將葉布席，菊用香浮酒。","落日下桑榆，秋风歇楊柳。","幸齊东戶慶，希薦南山壽。"]', '诗', 'shi', '', NULL, '九日幸臨渭亭登高應制得酒字 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a635c09-0e25-4b25-9817-d90768e21a8d', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["季月啓重陽，金輿陟寶坊。","御旗橫日道，仙塔儼雲莊。","帝蹕千官從，乾詞七曜光。","顧慙文墨職，無以頌時康。"]', '["季月啓重陽，金輿陟寶坊。","御旗橫日道，仙塔儼云莊。","帝蹕千官從，乾词七曜光。","顧慙文墨職，無以頌时康。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d2fe1b-a65c-4428-a5d6-b7a66b92a1d0', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["帝子今何去？重姻適異方。","離情愴宸掖，別路遶關梁。","望絕園中柳，悲纏陌上桑。","空餘願黃鶴，東顧憶迴翔。"]', '["帝子今何去？重姻適異方。","離情愴宸掖，別路遶关梁。","望絕园中柳，悲纏陌上桑。","空餘願黄鹤，东顧憶迴翔。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f4011a-af1a-46d3-889a-8291958d54ab', '餞許州宋司馬赴任', '餞許州宋司马赴任', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["潁川開郡邑，角宿分躔野。","君非仲舉才，誰是題輿者。","憫憫琴上鶴，蕭蕭路傍馬。","嚴程若可留，別袂希再把。"]', '["潁川开郡邑，角宿分躔野。","君非仲舉才，誰是題輿者。","憫憫琴上鹤，蕭蕭路傍马。","嚴程若可留，別袂希再把。"]', '诗', 'shi', '', NULL, '餞許州宋司馬赴任 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4257c5-7a2e-4422-9920-2bfafe7fa72a', '餞唐州高使君赴任', '餞唐州高使君赴任', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["外牧資賢守，斯人奉帝俞。","淮南膺建隼，渭北暫分符。","坐歎煙波隔，行嗟物候殊。","何年昇美課，迴首北城隅。"]', '["外牧資賢守，斯人奉帝俞。","淮南膺建隼，渭北暫分符。","坐歎煙波隔，行嗟物候殊。","何年昇美課，迴首北城隅。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a43d28-32ad-4fa2-ab8a-c13a092c21b8', '奉和立春遊苑迎春應制', '奉和立春游苑迎春應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["玄籥飛灰出洞房，青郊迎氣肇初陽。","仙輿暫下宜春苑，御醴行開薦壽觴。","映水輕苔猶隱綠，緣堤弱柳未舒黃。","唯有裁花飾簪鬢，恆隨聖藻狎年光。"]', '["玄籥飞灰出洞房，青郊迎氣肇初陽。","仙輿暫下宜春苑，御醴行开薦壽觴。","映水轻苔猶隐綠，緣堤弱柳未舒黄。","唯有裁花飾簪鬢，恆隨聖藻狎年光。"]', '诗', 'shi', '', NULL, '奉和立春遊苑迎春應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3abaf1-2a07-4351-8c69-4f3901e664c7', '奉和聖製春日幸望春宮應制', '奉和聖製春日幸望春宮應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["綵仗琱輿俯碧潯，行春御氣發皇心。","搖風細柳縈馳道，映日輕花出禁林。","遍野園亭開帟幕，連堤草樹狎衣簪。","謬參西掖霑堯酒，願沐南薰解舜琴。"]', '["綵仗琱輿俯碧潯，行春御氣發皇心。","搖风細柳縈驰道，映日轻花出禁林。","遍野园亭开帟幕，連堤草樹狎衣簪。","謬參西掖霑堯酒，願沐南薰解舜琴。"]', '诗', 'shi', '', NULL, '奉和聖製春日幸望春宮應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680ab466-cfc5-43f8-a68b-268c80d64137', '奉和人日讌大明宮恩賜綵縷人勝應制', '奉和人日讌大明宮恩賜綵縷人勝應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["日宇千門平旦開，天容萬象列昭回。","三陽候節金爲勝，百福迎祥玉作杯。","就暖風光偏著柳，辭寒雪影半藏梅。","何幸得參詞賦職，自憐終乏馬卿才。"]', '["日宇千门平旦开，天容万象列昭回。","三陽候節金爲勝，百福迎祥玉作杯。","就暖风光偏著柳，辞寒雪影半藏梅。","何幸得參词賦職，自怜終乏马卿才。"]', '诗', 'shi', '', NULL, '奉和人日讌大明宮恩賜綵縷人勝應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f83461d-c1ec-4c9d-b84f-411d40432bed', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["主家臺沼勝平陽，帝幸歡娛樂未央。","掩映琱窗交極浦，參差繡戶繞迴塘。","泉聲百處傳歌曲，樹影千重對舞行。","聖酒一霑何以報，唯欣頌德奉時康。"]', '["主家台沼勝平陽，帝幸歡娛乐未央。","掩映琱窗交極浦，參差繡戶繞迴塘。","泉声百处傳歌曲，樹影千重对舞行。","聖酒一霑何以報，唯欣頌德奉时康。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0691059d-30a9-4644-85c8-44595ec1b6c6', '興慶池侍宴應制', '兴慶池侍宴應制', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["積水逶迤繞直城，[含]虛皎鏡有餘清。","圖雲曲榭連緹幕，映日中塘間綵旌。","賞洽猶聞簫管沸，歡留更睹木蘭輕。","無勞海上尋仙客，即此蓬萊在帝京。"]', '["積水逶迤繞直城，[含]虛皎镜有餘清。","圖云曲榭連緹幕，映日中塘间綵旌。","賞洽猶闻簫管沸，歡留更睹木蘭轻。","無勞海上尋仙客，即此蓬萊在帝京。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea6e825-88dc-4019-bffb-371e2a274111', '夜宴安樂公主宅', '夜宴安乐公主宅', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["鳳樓䆗窱凌三襲，翠幌玲瓏瞰九衢。","複道中宵留宴衎，彌令上客想踟躕。"]', '["鳳楼䆗窱凌三襲，翠幌玲瓏瞰九衢。","複道中宵留宴衎，彌令上客想踟躕。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb411ba-9e03-4ce3-be1d-ed44e760275d', '餞唐永昌', '餞唐永昌', '7cb05f69-a1c5-40e9-8602-3491bb4f7f78', '唐', '["聞君出宰洛陽隅，賓友稱觴餞路衢。","別後相思在何處？祗應關下望仙鳧。"]', '["闻君出宰洛陽隅，賓友稱觴餞路衢。","別後相思在何处？祗應关下望仙鳧。"]', '诗', 'shi', '', NULL, '餞唐永昌 馬懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460577de-6930-4044-bded-11ae294f74d6', '明冰篇', '明冰篇', '54825d81-3b81-4dd0-9124-edb860e627d7', '唐', '["北陸蒼茫河海凝，南山闌干晝夜冰。","素彩峨峨明月升，深山窮谷不自見。","安知採斵備嘉薦，陰房涸冱掩寒扇。","陽春二月朝始暾，春光潭沱度千門。","明冰時出御至尊，彤庭赫赫九儀備。","腰玉煌煌千官事，明冰畢賦周在位。","憶昨沙漠寒風漲，崑崙長河冰始壯。","漫汗崚嶒積亭障，噰噰鳴雁江上來。","禁苑池臺冰復開，搖青涵綠映樓臺。","豳歌七月王風始，鑿冰藏用昭物軌，四時不忒千萬祀。"]', '["北陸蒼茫河海凝，南山闌干晝夜冰。","素彩峨峨明月升，深山窮谷不自见。","安知採斵備嘉薦，陰房涸冱掩寒扇。","陽春二月朝始暾，春光潭沱度千门。","明冰时出御至尊，彤庭赫赫九儀備。","腰玉煌煌千官事，明冰畢賦周在位。","憶昨沙漠寒风漲，崑崙长河冰始壯。","漫汗崚嶒積亭障，噰噰鳴雁江上来。","禁苑池台冰复开，搖青涵綠映楼台。","豳歌七月王风始，鑿冰藏用昭物軌，四时不忒千万祀。"]', '诗', 'shi', '', NULL, '明冰篇 富嘉謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfe09b51-dedd-4b27-b5d3-e024ce305dca', '長門怨', '长门怨', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["月出映層城，孤圓上太清。","君王眷愛歇，枕席涼風生。","怨咽不能寢，踟躕步前楹。","空階白露色，百草寒蟲鳴。","念昔金房裏，猶嫌玉座輕。","如何嬌所誤，長夜泣恩情。"]', '["月出映層城，孤圓上太清。","君王眷愛歇，枕席涼风生。","怨咽不能寢，踟躕步前楹。","空階白露色，百草寒蟲鳴。","念昔金房裏，猶嫌玉座轻。","如何嬌所誤，长夜泣恩情。"]', '诗', 'shi', '', NULL, '長門怨 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba80aac-e697-4ecd-9e2d-3cb097c00e08', '和崔侍御日用遊開化寺閣', '和崔侍御日用游开化寺閣', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["左憲多才雄，故人尤鷙鶚。","護贈單于使，休軺太原郭。","館次厭煩歊，清懷尋寂寞。","西緣十里餘，北上開化閣。","初入雲樹間，冥蒙未昭廓。","漸出欄榥外，萬里秋景焯。","歲晏風落山，天寒水歸壑。","覽物頌幽景，三乘動玄鑰。","但敷利解言，永用忘昏著。"]', '["左憲多才雄，故人尤鷙鶚。","護贈單于使，休軺太原郭。","館次厭煩歊，清懷尋寂寞。","西緣十里餘，北上开化閣。","初入云樹间，冥蒙未昭廓。","漸出欄榥外，万里秋景焯。","歲晏风落山，天寒水归壑。","覽物頌幽景，三乘动玄鑰。","但敷利解言，永用忘昏著。"]', '诗', 'shi', '', NULL, '和崔侍御日用遊開化寺閣 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8859355e-9c33-4bf6-814b-c6b44117ce0c', '哭富嘉謨', '哭富嘉謨', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["吾友適不死，於戲社稷臣。","直祿非造利，長懷大庇人。","乃通承明籍，遘此敦牂春。","藥厲其可畏，皇穹故匪仁。","疇昔與夫子，孰云異天倫。","同病一相失，茫茫不重陳。","子之文章在，其殆尼父新。","鼓興斡河岳，貞詞毒鬼神。","可悲不可朽，車輤沒荒榛。","聖主賢爲寶，吁茲大國貧。"]', '["吾友適不死，於戲社稷臣。","直祿非造利，长懷大庇人。","乃通承明籍，遘此敦牂春。","藥厲其可畏，皇穹故匪仁。","疇昔與夫子，孰云異天倫。","同病一相失，茫茫不重陳。","子之文章在，其殆尼父新。","鼓兴斡河岳，貞词毒鬼神。","可悲不可朽，车輤沒荒榛。","聖主賢爲寶，吁茲大国貧。"]', '诗', 'shi', '', NULL, '哭富嘉謨 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91007e81-f7c8-4b65-ad34-6b675260cafa', '過漢故城', '過漢故城', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["大漢昔未定，強秦猶擅場。","中原逐鹿罷，高祖鬱龍驤。","經始謀帝座，茲焉壯未央。","規模窺棟宇，表裏浚城隍。","羣后崇長樂，中朝增建章。","句陳被蘭錡，樂府奏芝房。","翡翠明珠帳，鴛鴦白玉堂。","清晨寶鼎食，閑夜鬱金香。","天馬來東道，佳人傾北方。","何其赫隆盛，自謂寶靈長。","歷數有時盡，哀平嗟不昌。","冰堅成巨猾，火德遂頹綱。","奧位匪虛校，貪天竟速亡。","魂神吁社稷，豹虎鬬巖廊。","金狄移灞岸，銅盤向洛陽。","君王無處所，年代幾荒涼。","宮闕誰家域，蓁蕪罥我裳。","井田唯有草，海水變爲桑。","昔在高門內，於今岐路傍。","餘基不可識，古墓列成行。","狐兔驚魍魎，鴟鳥嚇獝狂。","空城寒日晚，平野暮雲黃。","烈烈樊青棘，蕭蕭吹白楊。","千秋幷萬歲，空使詠歌傷。"]', '["大漢昔未定，強秦猶擅場。","中原逐鹿罷，高祖鬱龙驤。","經始謀帝座，茲焉壯未央。","規模窺棟宇，表裏浚城隍。","羣后崇长乐，中朝增建章。","句陳被蘭錡，乐府奏芝房。","翡翠明珠帳，鴛鴦白玉堂。","清晨寶鼎食，闲夜鬱金香。","天马来东道，佳人傾北方。","何其赫隆盛，自謂寶靈长。","歷數有时尽，哀平嗟不昌。","冰堅成巨猾，火德遂頹綱。","奧位匪虛校，貪天竟速亡。","魂神吁社稷，豹虎鬬巖廊。","金狄移灞岸，銅盤向洛陽。","君王無处所，年代幾荒涼。","宮闕誰家域，蓁蕪罥我裳。","井田唯有草，海水变爲桑。","昔在高门內，於今岐路傍。","餘基不可識，古墓列成行。","狐兔驚魍魎，鴟鸟嚇獝狂。","空城寒日晚，平野暮云黄。","烈烈樊青棘，蕭蕭吹白楊。","千秋幷万歲，空使詠歌傷。"]', '诗', 'shi', '', NULL, '過漢故城 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d4e416-1f13-41da-897b-7f5718a23836', '古意', '古意', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["洛陽芳樹向春開，洛陽女兒平旦來。","流車走馬紛相催，折芳瑤華向曲臺。","曲臺自有千萬行，重花累葉間垂楊。","北林朝日境明光，南國微風蘇合香。","可憐窈窕女，不作邯鄲娼。","妙舞輕迴拂長袖，高歌浩唱發清商。","歌終舞罷歡無極，樂往悲來長歎息。","陽春白日不少留，紅榮碧樹無顏色。","碧樹風花先春度，珠簾粉澤無人顧。","如何年少忽遲暮，坐見明月與白露。","明月白露夜已寒，香衣錦帶空珊珊。","今日陽春一妙曲，鳳皇樓上與君彈。"]', '["洛陽芳樹向春开，洛陽女兒平旦来。","流车走马紛相催，折芳瑤华向曲台。","曲台自有千万行，重花累葉间垂楊。","北林朝日境明光，南国微风蘇合香。","可怜窈窕女，不作邯鄲娼。","妙舞轻迴拂长袖，高歌浩唱發清商。","歌終舞罷歡無極，乐往悲来长歎息。","陽春白日不少留，紅榮碧樹無顏色。","碧樹风花先春度，珠簾粉澤無人顧。","如何年少忽遲暮，坐见明月與白露。","明月白露夜已寒，香衣錦带空珊珊。","今日陽春一妙曲，鳳皇楼上與君彈。"]', '诗', 'shi', '', NULL, '古意 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76047f2a-d0f6-457f-b380-35fe7284d4ee', '怨歌行', '怨歌行', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["城南有怨婦，含情傍芳叢。","自謂二八時，歌舞入漢宮。","皇恩數流眄，承幸玉堂中。","綠柏黃花催夜酒，錦衣羅袂逐春風。","建章西宮煥若神，燕趙美女三千人。","君王厭德不忘新，況羣豔冶紛來陳。","是時別君不再見，三十三春長信殿。","長信重門晝掩關，清房曉帳幽且閑。","綺窗蟲網氛塵色，文軒鶯對桃李顏。","天王貴宮不貯老，浩然含淚今來還。","自憐春色轉晚暮，試逐佳遊芳草路。","小腰麗女奪人奇，金鞍少年曾不顧。","歸來誰爲夫，請謝西家婦，莫辭先醉解羅襦。"]', '["城南有怨婦，含情傍芳叢。","自謂二八时，歌舞入漢宮。","皇恩數流眄，承幸玉堂中。","綠柏黄花催夜酒，錦衣羅袂逐春风。","建章西宮煥若神，燕趙美女三千人。","君王厭德不忘新，況羣豔冶紛来陳。","是时別君不再见，三十三春长信殿。","长信重门晝掩关，清房晓帳幽且闲。","綺窗蟲網氛塵色，文軒鶯对桃李顏。","天王貴宮不貯老，浩然含泪今来還。","自怜春色轉晚暮，試逐佳游芳草路。","小腰丽女奪人奇，金鞍少年曾不顧。","归来誰爲夫，請謝西家婦，莫辞先醉解羅襦。"]', '诗', 'shi', '', NULL, '怨歌行 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a031cf-0f72-4576-be02-62df9cda926d', '隴頭水', '隴头水', '036fa87c-42c8-4bb1-b325-6b9a50c4ccc7', '唐', '["路出金河道，山連玉塞門。","旌旗雲裏度，楊柳曲中喧。","喋血多壯膽，裹革無怯魂。","嚴霜斂曙色，大明辭朝暾。","塵銷營卒壘，沙靜都尉垣。","霧卷白山出，風吹黃葉翻。","將軍獻凱入，萬里絕河源。"]', '["路出金河道，山連玉塞门。","旌旗云裏度，楊柳曲中喧。","喋血多壯膽，裹革無怯魂。","嚴霜斂曙色，大明辞朝暾。","塵銷營卒壘，沙静都尉垣。","霧卷白山出，风吹黄葉翻。","將軍獻凱入，万里絕河源。"]', '诗', 'shi', '', NULL, '隴頭水 員半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8fe393-3b9b-438f-936b-2e72c643bf1b', '隴右途中遭非語', '隴右途中遭非語', '036fa87c-42c8-4bb1-b325-6b9a50c4ccc7', '唐', '["趙有兩毛遂，魯聞二曾參。","慈母猶且惑，況在行路心。","冠冕無醜士，賄賂成知己。","名利我所無，清濁誰見理。","敝服空逢春，緩帶不著身。","出遊非懷璧，何憂乎忌人。","正須自保愛，振衣出世塵。"]', '["趙有兩毛遂，魯闻二曾參。","慈母猶且惑，況在行路心。","冠冕無醜士，賄賂成知己。","名利我所無，清濁誰见理。","敝服空逢春，緩带不著身。","出游非懷璧，何憂乎忌人。","正須自保愛，振衣出世塵。"]', '诗', 'shi', '', NULL, '隴右途中遭非語 員半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf27e078-1669-4e63-a681-41d87d7b94d2', '儀坤廟樂章', '儀坤廟乐章', '036fa87c-42c8-4bb1-b325-6b9a50c4ccc7', '唐', '["孝享云畢，維徹有章。","雲感玄羽，風悽素商。","瞻望神座，祗戀匪遑。","禮終樂闋，肅雍鏘鏘。"]', '["孝享云畢，維徹有章。","云感玄羽，风悽素商。","瞻望神座，祗戀匪遑。","禮終乐闋，肅雍鏘鏘。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 員半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9cecb8a-54c8-440f-a3a4-a711202850bc', '銅雀妓', '銅雀妓', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["日暮銅雀迥，秋深玉座清。","蕭森松柏望，委鬱綺羅情。","君恩不再得，妾舞爲誰輕。"]', '["日暮銅雀迥，秋深玉座清。","蕭森松柏望，委鬱綺羅情。","君恩不再得，妾舞爲誰轻。"]', '诗', 'shi', '', NULL, '銅雀妓 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e773ef3-478a-4fe3-9a7c-a1ddd8a2caa7', '蜀中言懷', '蜀中言懷', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["獨坐年將暮，常懷志不通。","有時須問影，無事却書空。","棄置如天外，平生似夢中。","蓬心猶是客，華髪欲成翁。","跡滯魂逾窘，情乖路轉窮。","別離同夜月，愁思隔秋風。","老少悲顏駟，盈虛悟翟公。","時來不可問，何用求童蒙。"]', '["独坐年將暮，常懷志不通。","有时須问影，無事却书空。","棄置如天外，平生似梦中。","蓬心猶是客，华髪欲成翁。","跡滯魂逾窘，情乖路轉窮。","別離同夜月，愁思隔秋风。","老少悲顏駟，盈虛悟翟公。","时来不可问，何用求童蒙。"]', '诗', 'shi', '', NULL, '蜀中言懷 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c2bd65-0b20-4b61-8fe1-9c70b4e191c3', '古別離', '古別離', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["昔歲驚楊柳，高樓悲獨守。","今年芳樹枝，孤棲怨別離。","珠簾晝不捲，羅幔曉長垂。","苦調琴先覺，愁容鏡獨知。","頻年雁度無消息，罷却鴛文何用織。","夜還羅帳空有情，春著裙腰自無力。","青軒桃李落紛紛，紫庭蘭蕙日氛氳。","已能顦顇今如此，更復含情一待君。"]', '["昔歲驚楊柳，高楼悲独守。","今年芳樹枝，孤棲怨別離。","珠簾晝不捲，羅幔晓长垂。","苦調琴先覺，愁容镜独知。","頻年雁度無消息，罷却鴛文何用织。","夜還羅帳空有情，春著裙腰自無力。","青軒桃李落紛紛，紫庭蘭蕙日氛氳。","已能顦顇今如此，更复含情一待君。"]', '诗', 'shi', '', NULL, '古別離 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0042a9c3-0d24-4b44-9608-732348faecf0', '江上有懷', '江上有懷', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["湛湛江水見底清，荷花蓮子傍江生。","採蓮將欲寄同心，秋風落花空復情。","櫂歌數曲如有待，正見明月度東海。","海上雲盡月蒼蒼，萬里分輝滿洛陽。","洛陽閨閣夜何央，蛾眉嬋娟斷人腸。","寂寥金屏空自掩，青熒銀燭不生光。","應憐水宿洞庭子，今夕迢遙天一方。"]', '["湛湛江水见底清，荷花蓮子傍江生。","採蓮將欲寄同心，秋风落花空复情。","櫂歌數曲如有待，正见明月度东海。","海上云尽月蒼蒼，万里分輝满洛陽。","洛陽閨閣夜何央，蛾眉嬋娟斷人腸。","寂寥金屏空自掩，青熒銀燭不生光。","應怜水宿洞庭子，今夕迢遙天一方。"]', '诗', 'shi', '', NULL, '江上有懷 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d08d5e-6f13-45ed-8101-98ef0419e731', '江濱梅', '江濱梅', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["忽見寒梅樹，開花漢水濱。","不知春色早，疑是弄珠人。"]', '["忽见寒梅樹，开花漢水濱。","不知春色早，疑是弄珠人。"]', '诗', 'shi', '', NULL, '江濱梅 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65548834-51ec-42e7-b432-ba56a19cbfcb', '臨水亭', '臨水亭', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["高館基曾山，微冪生花草。","傍對野村樹，下臨車馬道。","清朗悟心術，幽遐備瞻討。","迴合峰隱雲，聯綿渚縈島。","氣似滄洲勝，風爲青春好。","相及盛年時，無令歎衰老。"]', '["高館基曾山，微冪生花草。","傍对野村樹，下臨车马道。","清朗悟心術，幽遐備瞻討。","迴合峰隐云，聯綿渚縈島。","氣似滄洲勝，风爲青春好。","相及盛年时，無令歎衰老。"]', '诗', 'shi', '', NULL, '臨水亭 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f06bc194-a7e1-4261-b917-b2a79f083986', '長門怨', '长门怨', '31bf2bf2-d924-4786-a1d0-29b816e34c36', '唐', '["煢煢孤思逼，寂寂長門夜。","妾妬亦知非，君恩那不借。","携琴就玉階，調悲聲未諧。","將心託明月，流影入君懷。"]', '["煢煢孤思逼，寂寂长门夜。","妾妬亦知非，君恩那不借。","携琴就玉階，調悲声未諧。","將心託明月，流影入君懷。"]', '诗', 'shi', '', NULL, '長門怨 齊澣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe78b47-8cb5-4763-8f7c-87662b26ccce', '長門怨', '长门怨', '31bf2bf2-d924-4786-a1d0-29b816e34c36', '唐', '["宮殿沈沈月欲分，昭陽更漏不堪聞。","珊瑚枕上千行淚，不是思君是恨君。"]', '["宮殿沈沈月欲分，昭陽更漏不堪闻。","珊瑚枕上千行泪，不是思君是恨君。"]', '诗', 'shi', '', NULL, '長門怨 齊澣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5045c7a4-8388-47d9-b8ad-516e255c2d4f', '儀坤廟樂章', '儀坤廟乐章', '8ad59a11-054b-466e-b28f-cd0e5fd04758', '唐', '["閟宮實實，清廟微微。","降格無象，馨香有依。","式昭纂慶，方融嗣徽。","明禋是享，神保聿歸。"]', '["閟宮實實，清廟微微。","降格無象，馨香有依。","式昭纂慶，方融嗣徽。","明禋是享，神保聿归。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 祝欽明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7509608-6faf-438f-ac08-22ab7889154a', '儀坤廟樂章', '儀坤廟乐章', '0536a467-982d-4f42-8c39-94abb9d9dfe1', '唐', '["妙算申帷幄，神謀出廟廷。","兩階文物備，七德武功成。","校獵長楊苑，屯軍細柳營。","將軍獻凱入，歌舞溢重城。"]', '["妙算申帷幄，神謀出廟廷。","兩階文物備，七德武功成。","校獵长楊苑，屯軍細柳營。","將軍獻凱入，歌舞溢重城。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 劉知幾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('660de777-d35e-41d3-8996-a950d35f3fd3', '儀坤廟樂章', '儀坤廟乐章', '25f72364-480f-45a5-aeec-01e9ed89d8c7', '唐', '["送文迎武遞參差，一始一終光聖儀。","四海生人歌有慶，千齡孝享肅無虧。"]', '["送文迎武遞參差，一始一終光聖儀。","四海生人歌有慶，千齡孝享肅無虧。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 胡雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58db30dd-65ce-4698-9114-768e30a701d4', '儀坤廟樂章', '儀坤廟乐章', 'fd3d1662-6b7e-4c60-a102-9bffc98656cb', '唐', '["祼圭既濯，鬱鬯既陳。","畫幕雲舉，黃流玉醇。","儀充獻酌，禮盛衆禋。","地察惟孝，愉焉饗親。"]', '["祼圭既濯，鬱鬯既陳。","畫幕云舉，黄流玉醇。","儀充獻酌，禮盛衆禋。","地察惟孝，愉焉饗親。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 張齊賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba397c45-7777-4d86-838d-9863589f93d6', '儀坤廟樂章', '儀坤廟乐章', '07bae2f9-1645-4621-b8d0-e19ed8a0acc6', '唐', '["酌鬱既灌，取蕭方爇。","籩豆靜器，簠簋芬飶。","魚腊薦美，牲牷表絜。","是戢是將，載迎載列。"]', '["酌鬱既灌，取蕭方爇。","籩豆静器，簠簋芬飶。","鱼腊薦美，牲牷表絜。","是戢是將，載迎載列。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 鄭善玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aafe3eb-8091-43c2-ac6d-203e85b35862', '儀坤廟樂章', '儀坤廟乐章', '2990ca26-1740-4f96-aadd-e38086471bc1', '唐', '["孝哉我后，沖乎廻聖。","道映重華，德輝文命。","慕深視篋，情殷撫鏡。","萬國移命，兆人承慶。"]', '["孝哉我后，沖乎廻聖。","道映重华，德輝文命。","慕深視篋，情殷撫镜。","万国移命，兆人承慶。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 丘悅 shi');
